bool goldenBallOwned() {
  return SinnohExpedition::goldenBallUnlocked(
      gameSave.gymProgress, gameSave.sinnoh);
}

uint8_t activeUiThemeId() {
  return static_cast<uint8_t>(selectedUiTheme());
}

uint16_t pokeBallQuantity(PokeBallType ball) {
  if (isInfinitePokeBall(ball)) return goldenBallOwned() ? 1U : 0U;
  const uint8_t id = static_cast<uint8_t>(ball);
  return isStoredPokeBall(ball) ? gameSave.inventory.balls[id] : 0U;
}

uint16_t battleItemQuantity(BattleItem item) {
  const uint8_t id=static_cast<uint8_t>(item);
  if(item==BattleItem::RareCandy)
    return gameSave.inventory.heldItems[kRareCandyInventorySlot];
  if(isPpInventoryItem(item)){
    const uint8_t index=ppInventoryIndex(item);
    return index<kPpItemCount?gameSave.ppItems.quantities[index]:0U;
  }
  return id<kStandardMedicineCount?gameSave.inventory.medicine[id]:0U;
}

bool consumeBattleItem(BattleItem item) {
  const uint8_t id=static_cast<uint8_t>(item);
  if(item==BattleItem::RareCandy){
    uint16_t& quantity=gameSave.inventory.heldItems[kRareCandyInventorySlot];
    if(!quantity)return false;--quantity;return true;
  }
  if(isPpInventoryItem(item)){
    const uint8_t index=ppInventoryIndex(item);
    if(index>=kPpItemCount||!gameSave.ppItems.quantities[index])return false;
    --gameSave.ppItems.quantities[index];return true;
  }
  if(id>=kStandardMedicineCount||!gameSave.inventory.medicine[id])return false;
  --gameSave.inventory.medicine[id];return true;
}

bool itemNeedsMoveTarget(BattleItem item) {
  return item==BattleItem::Ether||item==BattleItem::MaxEther||item==BattleItem::PpUp;
}

uint8_t normalizeInventoryPage(uint8_t page) { return page < kInventoryPocketCount ? page : kBallPocket; }
uint8_t previousInventoryPage(uint8_t page) {
  page = normalizeInventoryPage(page);
  return page == kBallPocket ? static_cast<uint8_t>(kInventoryPocketCount - 1U)
                             : static_cast<uint8_t>(page - 1U);
}
uint8_t nextInventoryPage(uint8_t page) {
  page = normalizeInventoryPage(page);
  return page + 1U < kInventoryPocketCount ? static_cast<uint8_t>(page + 1U) : kBallPocket;
}
uint8_t normalizeBattleBagPage(uint8_t page) { return page <= kMedicinePocket ? page : kBallPocket; }
uint8_t previousBattleBagPage(uint8_t page) {
  return normalizeBattleBagPage(page) == kBallPocket ? kMedicinePocket : kBallPocket;
}
uint8_t nextBattleBagPage(uint8_t page) {
  return normalizeBattleBagPage(page) == kMedicinePocket ? kBallPocket : kMedicinePocket;
}

// The normal Bag deliberately contains only things the player owns.  This is
// separate from the battle Bag, which intentionally exposes only items that
// are legal during the current battle.
uint8_t inventoryEntries(InventoryEntry* entries, uint8_t capacity) {
  uint8_t total = 0, count = 0;
  const auto add = [&](InventoryEntryKind kind, uint16_t id) {
    if (total++ < inventoryListOffset) return;
    if (count < capacity) entries[count++] = {kind, id};
  };
  if (bagPage == kBallPocket) {
    for (uint8_t id = 0; id < static_cast<uint8_t>(PokeBallType::Count); ++id)
      if (pokeBallQuantity(static_cast<PokeBallType>(id)))
        add(InventoryEntryKind::Ball, id);
  } else if (bagPage == kMedicinePocket) {
    for (uint8_t id = 0; id < static_cast<uint8_t>(BattleItem::Count); ++id)
      if (battleItemQuantity(static_cast<BattleItem>(id)) &&
          !(inventoryBattleContext&&(static_cast<BattleItem>(id)==BattleItem::PpUp||
                                     static_cast<BattleItem>(id)==BattleItem::RareCandy)))
        add(InventoryEntryKind::Medicine, id);
  } else if (bagPage == kHeldPocket) {
    for (uint8_t id = 1; id < kHeldItemInventorySlots; ++id)
      if (gameSave.inventory.heldItems[id]) add(InventoryEntryKind::Held, id);
    if(gameSave.ownedMachines&kMegaStoneOwnershipBit)
      add(InventoryEntryKind::Held,static_cast<uint8_t>(HeldItem::MegaStone));
    for(uint8_t id=static_cast<uint8_t>(HeldItem::MegaStone)+1U;
        id<static_cast<uint8_t>(HeldItem::Count);++id)
      if(specialHeldItemQuantity(gameSave.specialHeldItems,static_cast<HeldItem>(id)))
        add(InventoryEntryKind::Held,id);
    for(uint8_t id=static_cast<uint8_t>(kFirstGen4UniqueItem);
        id<=static_cast<uint8_t>(kLastGen4UniqueItem);++id)
      if(gen4UniqueItemQuantity(gameSave.gen4UniqueItems,static_cast<HeldItem>(id)))
        add(InventoryEntryKind::Held,id);
    for(uint8_t id=static_cast<uint8_t>(kFirstGen5Drive);
        id<=static_cast<uint8_t>(kLastGen5Drive);++id)
      if(gen5DriveQuantity(gameSave.gen5UniqueItems,static_cast<HeldItem>(id)))
        add(InventoryEntryKind::Held,id);
  } else if (bagPage == kMachinePocket) {
    for (uint16_t id = 0; id < kMachineCount; ++id)
      if (ownsMachine(id)) add(InventoryEntryKind::Machine, id);
  } else if (bagPage == kEggPocket) {
    for(uint8_t id=0;id<gameSave.eggInventory.count;++id)
      add(InventoryEntryKind::Egg,id);
  }
  return count;
}

uint8_t inventoryTotalEntries() {
  uint8_t total = 0;
  if (bagPage == kBallPocket) {
    for (uint8_t id=0;id<static_cast<uint8_t>(PokeBallType::Count);++id)
      if(pokeBallQuantity(static_cast<PokeBallType>(id)))++total;
  } else if (bagPage == kMedicinePocket) {
    for (uint8_t id=0;id<static_cast<uint8_t>(BattleItem::Count);++id)
      if(battleItemQuantity(static_cast<BattleItem>(id))&&
         !(inventoryBattleContext&&(static_cast<BattleItem>(id)==BattleItem::PpUp||
                                    static_cast<BattleItem>(id)==BattleItem::RareCandy)))++total;
  } else if (bagPage == kHeldPocket) {
    for (uint8_t id=1;id<kHeldItemInventorySlots;++id) if(gameSave.inventory.heldItems[id]) ++total;
    if(gameSave.ownedMachines&kMegaStoneOwnershipBit)++total;
    for(uint8_t id=static_cast<uint8_t>(HeldItem::MegaStone)+1U;
        id<static_cast<uint8_t>(HeldItem::Count);++id)
      if(specialHeldItemQuantity(gameSave.specialHeldItems,static_cast<HeldItem>(id)))++total;
    for(uint8_t id=static_cast<uint8_t>(kFirstGen4UniqueItem);
        id<=static_cast<uint8_t>(kLastGen4UniqueItem);++id)
      if(gen4UniqueItemQuantity(gameSave.gen4UniqueItems,static_cast<HeldItem>(id)))++total;
    for(uint8_t id=static_cast<uint8_t>(kFirstGen5Drive);
        id<=static_cast<uint8_t>(kLastGen5Drive);++id)
      if(gen5DriveQuantity(gameSave.gen5UniqueItems,static_cast<HeldItem>(id)))++total;
  } else if (bagPage == kMachinePocket) {
    for (uint16_t id=0;id<kMachineCount;++id) if(ownsMachine(id)) ++total;
  } else if (bagPage == kEggPocket) {
    total=gameSave.eggInventory.count;
  }
  return total;
}

InventoryEntry selectedInventoryEntry() {
  InventoryEntry entries[5]{};
  const uint8_t count = inventoryEntries(entries, 5);
  if (!count) return {};
  if (inventorySelection >= count) inventorySelection = 0;
  return entries[inventorySelection];
}

