uint8_t reconcileRegionCompletionRewards() {
  bool gymLedgerChanged = false;
  uint8_t granted = GymSystem::reconcileRegionCompletionRewards(
      gameSave.gymProgress, gameSave.inventory, &gymLedgerChanged);
  const SinnohExpedition::CompletionReward reward =
      SinnohExpedition::reconcileCompletionReward(
          gameSave.sinnoh, gameSave.inventory);
  if (reward.platinumThemeUnlocked)
    sinnohNotice[55] = static_cast<char>(
        static_cast<uint8_t>(sinnohNotice[55]) | 0x01U);
  if (reward.masterBallGranted) {
    sinnohNotice[55] = static_cast<char>(
        static_cast<uint8_t>(sinnohNotice[55]) | 0x02U);
    granted = static_cast<uint8_t>(granted | (1U << 3U));
  }
  if (UnovaAdventure::reconcileCompletionReward(
          gameSave.unova, gameSave.inventory))
    granted = static_cast<uint8_t>(granted | (1U << 4U));
  if (KalosAdventure::reconcileCompletionReward(
          gameSave.kalos, gameSave.inventory))
    granted = static_cast<uint8_t>(granted | (1U << 5U));
  // Sinnoh has its established dedicated notice byte. Queue the other five
  // regions for Home when reconciliation did not happen inside battle flow.
  regionalMasterBallNoticeMask = static_cast<uint8_t>(
      regionalMasterBallNoticeMask | (granted & static_cast<uint8_t>(~(1U << 3U))));
  if (!gymLedgerChanged && !reward.platinumThemeUnlocked &&
      !reward.masterBallGranted && !granted)
    return 0U;
  saveDirty = true;
  saveNow();
  return granted;
}

void normalizeSettings() {
  gameSave.settings.homeBackground = HomeBackgrounds::normalize(gameSave.settings.homeBackground);
#if !defined(POKEGOCHI_ANDROID)
  // Bits 2..3 were unused before battle speed reached the physical device.
  // Preserve the established ESP32 1x pace on an upgraded save; once the
  // player chooses a speed, all three values have an explicit encoding.
  if ((gameSave.settings.screenTimeoutIndex &
       UserSettings::kBattleSpeedMask) == 0U) {
    gameSave.settings.setBattleSpeedMultiplier(1U);
    saveDirty = true;
  }
#endif
  // The retired Map Maker bytes remain in the frozen save layout only for
  // backward compatibility. Never let an older active slot affect the Home.
  gameSave.creativeBackgrounds.activeSlot = 0xFF;
  gameSave.settings.setColorTheme(gameSave.settings.colorTheme());
  if (gameSave.settings.colorTheme() == UiColorTheme::Platinum &&
      !SinnohExpedition::platinumThemeUnlocked(gameSave.sinnoh))
    gameSave.settings.setColorTheme(UiColorTheme::Sapphire);
  if (!UnovaAdventure::white2ThemeUnlocked(gameSave.unova))
    UnovaAdventure::setWhite2ThemeSelected(gameSave.unova, false);
  if (!KalosAdventure::xThemeUnlocked(gameSave.kalos))
    KalosAdventure::setXThemeSelected(gameSave.kalos, false);
  else if (KalosAdventure::xThemeSelected(gameSave.kalos))
    UnovaAdventure::setWhite2ThemeSelected(gameSave.unova, false);
  gameSave.settings.setTouchInputMode(gameSave.settings.touchInputMode());
  if (gameSave.settings.brightnessPercent < 20 || gameSave.settings.brightnessPercent > 100)
    gameSave.settings.brightnessPercent = 80;
  gameSave.settings.brightnessPercent = static_cast<uint8_t>((gameSave.settings.brightnessPercent / 20U) * 20U);
  if (gameSave.settings.screenTimeout() >= kScreenTimeoutCount)
    gameSave.settings.setScreenTimeout(1);
}

const char* screenTimeoutLabel(uint8_t index) {
  static constexpr const char* labels[kScreenTimeoutCount] = {"1 MIN", "2 MIN", "5 MIN", "10 MIN"};
  return labels[index < kScreenTimeoutCount ? index : 1];
}

bool inside(const TouchPoint& p, int16_t x, int16_t y, int16_t w, int16_t h) {
  // Keep hit boxes almost identical to their painted bounds. Expanding every
  // control by five pixels made neighbouring FireRed controls overlap and a
  // physically correct tap could be claimed by the wrong button.
  const int16_t tolerance = gameSaveStorage &&
      gameSave.settings.touchInputMode() == TouchInputMode::Stylus ? 1 : 3;
  return p.x >= x - tolerance && p.x < x + w + tolerance &&
         p.y >= y - tolerance && p.y < y + h + tolerance;
}

// Generation III derives gender from the low personality byte and the
// species threshold. Keep it presentation-only: the same immutable
// personality already drives Attract and remains persisted in every save.
int8_t displayedPokemonGender(const OwnedPokemon& pokemon) {
  const SpeciesData* species = findSpecies(pokemon.speciesId);
  if (!species || species->genderRatio == 255U) return -1;  // genderless
  if (species->genderRatio == 0U) return 0;                 // male
  if (species->genderRatio == 254U) return 1;               // female
  return static_cast<uint8_t>(pokemon.personality & 0xFFU) < species->genderRatio ? 1 : 0;
}

// FireRed's font table stores gender as dedicated control glyphs rather than
// normal text. Draw their tiny pixel geometry directly so no '?' placeholder
// appears and the symbols stay legible on the 2.8-inch panel.
void drawPokemonGenderSymbol(const OwnedPokemon& pokemon, int16_t centerX, int16_t centerY) {
  const int8_t gender = displayedPokemonGender(pokemon);
  if (gender < 0) return;
  const uint16_t color = gender == 1 ? TFT_RED : TFT_BLUE;
  display.drawCircle(centerX, centerY, 3, color);
  display.drawCircle(centerX, centerY, 2, color);
  if (gender == 1) {
    display.drawFastVLine(centerX, centerY + 3, 5, color);
    display.drawFastHLine(centerX - 2, centerY + 6, 5, color);
  } else {
    display.drawLine(centerX + 2, centerY - 2, centerX + 6, centerY - 6, color);
    display.drawFastHLine(centerX + 3, centerY - 6, 4, color);
    display.drawFastVLine(centerX + 6, centerY - 6, 4, color);
  }
}

void button(int16_t x, int16_t y, int16_t w, int16_t h, const char* label, uint16_t color) {
  display.fillRoundRect(x, y, w, h, 6, color); display.drawRoundRect(x, y, w, h, 6, TFT_WHITE);
  // The asset-derived FireRed font has no '<' or '>' glyphs. Keep navigation
  // controls graphical everywhere (Bag, Trainer Card and Settings) instead
  // of rendering a misleading question mark on the real display.
  if (label && std::strcmp(label, "<") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w / 2 - 8, cy, x + w / 2 + 6, cy - 8,
                         x + w / 2 + 6, cy + 8, TFT_WHITE);
    return;
  }
  if (label && std::strcmp(label, ">") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w / 2 + 8, cy, x + w / 2 - 6, cy - 8,
                         x + w / 2 - 6, cy + 8, TFT_WHITE);
    return;
  }
  // Compound navigation labels used to fall through to the FireRed font,
  // whose missing angle-bracket glyph is rendered as '?'. Draw the arrow
  // directly and send only the supported word through the font.
  if (label && label[0] == '<' && label[1] == ' ') {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + 8, cy, x + 20, cy - 7, x + 20, cy + 7, TFT_WHITE);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawStringFitted(label + 2, x + w / 2 + 8, cy,
                                 std::max<int16_t>(1, w - 30), 1);
    fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  const size_t labelLength = label ? std::strlen(label) : 0U;
  if (label && labelLength > 2U && label[labelLength - 2U] == ' ' &&
      label[labelLength - 1U] == '>') {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w - 8, cy, x + w - 20, cy - 7,
                         x + w - 20, cy + 7, TFT_WHITE);
    char text[32]{};
    const size_t textLength = std::min<size_t>(labelLength - 2U, sizeof(text) - 1U);
    std::memcpy(text, label, textLength);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawStringFitted(text, x + w / 2 - 8, cy,
                                 std::max<int16_t>(1, w - 30), 1);
    fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  if (label && std::strcmp(label, "< PREV") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + 8, cy, x + 20, cy - 7, x + 20, cy + 7, TFT_WHITE);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("PREV", x + w / 2 + 8, cy, 1); fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  if (label && std::strcmp(label, "NEXT >") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w - 8, cy, x + w - 20, cy - 7, x + w - 20, cy + 7, TFT_WHITE);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("NEXT", x + w / 2 - 8, cy, 1); fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted(label, x + w / 2, y + h / 2,
                               std::max<int16_t>(1, w - 4), 2);
  fireRedText.setTextDatum(TL_DATUM);
}

void outlinedButtonLabel(const char* label, int16_t centerX, int16_t centerY,
                         int16_t maxWidth, uint16_t foreground = TFT_WHITE) {
  if (!label || !label[0]) return;
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(TFT_BLACK);
  for (int8_t offsetY = -1; offsetY <= 1; ++offsetY) {
    for (int8_t offsetX = -1; offsetX <= 1; ++offsetX) {
      if (!offsetX && !offsetY) continue;
      fireRedText.drawStringFitted(label, centerX + offsetX, centerY + offsetY,
                                   std::max<int16_t>(1, maxWidth - 2), 2);
    }
  }
  fireRedText.setTextColor(foreground);
  fireRedText.drawStringFitted(label, centerX, centerY,
                               std::max<int16_t>(1, maxWidth - 2), 2);
  fireRedText.setTextDatum(TL_DATUM);
}

void bar(int16_t x, int16_t y, const char* label, uint16_t value, uint16_t maximum, uint16_t color) {
  fireRedText.setTextColor(TFT_WHITE, TFT_BLACK); fireRedText.drawStringFitted(label, x, y, 40, 1);
  display.drawRect(x + 42, y, 94, 9, TFT_DARKGREY);
  const uint16_t width = maximum ? static_cast<uint16_t>(88U * value / maximum) : 0;
  display.fillRect(x + 45, y + 2, width, 5, color);
}

uint16_t speciesColor(uint16_t id) {
  if (id == 1 || id == 10) return TFT_GREEN;
  if (id == 4) return TFT_ORANGE;
  if (id == 7) return TFT_CYAN;
  if (id == 13) return TFT_YELLOW;
  if (id == 16) return TFT_LIGHTGREY;
  return TFT_MAGENTA;
}

enum class PokemonAssetView : uint8_t { Front, Back, Icon };

void pokemonAssetPath(char* path, size_t size, const OwnedPokemon& pokemon,
                      PokemonAssetView view, uint8_t frame = 0,
                      uint16_t displayedSpecies = 0) {
  const uint16_t species = displayedSpecies ? displayedSpecies : pokemon.speciesId;
  const char* shiny = pokemon.shiny ? "shiny/" : "";
  const MegaVariant mega=MegaEvolution::variantFor(pokemon);
  if(mega!=MegaVariant::None&&species==pokemon.speciesId){
    const MegaFormData* megaForm=MegaEvolution::formData(species,mega);
    if(megaForm){
      if(view==PokemonAssetView::Icon)
        std::snprintf(path,size,"/pokegochi/assets/pokemon/forms/mega/%03u/%s/%sicons/%u.pkg",
                      species,megaForm->assetVariant,shiny,static_cast<unsigned>(frame&1U));
      else
        std::snprintf(path,size,"/pokegochi/assets/pokemon/forms/mega/%03u/%s/%s%s.pkg",
                      species,megaForm->assetVariant,shiny,
                      view==PokemonAssetView::Back?"back":"front");
      return;
    }
  }
  // A real Unown is tied to its personality-derived form. If another species
  // is merely being presented as Unown through Transform, BattleEngine has
  // copied the target's explicit form byte into that battler as well.
  if (species == 201) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 27U);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/unown/%02u/%sicons/%u.pkg",
                    form, shiny, static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/unown/%02u/%s%s.pkg",
                    form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 386) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 3U);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/deoxys/%u/%sicons/%u.pkg",
                    form, shiny, static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/deoxys/%u/%s%s.pkg",
                    form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 412U || species == 413U ||
      species == 422U || species == 423U) {
    const uint8_t form = CollectionLogic::resolvedForm(pokemon);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size,
                    "/pokegochi/assets/pokemon/forms/sinnoh/%03u/%u/%sicons/%u.pkg",
                    species, static_cast<unsigned>(form), shiny,
                    static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size,
                    "/pokegochi/assets/pokemon/forms/sinnoh/%03u/%u/%s%s.pkg",
                    species, static_cast<unsigned>(form), shiny,
                    view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 479 || species == 487 || species == 492) {
    const uint8_t form = CollectionLogic::resolvedForm(pokemon);
    const char* family = species == 479 ? "rotom" : species == 487 ? "giratina" : "shaymin";
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/%s/%u/%sicons/%u.pkg",
                    family, static_cast<unsigned>(form), shiny,
                    static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/%s/%u/%s%s.pkg",
                    family, static_cast<unsigned>(form), shiny,
                    view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 493) {
    // Arceus' Multitype sprite is driven by its held Plate. The resolved form
    // is shared by Home, Summary, Box and battle so changing the item never
    // leaves a stale Normal/placeholder sprite in one of those screens.
    const uint8_t form = CollectionLogic::resolvedForm(pokemon);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/arceus/%u/%sicons/%u.pkg",
                    static_cast<unsigned>(form), shiny,
                    static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/arceus/%u/%s%s.pkg",
                    static_cast<unsigned>(form), shiny,
                    view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 351 && view != PokemonAssetView::Icon && pokemon.form) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 3U);
    std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/castform/%u/%s%s.pkg",
                  form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 550U || species == 555U || species == 585U ||
      species == 586U || species == 641U || species == 642U ||
      species == 645U || species == 646U || species == 647U ||
      species == 648U || species == 649U) {
    const uint8_t form = CollectionLogic::resolvedForm(pokemon);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size,
                    "/pokegochi/assets/pokemon/forms/unova/%03u/%u/%sicons/%u.pkg",
                    species, static_cast<unsigned>(form), shiny,
                    static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size,
                    "/pokegochi/assets/pokemon/forms/unova/%03u/%u/%s%s.pkg",
                    species, static_cast<unsigned>(form), shiny,
                    view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if(species==666U||(species>=669U&&species<=671U)||species==676U||
     species==678U||species==681U||species==710U||species==711U||
     species==716U||species==718U||species==720U){
    const uint8_t form=CollectionLogic::resolvedForm(pokemon);
    if(view==PokemonAssetView::Icon)
      std::snprintf(path,size,
                    "/pokegochi/assets/pokemon/forms/kalos/%03u/%u/%sicons/%u.pkg",
                    species,static_cast<unsigned>(form),shiny,
                    static_cast<unsigned>(frame&1U));
    else
      std::snprintf(path,size,
                    "/pokegochi/assets/pokemon/forms/kalos/%03u/%u/%s%s.pkg",
                    species,static_cast<unsigned>(form),shiny,
                    view==PokemonAssetView::Back?"back":"front");
    return;
  }
  if (species == 421 && view != PokemonAssetView::Icon) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 1U);
    std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/cherrim/%u/%s%s.pkg",
                  form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (view == PokemonAssetView::Icon)
    std::snprintf(path, size, "/pokegochi/assets/pokemon/%sicons/%03u_%u.pkg",
                  shiny, species, static_cast<unsigned>(frame & 1U));
  else
    std::snprintf(path, size, "/pokegochi/assets/pokemon/%s%s/%03u.pkg", shiny,
                   view == PokemonAssetView::Back ? "back" : "front", species);
}

void centeredPokemonAssetOrigin(const char* path, int16_t centerX, int16_t centerY,
                                uint16_t defaultWidth, uint16_t defaultHeight,
                                int16_t& originX, int16_t& originY) {
  uint16_t width = defaultWidth;
  uint16_t height = defaultHeight;
  uint16_t residentWidth = 0;
  uint16_t residentHeight = 0;
  // Gen 1-3 battle assets are 64x64, while the native Platinum assets are
  // 80x80.  dimensions() is RAM-only here; the scene manifest has already
  // made the relevant asset resident before a composed frame is drawn.
  if (AssetRenderer::dimensions(path, residentWidth, residentHeight) &&
      residentWidth != 0U && residentHeight != 0U) {
    width = residentWidth;
    height = residentHeight;
  }
  originX = static_cast<int16_t>(centerX - static_cast<int16_t>(width / 2U));
  originY = static_cast<int16_t>(centerY - static_cast<int16_t>(height / 2U));
}

bool drawCenteredPokemonAsset(const char* path, int16_t centerX, int16_t centerY,
                              uint16_t defaultWidth, uint16_t defaultHeight) {
  int16_t originX = 0;
  int16_t originY = 0;
  centeredPokemonAssetOrigin(path, centerX, centerY, defaultWidth, defaultHeight,
                             originX, originY);
  return AssetRenderer::draw(display, path, originX, originY);
}

void creature(int16_t x, int16_t y, const OwnedPokemon& pokemon, bool wild = false,
              uint16_t displayedSpecies = 0) {
  const uint16_t speciesId=displayedSpecies?displayedSpecies:pokemon.speciesId;
  if (sdReady && speciesId >= 1 && speciesId <= kPokedexSpeciesCount) {
    char path[112]; pokemonAssetPath(path, sizeof(path), pokemon,
        wild ? PokemonAssetView::Front : PokemonAssetView::Icon, iconFrame,
        displayedSpecies);
    const int16_t size = wild ? 64 : 32;
    if (wild && speciesId == 327U) {
      int16_t originX = 0, originY = 0;
      centeredPokemonAssetOrigin(path, x, y, size, size, originX, originY);
      if (AssetRenderer::drawSpinda(
              display, path, originX, originY, pokemon.personality)) return;
    } else if (drawCenteredPokemonAsset(path, x, y, size, size)) return;
  }
  const uint16_t color = speciesColor(speciesId);
  // Keep the emergency silhouette inside the same footprint as the asset it
  // replaces.  The old 68 px placeholder overflowed every 32 px Box/Home
  // cell and looked like a purple sprite even when only one cache read had
  // missed.
  const int16_t radius = wild ? 24 : 12;
  const int16_t earX = wild ? 24 : 12;
  const int16_t earTop = wild ? 37 : 20;
  const int16_t earY = wild ? 18 : 8;
  const int16_t eyeOffset = wild ? 10 : 5;
  display.fillCircle(x, y, radius, color);
  display.fillTriangle(x - earX, y - earY, x - earX + 9, y - earTop,
                       x - (wild ? 8 : 4), y - earY + 1, color);
  display.fillTriangle(x + (wild ? 8 : 4), y - earY + 1,
                       x + earX - 7, y - earTop, x + earX, y - earY, color);
  display.fillCircle(x - eyeOffset, y - (wild ? 4 : 2), wild ? 3 : 2, TFT_BLACK);
  display.fillCircle(x + eyeOffset, y - (wild ? 4 : 2), wild ? 3 : 2, TFT_BLACK);
}

void creature(int16_t x, int16_t y, uint16_t speciesId, bool wild = false,
              bool shiny = false, uint8_t form = 0) {
  OwnedPokemon visual{};visual.speciesId=speciesId;visual.shiny=shiny;visual.form=form;
  creature(x,y,visual,wild);
}

void battleBackSprite(int16_t x, int16_t y, const OwnedPokemon& pokemon,
                      uint16_t displayedSpecies = 0) {
  const uint16_t speciesId=displayedSpecies?displayedSpecies:pokemon.speciesId;
  if (sdReady && speciesId >= 1 && speciesId <= kPokedexSpeciesCount) {
    char path[112]; pokemonAssetPath(path, sizeof(path), pokemon,
                                     PokemonAssetView::Back,0,displayedSpecies);
    if (drawCenteredPokemonAsset(path, x, y, 64U, 64U)) return;
  }
  creature(x,y,pokemon,true,displayedSpecies);
}

