bool battleAnimationAssetTravels(const char* asset) {
  if (!asset) return false;
  static constexpr const char* kTravelWords[] = {
      "ember", "fire", "water", "bubble", "orb", "ball", "seed", "leaf", "needle",
      "rock", "shard", "icicle", "spear", "wave", "line", "ring", "star", "beam",
      "electric", "lightning", "gust", "spike", "petal", "powder", "spore"};
  for (const char* word : kTravelWords) if (std::strstr(asset, word)) return true;
  return false;
}

void battleAnimationAssetPath(char* destination, size_t size, const char* asset, uint8_t frame) {
  std::snprintf(destination, size, "/pokegochi/assets/firered/battle_anims/sprites/%s_%02u.pkg",
                asset && asset[0] ? asset : "hit", static_cast<unsigned>(frame));
}

