        const uint8_t step = static_cast<uint8_t>(std::min<uint16_t>(
            std::abs(static_cast<int16_t>(end) - start), task.age / delay));
        const uint8_t amount = static_cast<uint8_t>(start +
            (end >= start ? step : -static_cast<int16_t>(step)));
        const uint16_t color = gbaBattleColorToRgb565(battleAnimationArgument(
            task.arguments, task.argumentCount, 4, 0));
        // This callback is used with BG palette mask 0xF8 in FireRed. It does
