        // Fifteen steps toward RGB(27,29,31), a thirty-tick hold, then the
        // battle BG and battler palettes return over sixteen steps.
        constexpr uint16_t kFadeInEnd = 16U;
        constexpr uint16_t kHoldEnd = 47U;
        uint8_t amount = 0U;
        if (task.age < kFadeInEnd) amount = static_cast<uint8_t>(task.age);
        else if (task.age < kHoldEnd) amount = 16U;
        else amount = static_cast<uint8_t>(std::max<int16_t>(0,
            16 - static_cast<int16_t>(task.age - kHoldEnd)));
        const uint16_t moonColor = gbaBattleColorToRgb565(0x7FBB);
        applyArenaColor(AssetColorEffect::Blend, moonColor, amount);
        applyColor(false, AssetColorEffect::Blend, moonColor, amount);
        applyColor(true, AssetColorEffect::Blend, moonColor, amount);
        break;
