          const int16_t direction = (drop & 1U) ? -1 : 1;
          drawTaskSprite(0U, task.age - born,
              static_cast<int16_t>(taskAttackerX + direction * (18 + drop * 3)),
              static_cast<int16_t>(taskAttackerY - 24 +
                  static_cast<int16_t>(task.age - born) * 2));
