        static constexpr uint16_t kFacadeColors[] = {
            0xF800, 0xFBE0, 0x07E0, 0x07FF, 0x001F, 0xF81F,
            0xFD20, 0xAFE5};
        const uint16_t duration = static_cast<uint16_t>(std::max<int16_t>(1,
            battleAnimationArgument(task.arguments, task.argumentCount, 1, 72)));
        if (task.age < duration)
          applyColor(attackerOpponent, AssetColorEffect::Blend,
              kFacadeColors[(task.age / 3U) %
                  (sizeof(kFacadeColors) / sizeof(kFacadeColors[0]))], 8U);
        break;
