      case BattleAnimationTaskMotion::SetAllNonAttackersInvisible: {
        const bool invisible = battleAnimationArgument(
            task.arguments, task.argumentCount, 0, 0) != 0;
        if (targetOpponent) battleVisualOverlay.hideOpponent = invisible;
        else battleVisualOverlay.hidePlayer = invisible;
        markBattler(targetOpponent);
        break;
      }
      case BattleAnimationTaskMotion::RotateAuroraRingColors:
      case BattleAnimationTaskMotion::TagFlash:
      case BattleAnimationTaskMotion::TagPaletteRotate:
      case BattleAnimationTaskMotion::TagBlendCycle:
      case BattleAnimationTaskMotion::TagBlendInOut:
      case BattleAnimationTaskMotion::TagBlendToColor:
      case BattleAnimationTaskMotion::MagicalLeafPaletteCycle:
      case BattleAnimationTaskMotion::MusicNotePaletteSetup:
      case BattleAnimationTaskMotion::MusicNotePaletteClear:
      case BattleAnimationTaskMotion::PaletteBackupSave:
      case BattleAnimationTaskMotion::PaletteBackupRestore:
