        // not pre-bake scrolling, alpha or palette cycling into the bitmap.
        const uint16_t stage = static_cast<uint16_t>((task.age + 1U) / 2U);
        uint8_t opacity = 0U;
        if (stage && stage < 14U) opacity = static_cast<uint8_t>(stage);
        else if (stage <= 54U) opacity = 13U;
        else if (stage < 68U) opacity = static_cast<uint8_t>(67U - stage);
