          battleVisualOverlay.fieldAsset = enemyAttacking
              ? BattleFieldAsset::SurfOpponent
              : BattleFieldAsset::SurfPlayer;
        const uint16_t travelAge = std::min<uint16_t>(135U, task.age);
        const uint16_t sourceTop = enemyAttacking
            ? 0U : static_cast<uint16_t>(std::max<int16_t>(
                0, static_cast<int16_t>(48 - travelAge)));
        const uint16_t sourceBottom = enemyAttacking
            ? std::min<uint16_t>(112U, travelAge)
            : 112U;
