        // both boundaries (instead of scaling the height independently)
        // prevents a one-row seam as the reveal window advances.
        const uint16_t destinationTop = static_cast<uint16_t>(
            (static_cast<uint32_t>(sourceTop) * 4U) / 3U);
        const uint16_t destinationBottom = static_cast<uint16_t>(
            (static_cast<uint32_t>(sourceBottom) * 4U) / 3U);
        battleVisualOverlay.fieldDestinationX = 0;
        battleVisualOverlay.fieldDestinationY = static_cast<int16_t>(destinationTop);
        battleVisualOverlay.fieldOffsetX = enemyAttacking
            ? static_cast<int16_t>(-224 + 2 * travelAge)
            : static_cast<int16_t>(-2 * travelAge);
