        battleVisualOverlay.fieldPaletteFirst = 1U;
        battleVisualOverlay.fieldPaletteCount = 7U;
        battleVisualOverlay.fieldPaletteShift = static_cast<uint8_t>(
            (travelAge / 4U) % 7U);
