bool isLegendarySpecies(uint16_t species) {
  return PokedexLogic::isLegendaryOrMythical(species);
}
void recordWildEncounterStatistics(const OwnedPokemon& pokemon) {
  if(pokemon.shiny)++gameSave.statistics.shiniesEncountered;
  if(isLegendarySpecies(pokemon.speciesId))++gameSave.statistics.legendariesEncountered;
}
void recordBallStatistics(const BattleActionResult& result,const OwnedPokemon* target) {
  if(!result.accepted)return;
  ++gameSave.statistics.pokeBallsThrown;
  if(!result.caught||!target)return;
  ++gameSave.statistics.pokemonCaptured;
  if(target->shiny)++gameSave.statistics.shiniesCaptured;
  if(isLegendarySpecies(target->speciesId))++gameSave.statistics.legendariesCaptured;
}
