void fillUiEllipse(int16_t centerX, int16_t centerY, int16_t radiusX,
                   int16_t radiusY, uint16_t color) {
  if (radiusX <= 0 || radiusY <= 0) return;
  for (int16_t offsetY = -radiusY; offsetY <= radiusY; ++offsetY) {
    const float normalized = static_cast<float>(offsetY) / radiusY;
    const int16_t span = static_cast<int16_t>(
        radiusX * sqrtf(std::max(0.0F, 1.0F - normalized * normalized)));
    display.drawFastHLine(centerX - span, centerY + offsetY, span * 2 + 1, color);
  }
}

void drawEggArtwork(int16_t panelX, int16_t panelY, int16_t panelWidth,
                    int16_t panelHeight) {
  drawGbaInsetPanel(panelX, panelY, panelWidth, panelHeight, 7,
                    kBattleFrameShadow, themePale(), kBattleFrameGold);
  const int16_t centerX = panelX + panelWidth / 2;
  const int16_t centerY = panelY + panelHeight / 2 + 4;
  // A few deterministic sparkles keep the card lively without changing from
  // frame to frame or requiring additional SD traffic.
  display.fillCircle(centerX - 33, centerY - 37, 2, TFT_WHITE);
  display.drawPixel(centerX - 33, centerY - 41, TFT_WHITE);
  display.drawPixel(centerX - 33, centerY - 33, TFT_WHITE);
  display.fillCircle(centerX + 34, centerY - 21, 2, TFT_YELLOW);
  display.drawPixel(centerX + 30, centerY - 21, TFT_YELLOW);
  display.drawPixel(centerX + 38, centerY - 21, TFT_YELLOW);
  fillUiEllipse(centerX, centerY + 32, 32, 7, 0xA514);
  if (!sdReady || !AssetRenderer::draw(display,
      "/pokegochi/assets/firered/ui/egg.pkg", centerX - 32, centerY - 32)) {
    fillUiEllipse(centerX, centerY, 23, 30, kBattleFrameShadow);
    fillUiEllipse(centerX, centerY, 21, 28, TFT_WHITE);
    display.fillCircle(centerX - 10, centerY - 8, 4, 0xE73C);
    display.fillCircle(centerX + 9, centerY + 7, 5, 0xE73C);
  }
}

