void drawLeagueComplete(){
  const bool entering=beginScreenPresentation(Screen::LeagueComplete,themePale());
  // LeagueComplete is entered directly from battle. Large move planes may
  // have replaced the normal 57 KiB UI bank with a smaller exact-sized
  // workspace; Android's 4 MiB cache hides that transition, but the ESP32
  // then cannot retain the 320x240 Hall of Fame backdrop and shows the
  // striped recovery fallback. Restore the normal bank before the manifest,
  // never while retained stripes are being composed.
  if(entering&&!renderingRetainedFrame&&
     !AssetRenderer::restoreSceneWorkspace(false))
    Serial.println("[GFX] LeagueComplete workspace restore failed");
  const uint8_t region=gameSave.gymProgress.unlockedGeneration;
  const char* backdrop=region==3
      ? "/pokegochi/assets/emerald/pokemon_league/victory_bg.pkg"
      : "/pokegochi/assets/firered/pokemon_league/victory_bg.pkg";
  char pokemonPaths[3][88]{};
  const char* assets[4]={backdrop,nullptr,nullptr,nullptr};
  uint8_t assetCount=1;
  uint32_t sceneKey=0x484F4600UL|region;
  for(uint8_t i=0;i<3;++i){
    const OwnedPokemon* pokemon=CollectionLogic::active(gameSave.collection,i);
    if(!pokemon)continue;
    pokemonAssetPath(pokemonPaths[i],sizeof(pokemonPaths[i]),*pokemon,
                     PokemonAssetView::Front);
    assets[assetCount++]=pokemonPaths[i];
    sceneKey=(sceneKey^pokemon->speciesId^
        (static_cast<uint32_t>(CollectionLogic::resolvedForm(*pokemon))<<16U)^
        (pokemon->shiny?0x80000000UL:0UL))*16777619UL;
  }
  prepareUiScene(sceneKey,assets,assetCount);
  if(!sdReady||!AssetRenderer::draw(display,backdrop,0,0)){
    // The Hall remains celebratory and readable even during SD recovery.
    display.fillRect(0,0,320,240,themePale());
    for(int16_t y=0;y<240;y+=12)
      display.drawFastHLine(0,y,320,themeAccent());
  }

  // FireRed-style gold/blue framing leaves the original Hall of Fame room
  // visible through the centre instead of hiding the party on a black field.
  display.drawRoundRect(2,2,316,236,8,kBattleFrameShadow);
  display.drawRoundRect(4,4,312,232,7,kBattleFrameGold);
  drawFireRedBattleWindow(8,8,304,58,themeAccent(),themePrimary());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(TFT_YELLOW,themePrimary());
  fireRedText.drawString("NEW CHAMPION!",160,25,4);
  fireRedText.setTextColor(TFT_WHITE,themePrimary());
  fireRedText.drawStringFitted(region==1?"KANTO LEAGUE":region==2?"JOHTO LEAGUE":"HOENN LEAGUE",160,51,286,1);

  // Small podium shadows anchor the existing party sprites in the room.
  for(uint8_t i=0;i<3;++i){
    OwnedPokemon* pokemon=CollectionLogic::active(gameSave.collection,i);
    if(!pokemon)continue;
    const int16_t centerX=82+i*78;
    fillUiEllipse(centerX,146,30,7,themeDark());
    fillUiEllipse(centerX,144,27,5,themePale());
    creature(centerX,126,*pokemon,false);
  }

  drawFireRedBattleWindow(10,158,300,42,themeAccent(),kBattlePaper);
  fireRedText.setTextColor(themeDark(),kBattlePaper);
  fireRedText.drawStringFitted("MASTER BALL RECEIVED!",160,171,284,1);
  fireRedText.drawStringFitted(region==1?"LUCKY EGG BOOST: +100%!":
      region<3?"A NEW ADVENTURE AWAITS!":"A SPECIAL CHALLENGE AWAITS!",160,188,284,1);
  button(105,204,110,28,"CONTINUE",TFT_DARKGREEN);
  fireRedText.setTextDatum(TL_DATUM);
}

