uint32_t firstReadyPartyUid(bool requireReady = true) {
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    if (!pokemon) continue;
    if (!requireReady || (pokemon->currentHp && !pokemon->recoverySecondsRemaining))
      return pokemon->uid;
  }
  return 0U;
}

bool unovaAreaBattleInProgress() {
  return gameSave.battle.active && UnovaAdventure::active(gameSave.unova) &&
      gameSave.unova.run.pendingBattle != UnovaBattleRole::None &&
      (gameSave.battle.kind == BattleKind::Wild ||
       gameSave.battle.kind == BattleKind::Trainer);
}

bool kalosBattleInProgress() {
  return gameSave.battle.active && KalosAdventure::active(gameSave.kalos) &&
      gameSave.kalos.run.pendingBattle != KalosBattleRole::None &&
      (gameSave.battle.kind == BattleKind::Wild ||
       gameSave.battle.kind == BattleKind::KalosAdventure);
}

bool unovaTournamentBattleInProgress() {
  return gameSave.battle.active && UnovaTournament::active(gameSave.unova) &&
      (gameSave.battle.kind == BattleKind::Pwt ||
       gameSave.battle.kind == BattleKind::RoyalUnova);
}

void prepareFreshBattlePresentation() {
  pendingBattleKind = BattleKind::None;
  battleEntryAnimationPending = true;
  selectedBattleTerrainSceneKey = 0;
  battlePresentationPlayerHidden = false;
  battlePresentationOpponentHidden = false;
  battleCaptureOpponentHidden = false;
  resetBattleVisualOverlay();
  battleArenaVisible = false;
  presentedPlayerHp = presentedOpponentHp = -1;
  presentedPlayerHpBarPixels = presentedOpponentHpBarPixels = -1;
  battleEntryFollowupMessage[0] = 0;
  runConfirmVisible = false;
}

bool launchUnovaAreaBattle() {
  const uint32_t playerUid = firstReadyPartyUid();
  if (!playerUid || !UnovaAdventure::startPendingBattle(
          gameSave.unova, gameSave.battle, gameSave.collection, playerUid))
    return false;
  OwnedPokemon* opponent = BattleEngine::currentOpponent(gameSave.battle);
  if (opponent) {
    PokedexLogic::markSeen(gameSave.pokedex, opponent->speciesId);
    if (gameSave.battle.kind == BattleKind::Wild)
      recordWildEncounterStatistics(*opponent);
  }
  prepareFreshBattlePresentation();
  const SpeciesData* species = opponent ? findSpecies(opponent->speciesId) : nullptr;
  if (gameSave.battle.kind == BattleKind::Wild)
    std::snprintf(message, sizeof(message), "A WILD %s APPEARED!",
                  species ? species->name : "POKEMON");
  else
    std::snprintf(message, sizeof(message), "%s BLOCKS THE PATH!",
                  gameSave.unova.run.pendingBattle == UnovaBattleRole::Boss
                      ? UnovaAdventure::bossName(
                            static_cast<UnovaArea>(gameSave.unova.run.area))
                      : gameSave.unova.run.pendingBattle == UnovaBattleRole::GateTrainer
                          ? "THE GATE TRAINER" : "A TRAINER");
  saveDirty = true;
  saveNow();
  screen = Screen::Battle;
  drawBattle();
  return true;
}

bool launchKalosBattle() {
  const uint32_t playerUid = firstReadyPartyUid();
  if (!playerUid || !KalosAdventure::startPendingBattle(
          gameSave.kalos, gameSave.battle, gameSave.collection, playerUid))
    return false;
  OwnedPokemon* opponent = BattleEngine::currentOpponent(gameSave.battle);
  if (opponent) {
    PokedexLogic::markSeen(gameSave.pokedex, opponent->speciesId);
    if (gameSave.battle.kind == BattleKind::Wild)
      recordWildEncounterStatistics(*opponent);
  }
  prepareFreshBattlePresentation();
  const SpeciesData* species = opponent ? findSpecies(opponent->speciesId) : nullptr;
  if (gameSave.battle.kind == BattleKind::Wild)
    std::snprintf(message, sizeof(message), "A WILD %s APPEARED!",
                  species ? species->name : "POKEMON");
  else
    std::snprintf(message, sizeof(message), "%s WANTS TO BATTLE!",
        gameSave.kalos.run.pendingBattle == KalosBattleRole::Leader
            ? KalosAdventure::bossName(
                  static_cast<KalosArea>(gameSave.kalos.run.area))
            : gameSave.kalos.run.pendingBattle == KalosBattleRole::TeamFlare
                ? "TEAM FLARE" : "A KALOS TRAINER");
  saveDirty = true;
  saveNow();
  screen = Screen::Battle;
  drawBattle();
  return true;
}

bool launchUnovaTournamentBattle() {
  const uint32_t playerUid = firstReadyPartyUid(false);
  if (!playerUid || !UnovaTournament::startBattle(
          gameSave.unova, gameSave.battle, gameSave.collection, playerUid))
    return false;
  prepareFreshBattlePresentation();
  std::snprintf(message, sizeof(message), "%s WANTS TO BATTLE!",
                UnovaTournament::opponentName(gameSave.unova));
  saveDirty = true;
  saveNow();
  screen = Screen::Battle;
  drawBattle();
  return true;
}

void drawChooseBattler() {
  // Enter the scene before building its manifest. beginScreenPresentation()
  // invalidates every battle-owned UI/cache key at a real transition; doing
  // that after prepareUiScene() discarded the freshly prepared party pack.
  // The retained preflight then tried to rebuild it with compositionActive,
  // where SD access is deliberately blocked, and all three cards fell back
  // to the broken procedural silhouettes. With this order, the top-level
  // call performs cleanup first and the retained pass is strictly RAM-only.
  beginScreenPresentation(Screen::ChooseBattler, kBattlePaper);
  // ChooseBattler is a real scene, not an overlay on Home. Give it an atomic
  // manifest so its transition and three party sprites replace (rather than
  // append to) Home's already-full cache before retained composition starts.
  char choicePaths[4][88]{};
  const char* choiceAssets[4]{};
  uint8_t choiceAssetCount = 0;
  uint32_t choiceSceneKey = 0x43484F4FU ^ static_cast<uint8_t>(pendingBattleKind);
  if (pendingBattleKind == BattleKind::Wild) {
    std::snprintf(choicePaths[choiceAssetCount], sizeof(choicePaths[0]),
                  "/pokegochi/assets/firered/ui/wild_transition.pkg");
    choiceAssets[choiceAssetCount] = choicePaths[choiceAssetCount];
    ++choiceAssetCount;
  }
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    if (!pokemon) continue;
    pokemonAssetPath(choicePaths[choiceAssetCount], sizeof(choicePaths[0]),
                     *pokemon, PokemonAssetView::Front);
    choiceAssets[choiceAssetCount] = choicePaths[choiceAssetCount];
    choiceSceneKey = (choiceSceneKey ^ pokemon->speciesId ^
        (static_cast<uint32_t>(CollectionLogic::resolvedForm(*pokemon)) << 16U) ^
        (pokemon->shiny ? 0x8000U : 0U)) * 16777619U;
    ++choiceAssetCount;
  }
  prepareUiScene(choiceSceneKey, choiceAssets, choiceAssetCount);
  // Battle-adjacent screens share FireRed's ivory paper and faint green
  // scanlines.  The previous full-screen navy Pokeball made this picker look
  // unrelated to the arena that immediately followed it.
  constexpr uint16_t pickerBackdrop = 0xE7F8;
  constexpr uint16_t pickerStripe = 0xCF33;
  constexpr uint16_t pickerWell = 0xDFF4;
  // The enabled action uses the bright ivory surface.  The tinted green-grey
  // surface is deliberately reserved for a partner that is still recovering;
  // using it on CHOOSE made the available action look pressed/disabled while
  // the unavailable FAINTED card looked brighter and clickable.
  constexpr uint16_t pickerUnavailable = 0xBEEA;
  bool hasReadyBattler = false;
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    if (pokemon && pokemon->currentHp > 0 && pokemon->recoverySecondsRemaining == 0) {
      hasReadyBattler = true;
      break;
    }
  }
  display.fillRect(0, 0, 320, 240, pickerBackdrop);
  for (int16_t y = 2; y < 240; y += 8)
    display.drawFastHLine(0, y, 320, pickerStripe);

  drawFireRedBattleWindow(3, 3, 314, 51, kBattleFrameGold, themePrimary());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(TFT_YELLOW, themePrimary());
  char wildHeading[44]{};
  if (pendingBattleKind == BattleKind::Wild && pendingWildEncounterCount > 1U)
    std::snprintf(wildHeading, sizeof(wildHeading),
                  sinnohEncounterPending ? "SINNOH EXPLORE: %u ENCOUNTERS" :
                                            "WILD CHAIN: %u ENCOUNTERS",
                  pendingWildEncounterCount);
  const char* heading = pendingBattleKind == BattleKind::Wild
                            ? (wildHeading[0] ? wildHeading : "A WILD POKEMON APPEARED!") :
                        pendingBattleKind == BattleKind::Gym ? "GYM CHALLENGE" :
                        pendingBattleKind == BattleKind::SinnohGym ? "SINNOH GYM CHALLENGE" :
                        pendingBattleKind == BattleKind::League ? "POKEMON LEAGUE" :
                        pendingBattleKind == BattleKind::MegaChallenge ? "SPECIAL CHALLENGE" :
                        pendingBattleKind == BattleKind::Boss ? "BOSS CHALLENGE" :
                        pendingBattleKind == BattleKind::Tower ? "BATTLE TOWER CHALLENGE" : "TRAINER BATTLE";
  fireRedText.drawStringFitted(heading, 160, 16, 296, 1);
  fireRedText.setTextColor(TFT_WHITE, themePrimary());
  fireRedText.drawString(hasReadyBattler ? "CHOOSE YOUR BATTLER" : "NO POKEMON CAN BATTLE!",
                         160, 38, 1);
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    const int16_t left = 5 + slot * 105;
    const int16_t x = left + 50;
    drawFireRedBattleWindow(left, 57, 100, 154, kBattleFrameGold, kBattlePaper);
    display.fillRect(left + 5, 62, 90, 56, pickerWell);
    display.drawFastHLine(left + 5, 118, 90, kBattleFrameGold);
    if (!pokemon) {
      fireRedText.setTextColor(TFT_LIGHTGREY, kBattlePaper);
      fireRedText.drawString("EMPTY", x, 141, 1);
      continue;
    }
    const SpeciesData* data = findSpecies(pokemon->speciesId);
    creature(x,91,*pokemon,true);
    fireRedText.setTextColor(kBattleInk, kBattlePaper);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawStringAuto(data ? data->name : "UNKNOWN", x, 127, 78);
    char level[12]; std::snprintf(level, sizeof(level), "Lv%u", pokemon->level);
    const uint16_t hpPercent = pokemon->maximumHp == 0 ? 0U :
        pokemon->currentHp == 0 ? 0U : static_cast<uint16_t>(std::max<uint32_t>(
            1U, std::min<uint32_t>(100U,
                (static_cast<uint32_t>(pokemon->currentHp) * 100U) / pokemon->maximumHp)));
    // "HP" is already printed beside the meter, so the compact value row
    // owns the full four glyphs of "100%".  Prefixing it with a second "HP"
    // exceeded the 45 px cell and clipped only the percent sign at full life.
    char hp[10]; std::snprintf(hp, sizeof(hp), "%u%%", hpPercent);
    display.drawFastHLine(left + 7, 137, 86, kBattleFrameGold);
    fireRedText.setTextDatum(TL_DATUM);
    fireRedText.drawStringFitted(level, left + 9, 141, 38, 1);
    fireRedText.setTextDatum(TR_DATUM);
    fireRedText.drawStringFitted(hp, left + 91, 141, 40, 1);
    fireRedText.setTextDatum(TL_DATUM); fireRedText.setTextColor(TFT_ORANGE, kBattlePaper);
    fireRedText.drawString("HP", left + 11, 153, 1);
    display.fillRect(left + 30, 154, 57, 7, kBattleInk);
    display.fillRect(left + 32, 156, 53, 3, kBattlePaper);
    const uint16_t pickerHpColor = pokemon->maximumHp && pokemon->currentHp * 4U <= pokemon->maximumHp
        ? TFT_RED : pokemon->maximumHp && pokemon->currentHp * 2U <= pokemon->maximumHp ? TFT_ORANGE : TFT_GREEN;
    display.fillRect(left + 32, 156, meterFillPixels(53U, pokemon->currentHp, pokemon->maximumHp),
                     3, pickerHpColor);
    const bool ready = pokemon->currentHp > 0 && pokemon->recoverySecondsRemaining == 0;
    drawFireRedBattleWindow(left + 8, 170, 84, 32,
                            ready ? kBattleFrameGold : TFT_LIGHTGREY,
                            ready ? kBattlePaper : pickerUnavailable);
    fireRedText.setTextColor(ready ? kBattleInk : TFT_DARKGREY,
                             ready ? kBattlePaper : pickerUnavailable);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString(ready ? "CHOOSE" : "FAINTED", x, 186, 1);
  }
  // Every challenge must remain escapable here.  Gym and League used to omit
  // this control, which trapped the player if every party member was fainted.
  drawFireRedBattleWindow(110, 214, 100, 24, TFT_RED, kBattlePaper);
  fireRedText.setTextColor(kBattleInk, kBattlePaper);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString(pendingBattleKind == BattleKind::Wild ? "IGNORE" : "BACK", 160, 226, 1);
  fireRedText.setTextDatum(TL_DATUM);
}

void drawTrainerIntro() {
  const TrainerProfile* profile = trainerProfile(gameSave.battle.trainerProfileId);
  const GymDefinition* gym = gameSave.battle.kind == BattleKind::Gym
      ? GymSystem::definition(static_cast<GymId>(gameSave.battle.gymId)) : nullptr;
  const SinnohGymDefinition* sinnohGym = gameSave.battle.kind == BattleKind::SinnohGym
      ? SinnohExpedition::gymDefinition(
            static_cast<SinnohSite>(gameSave.battle.gymId)) : nullptr;
  const LeagueMemberDefinition* league = gameSave.battle.kind == BattleKind::League
      ? LeagueSystem::definition(gameSave.battle.leagueRegion,gameSave.battle.leagueStage) : nullptr;
  const BattleTowerTrainerDefinition* tower = BattleTowerSystem::trainer(gameSave.battle);
  const MegaChallengeTrainerDefinition* mega = gameSave.battle.kind == BattleKind::MegaChallenge
      ? &MegaChallengeSystem::trainer() : nullptr;
  const char* trainerClass = "TRAINER";
  const char* trainerName = "";
  const char* line1 = "LET'S BATTLE!";
  const char* line2 = "";
  const char* asset = nullptr;
  if (sinnohGym) {
    trainerClass = "LEADER"; trainerName = sinnohGym->leader;
    line1 = sinnohGym->introLine1; line2 = sinnohGym->introLine2;
    asset = sinnohGym->frontAsset;
  } else if (mega) {
    trainerClass = mega->trainerClass; trainerName = mega->name;
    line1 = mega->introLine1; line2 = mega->introLine2; asset = mega->frontAsset;
  } else if (tower) {
    trainerClass = tower->trainerClass; trainerName = tower->name;
    line1 = tower->introLine1; line2 = tower->introLine2; asset = tower->frontAsset;
  } else if (league) {
    trainerClass = league->trainerClass; trainerName = league->name;
    line1 = league->introLine1; line2 = league->introLine2; asset = league->frontAsset;
  } else if (gym) {
    trainerClass = GymSystem::opponentClass(gameSave.battle);
    trainerName = GymSystem::opponentName(gameSave.battle);
    line1 = GymSystem::opponentLine1(gameSave.battle);
    line2 = GymSystem::opponentLine2(gameSave.battle);
    asset = GymSystem::opponentAsset(gameSave.battle);
  } else if (profile) {
    trainerClass = profile->trainerClass; trainerName = profile->name;
    line1 = profile->introLine1; line2 = profile->introLine2; asset = profile->frontAsset;
  }

  beginScreenPresentation(Screen::TrainerIntro, themeDark());

  // Portrait stage. The old screen was a single pale rectangle; this uses
  // the FireRed window rail, a theme-aware Pokeball watermark and speed lines
  // while keeping the genuine 64x64 trainer sprite as the focal point.
  drawFireRedBattleWindow(3, 3, 314, 127, kBattleFrameGold, themePale());
  display.fillRect(9, 9, 302, 115, themePale());
  for (uint8_t stripe = 0; stripe < 4; ++stripe) {
    const int16_t y = 24 + stripe * 22;
    display.fillRect(14, y, 76 - stripe * 10, 3, themeAccent());
    display.fillRect(230 + stripe * 10, y + 10, 76 - stripe * 10, 3, themeAccent());
  }
  constexpr int16_t ballX = 160, ballY = 66, ballRadius = 49;
  display.fillCircle(ballX, ballY, ballRadius + 3, themeDark());
  display.fillCircle(ballX, ballY, ballRadius, themePale());
  // Paint only spans belonging to the lower semicircle; this avoids the
  // square corners produced by covering half of a circle with fillRect.
  for (int16_t dy = 0; dy <= ballRadius; ++dy) {
    const int16_t span = static_cast<int16_t>(sqrtf(
        static_cast<float>(ballRadius * ballRadius - dy * dy)));
    display.drawFastHLine(ballX - span, ballY + dy, span * 2 + 1, TFT_WHITE);
  }
  display.fillRect(ballX - ballRadius, ballY - 2, ballRadius * 2 + 1, 5, themeDark());
  display.fillCircle(ballX, ballY, 12, themeDark());
  display.fillCircle(ballX, ballY, 7, TFT_WHITE);
  display.fillRoundRect(115, 110, 90, 9, 4, themeDark());
  display.fillRoundRect(120, 111, 80, 5, 2, themeAccent());

  const char* challenge = (gameSave.battle.kind == BattleKind::Gym ||
                           gameSave.battle.kind == BattleKind::SinnohGym) ? "GYM BATTLE" :
      gameSave.battle.kind == BattleKind::League ? "POKEMON LEAGUE" :
      gameSave.battle.kind == BattleKind::Tower ? "BATTLE TOWER" :
      gameSave.battle.kind == BattleKind::MegaChallenge ? "SPECIAL BATTLE" : "TRAINER BATTLE";
  drawFireRedBattleWindow(12, 12, 126, 27, kBattleFrameGold, themePrimary());
  fireRedText.setTextColor(TFT_WHITE, themePrimary());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted(challenge, 75, 25, 112, 1);
  fireRedText.setTextDatum(TL_DATUM);

  if (asset && asset[0]) {
    char path[96];
    std::snprintf(path, sizeof(path), "/pokegochi/assets/trainers/%s.pkg", asset);
    const int16_t portraitX = sinnohGym ? 120 : 128;
    const int16_t portraitY = sinnohGym ? 40 : 43;
    if (!AssetRenderer::draw(display, path, portraitX, portraitY)) {
      // A missing portrait must remain recognisable without leaving an empty
      // hole in the composition while the SD diagnostic catches the failure.
      display.fillCircle(160, 69, 20, themeDark());
      display.fillRoundRect(138, 87, 44, 25, 8, themeDark());
    }
  }

  // Dialogue surface. Merge the authored two source rows and let the common
  // text-box renderer wrap and clip them. This guarantees at least one pixel
  // of margin and prevents long trainer lines from escaping the panel.
  drawFireRedBattleWindow(3, 132, 314, 105, kBattleFrameGold, themePrimary());
  char title[56]{};
  std::snprintf(title, sizeof(title), "%s%s%s", trainerClass,
                trainerName && trainerName[0] ? " " : "", trainerName ? trainerName : "");
  fireRedText.setTextColor(TFT_YELLOW, themePrimary());
  fireRedText.drawStringFitted(title, 14, 140, 292, 2);
  display.fillRect(12, 160, 296, 2, themeAccent());

  char dialogue[128]{};
  std::snprintf(dialogue, sizeof(dialogue), "%s%s%s", line1 ? line1 : "",
                line2 && line2[0] ? "\n" : "", line2 ? line2 : "");
  fireRedText.setTextColor(TFT_WHITE, themePrimary());
  fireRedText.drawTextBox(dialogue, 13, 166, 294, 48, 0);
  fireRedText.setTextDatum(TR_DATUM);
  fireRedText.drawStringFitted("TOUCH TO BATTLE  >", 305, 218, 160, 1);
  fireRedText.setTextDatum(TL_DATUM);
}

const char* terrainForPokemonType(PokemonType type, uint32_t roll) {
  const char* first = "grass";
  const char* second = "building";
  const char* third = "indoor";
  switch (type) {
    case PokemonType::Water: first = "water"; second = "pond"; third = "underwater"; break;
    case PokemonType::Grass: first = "grass"; second = "longgrass"; third = "pond"; break;
    case PokemonType::Bug: first = "longgrass"; second = "grass"; third = "forest"; break;
    case PokemonType::Ground: first = "sand"; second = "cave"; third = "mountain"; break;
    case PokemonType::Rock: first = "cave"; second = "mountain"; third = "sand"; break;
    case PokemonType::Fire: first = "mountain"; second = "sand"; third = "cave"; break;
    case PokemonType::Flying: first = "mountain"; second = "grass"; third = "longgrass"; break;
    case PokemonType::Ice: first = "cave"; second = "water"; third = "mountain"; break;
    case PokemonType::Dragon: first = "mountain"; second = "cave"; third = "sand"; break;
    case PokemonType::Ghost: first = "cave"; second = "mountain"; third = "indoor"; break;
    case PokemonType::Poison: first = "longgrass"; second = "cave"; third = "grass"; break;
    case PokemonType::Psychic: first = "cave"; second = "mountain"; third = "indoor"; break;
    case PokemonType::Electric: first = "building"; second = "indoor"; third = "mountain"; break;
    case PokemonType::Steel: first = "building"; second = "cave"; third = "indoor"; break;
    case PokemonType::Fighting: first = "mountain"; second = "building"; third = "sand"; break;
    case PokemonType::Dark: first = "cave"; second = "longgrass"; third = "mountain"; break;
    case PokemonType::Normal: default: break;
  }
  const uint8_t chance = static_cast<uint8_t>(roll % 100U);
  return chance < 60U ? first : chance < 85U ? second : third;
}

BattleTerrain battleTerrainForAsset(const char* terrain) {
  if (!terrain) return BattleTerrain::Plain;
  if (std::strcmp(terrain, "grass") == 0) return BattleTerrain::Grass;
  if (std::strcmp(terrain, "longgrass") == 0 || std::strcmp(terrain, "forest") == 0)
    return BattleTerrain::LongGrass;
  if (std::strcmp(terrain, "sand") == 0) return BattleTerrain::Sand;
  if (std::strcmp(terrain, "underwater") == 0) return BattleTerrain::Underwater;
  if (std::strcmp(terrain, "water") == 0) return BattleTerrain::Water;
  if (std::strcmp(terrain, "pond") == 0) return BattleTerrain::Pond;
  if (std::strcmp(terrain, "mountain") == 0) return BattleTerrain::Mountain;
  if (std::strcmp(terrain, "cave") == 0) return BattleTerrain::Cave;
  if (std::strcmp(terrain, "building") == 0 || std::strcmp(terrain, "indoor") == 0 ||
      std::strcmp(terrain, "gym") == 0 || std::strcmp(terrain, "leader") == 0 ||
      std::strcmp(terrain, "indoor_2") == 0 || std::strcmp(terrain, "lorelei") == 0 ||
      std::strcmp(terrain, "bruno") == 0 || std::strcmp(terrain, "agatha") == 0 ||
      std::strcmp(terrain, "lance") == 0 || std::strcmp(terrain, "champion") == 0 ||
      std::strcmp(terrain, "link") == 0)
    return BattleTerrain::Building;
  return BattleTerrain::Plain;
}

void applyBattleTerrainMechanics(const char* terrain) {
  gameSave.battle.terrain = battleTerrainForAsset(terrain);
  switch (gameSave.battle.terrain) {
    case BattleTerrain::Grass:
    case BattleTerrain::LongGrass: gameSave.battle.terrainType = PokemonType::Grass; break;
    case BattleTerrain::Sand: gameSave.battle.terrainType = PokemonType::Ground; break;
    case BattleTerrain::Underwater:
    case BattleTerrain::Water:
    case BattleTerrain::Pond: gameSave.battle.terrainType = PokemonType::Water; break;
    case BattleTerrain::Mountain:
    case BattleTerrain::Cave: gameSave.battle.terrainType = PokemonType::Rock; break;
    case BattleTerrain::Building:
    case BattleTerrain::Plain: gameSave.battle.terrainType = PokemonType::Normal; break;
  }
}

const char* chooseBattleTerrain(const OwnedPokemon* opponent) {
  // Use the lead and the battle identity, never the active battlers. A
  // trainer, Gym opponent or League member owns one arena for their entire
  // fight, exactly as in FireRed.
  const uint8_t opponentCount = std::min<uint8_t>(
      gameSave.battle.opponentCount, kOpponentTeamCapacity);
  const OwnedPokemon* lead = opponentCount ? &gameSave.battle.opponents[0] : opponent;
  const uint32_t species = lead ? lead->speciesId : 0U;
  uint32_t sceneKey = (species * 0x45D9F3BU) ^
                      (static_cast<uint32_t>(gameSave.battle.kind) << 27U) ^
                      (static_cast<uint32_t>(gameSave.battle.trainerProfileId) << 15U) ^
                      (static_cast<uint32_t>(gameSave.battle.gymId) << 7U) ^
                      (static_cast<uint32_t>(gameSave.battle.gymStage) << 4U) ^
                      (static_cast<uint32_t>(gameSave.battle.leagueRegion) << 2U) ^
                      gameSave.battle.leagueStage;
  for (uint8_t index = 0; index < opponentCount; ++index)
    sceneKey = (sceneKey ^ gameSave.battle.opponents[index].speciesId) * 16777619U;
  if (!sceneKey) sceneKey = 1U;
  if (selectedBattleTerrainSceneKey == sceneKey) {
    applyBattleTerrainMechanics(selectedBattleTerrain);
    return selectedBattleTerrain;
  }

  const SpeciesData* speciesData = lead ? findSpecies(lead->speciesId) : nullptr;
  uint32_t roll = sceneKey ^ 0x9E3779B9U;
  PokemonType type = speciesData ? speciesData->type1 : PokemonType::Normal;
  if (speciesData && speciesData->type2 != speciesData->type1 && ((roll >> 8U) & 3U) == 0U)
    type = speciesData->type2;
  const char* terrain = terrainForPokemonType(type, roll >> 16U);
  // Ordinary trainers retain the route/interior variety. Special encounters
  // use FireRed's own room-specific tile/palette combinations rather than a
  // firmware-generated recolour.
  if (gameSave.battle.kind == BattleKind::Trainer && roll % 100U < 58U)
    terrain = (roll & 0x100U) ? "building" : "indoor";
  else if (gameSave.battle.kind == BattleKind::Gym)
    terrain = gameSave.battle.gymStage >= 2U ? "leader" : "gym";
  else if (gameSave.battle.kind == BattleKind::SinnohGym)
    terrain = "leader";
  else if (gameSave.battle.kind == BattleKind::League) {
    static const char* const kLeagueTerrains[] = {
      "lorelei", "bruno", "agatha", "lance", "champion"
    };
    terrain = kLeagueTerrains[std::min<uint8_t>(gameSave.battle.leagueStage, 4U)];
  } else if (gameSave.battle.kind == BattleKind::Tower)
    terrain = "indoor_2";
  else if (gameSave.battle.kind == BattleKind::MegaChallenge)
    terrain = "champion";
  else if (gameSave.battle.kind == BattleKind::Boss)
    terrain = "champion";
  else if (gameSave.battle.kind == BattleKind::Pvp)
    terrain = "link";
  // "forest" is intentionally represented by FireRed's long-grass scene;
  // it is not a separate battle terrain asset in this ROM.
  if (std::strcmp(terrain, "forest") == 0) terrain = "longgrass";
  std::strncpy(selectedBattleTerrain, terrain, sizeof(selectedBattleTerrain) - 1U);
  selectedBattleTerrain[sizeof(selectedBattleTerrain) - 1U] = 0;
  selectedBattleTerrainSceneKey = sceneKey;
  applyBattleTerrainMechanics(selectedBattleTerrain);
  Serial.printf("[BATTLE] terrain=%s type=%u scene=%08lx\n", selectedBattleTerrain,
                static_cast<unsigned>(type), static_cast<unsigned long>(sceneKey));
  return selectedBattleTerrain;
}

OwnedPokemon* battleOpponentByUid(uint32_t uid) {
  if (!uid) return nullptr;
  const uint8_t opponentCount = std::min<uint8_t>(
      gameSave.battle.opponentCount, kOpponentTeamCapacity);
  for (uint8_t index = 0; index < opponentCount; ++index)
    if (gameSave.battle.opponents[index].uid == uid) return &gameSave.battle.opponents[index];
  return nullptr;
}

uint8_t battleOpponentIndexByUid(uint32_t uid) {
  const uint8_t opponentCount = std::min<uint8_t>(
      gameSave.battle.opponentCount, kOpponentTeamCapacity);
  for (uint8_t index = 0; index < opponentCount; ++index)
    if (gameSave.battle.opponents[index].uid == uid) return index;
  return std::min<uint8_t>(gameSave.battle.opponentIndex,
                           opponentCount ? static_cast<uint8_t>(opponentCount - 1U) : 0U);
}

OwnedPokemon* presentedBattlePlayer() {
  const uint32_t uid = battleFlow.phase != BattleFlowPhase::Idle && battleFlow.displayPlayerUid
      ? battleFlow.displayPlayerUid : gameSave.battle.playerUid;
  return CollectionLogic::find(gameSave.collection, uid);
}

OwnedPokemon* presentedBattleOpponent() {
  if (battleFlow.phase != BattleFlowPhase::Idle) {
    if (battleFlow.displayOpponentUid)
      if (OwnedPokemon* pokemon = battleOpponentByUid(battleFlow.displayOpponentUid)) return pokemon;
    // Legacy battles once stored every opponent with UID zero. Never fall
    // through to currentOpponent() during presentation: the engine may have
    // already advanced that pointer to the next trainer Pokemon.
    const uint8_t opponentCount = std::min<uint8_t>(
        gameSave.battle.opponentCount, kOpponentTeamCapacity);
    if (battleFlow.displayOpponentIndex < opponentCount)
      return &gameSave.battle.opponents[battleFlow.displayOpponentIndex];
    return nullptr;
  }
  return BattleEngine::currentOpponent(gameSave.battle);
}

uint16_t presentedBattleSpeciesId(const OwnedPokemon* pokemon, bool playerSide) {
  if (!pokemon) return 0;
  if (battleFlow.phase != BattleFlowPhase::Idle) {
    const uint16_t displayed = playerSide ? battleFlow.displayPlayerSpeciesId
                                          : battleFlow.displayOpponentSpeciesId;
    if (displayed) return displayed;
  }
  return pokemon->speciesId;
}

uint8_t presentedBattleForm(const OwnedPokemon* pokemon, bool playerSide) {
  if (!pokemon) return 0;
  if (battleFlow.phase != BattleFlowPhase::Idle) {
    const uint32_t displayedUid = playerSide ? battleFlow.displayPlayerUid
                                             : battleFlow.displayOpponentUid;
    if (pokemon->uid == displayedUid)
      return playerSide ? battleFlow.displayPlayerForm
                        : battleFlow.displayOpponentForm;
  }
  return CollectionLogic::resolvedForm(*pokemon);
}

uint16_t presentedBattleMaximumHp(const OwnedPokemon* pokemon,bool playerSide){
  if(!pokemon)return 1U;
  if(battleFlow.phase!=BattleFlowPhase::Idle){
    const uint32_t displayedUid=playerSide?battleFlow.displayPlayerUid:
        battleFlow.displayOpponentUid;
    if(pokemon->uid==displayedUid){
      const uint16_t staged=playerSide?battleFlow.displayPlayerMaximumHp:
          battleFlow.displayOpponentMaximumHp;
      if(staged)return staged;
    }
  }
  return std::max<uint16_t>(1U,pokemon->maximumHp);
}

uint16_t battleHpColor(uint16_t current, uint16_t maximum) {
  switch (BattleHpAnimation::levelForValue(current, maximum)) {
    case BattleHpAnimation::BarLevel::Green: return TFT_GREEN;
    case BattleHpAnimation::BarLevel::Yellow: return TFT_YELLOW;
    default: return TFT_RED;
  }
}

uint16_t battleHpColorForFill(uint16_t filled, uint16_t width) {
  switch (BattleHpAnimation::levelForScaledPixels(filled, width)) {
    case BattleHpAnimation::BarLevel::Green: return TFT_GREEN;
    case BattleHpAnimation::BarLevel::Yellow: return TFT_YELLOW;
    default: return TFT_RED;
  }
}

// FireRed windows are tile-aligned with tiny cut corners, never smooth
// rounded rectangles.  This primitive reproduces that frame using only
// resident pixels, so improving the style does not add any SD reads.
void drawFireRedBattleWindow(int16_t x, int16_t y, int16_t width, int16_t height,
                             uint16_t trim, uint16_t inside) {
  if (width < 8 || height < 8) return;
  display.fillRect(x + 2, y, width - 4, height, kBattleFrameDark);
  display.fillRect(x, y + 2, width, height - 4, kBattleFrameDark);
  display.fillRect(x + 3, y + 2, width - 6, height - 4, trim);
  display.fillRect(x + 2, y + 3, width - 4, height - 6, trim);
  display.fillRect(x + 5, y + 5, width - 10, height - 10, inside);
}

void drawBattleHpMeter(int16_t x, int16_t y, uint16_t current, uint16_t maximum,
                       uint16_t width = 82, int16_t animatedFill = -1) {
  fireRedText.setTextColor(TFT_ORANGE, kBattlePaper);
  fireRedText.drawString("HP", x, y - 1, 1);
  display.fillRect(x + 19, y, width + 4, 8, kBattleInk);
  display.fillRect(x + 21, y + 2, width, 4, kBattlePaper);
  const uint16_t filled = animatedFill >= 0
      ? std::min<uint16_t>(width, static_cast<uint16_t>(animatedFill))
      : BattleHpAnimation::pixelsForValue(current, maximum, width);
  if (filled) {
    const uint16_t color = animatedFill >= 0
        ? battleHpColorForFill(filled, width)
        : battleHpColor(current, maximum);
    display.fillRect(x + 21, y + 2, filled, 4, color);
  }
}

const char* battleStatusAbbreviation(StatusCondition status) {
  switch (status) {
    case StatusCondition::Poison: case StatusCondition::BadlyPoisoned: return "PSN";
    case StatusCondition::Paralysis: return "PAR";
    case StatusCondition::Burn: return "BRN";
    case StatusCondition::Sleep: return "SLP";
    case StatusCondition::Frozen: return "FRZ";
    default: return "";
  }
}

uint16_t battleStatusColor(StatusCondition status) {
  switch (status) {
    case StatusCondition::Poison: case StatusCondition::BadlyPoisoned: return TFT_MAGENTA;
    case StatusCondition::Paralysis: return TFT_YELLOW;
    case StatusCondition::Burn: return TFT_RED;
    case StatusCondition::Sleep: return TFT_LIGHTGREY;
    case StatusCondition::Frozen: return TFT_CYAN;
    default: return TFT_WHITE;
  }
}


void drawTinyPokeBall(int16_t x, int16_t y, bool available = true) {
  const uint16_t edge = available ? TFT_DARKGREY : TFT_LIGHTGREY;
  display.fillCircle(x, y, 5, edge);
  display.fillCircle(x, y, 4, available ? TFT_RED : TFT_DARKGREY);
  display.fillRect(x - 4, y, 9, 4, available ? TFT_WHITE : TFT_DARKGREY);
  display.drawFastHLine(x - 4, y - 1, 9, edge);
  display.fillCircle(x, y, 2, available ? TFT_WHITE : TFT_LIGHTGREY);
  display.drawCircle(x, y, 2, edge);
}

void drawBattleTeamIndicators() {
  // Player party: immediately above the player's lower-right card. This was
  // previously (and incorrectly) populated with the opponent's team.
  uint8_t playerCount = 0;
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot)
    if (CollectionLogic::active(gameSave.collection, slot)) ++playerCount;
  const int16_t playerStartX = static_cast<int16_t>(306 - (playerCount ? playerCount - 1U : 0U) * 13U);
  uint8_t shown = 0;
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const OwnedPokemon* member = CollectionLogic::active(gameSave.collection, slot);
    if (!member) continue;
    const bool available = battleFlow.phase == BattleFlowPhase::Idle
        ? member->currentHp > 0 && member->recoverySecondsRemaining == 0
        : (battleFlow.displayPlayerUsableMask & (1U << slot)) != 0;
    drawTinyPokeBall(static_cast<int16_t>(playerStartX + shown * 13), 96, available);
    ++shown;
  }

  if (gameSave.battle.kind == BattleKind::Wild) return;
  // Opponent team: directly below the opponent's upper-left card. Future
  // members stay anonymous Pokeballs and defeated members are dimmed.
  constexpr int16_t opponentStartX = 15;
  const uint8_t opponentCount = std::min<uint8_t>(
      gameSave.battle.opponentCount, kOpponentTeamCapacity);
  for (uint8_t index = 0; index < opponentCount; ++index) {
    const bool available = battleFlow.phase == BattleFlowPhase::Idle
        ? gameSave.battle.opponents[index].currentHp > 0
        : (battleFlow.displayOpponentUsableMask & (1U << index)) != 0;
    drawTinyPokeBall(static_cast<int16_t>(opponentStartX + index * 13), 58, available);
  }
}

void drawBattleStatusBox(int16_t x, int16_t y, int16_t width, const SpeciesData* species,
                         const OwnedPokemon* pokemon, bool playerSide) {
  const uint16_t card = kBattlePaper;
  const int16_t cardHeight = playerSide ? 51 : 46;
  // The right-hand wedge is the characteristic FireRed health-box shadow.
  // It deliberately extends beyond the parchment while remaining below all
  // text and meters, matching the original two-sprite healthbox silhouette.
  display.fillRect(x + 5, y + 6, width - 5, cardHeight - 1, kBattleFrameShadow);
  display.fillTriangle(x + width - 23, y + cardHeight - 7,
                       x + width + 8, y + cardHeight + 5,
                       x + width - 23, y + cardHeight + 5, kBattleFrameShadow);
  display.fillRect(x + 2, y, width - 4, cardHeight, kBattleFrameDark);
  display.fillRect(x, y + 2, width, cardHeight - 4, kBattleFrameDark);
  display.fillRect(x + 3, y + 2, width - 6, cardHeight - 4, kBattleFrameGold);
  display.fillRect(x + 2, y + 3, width - 4, cardHeight - 6, kBattleFrameGold);
  display.fillRect(x + 4, y + 4, width - 8, cardHeight - 8, card);
  fireRedText.setTextColor(kBattleInk, card);
  fireRedText.drawStringFitted(species ? species->name : "POKEMON", x + 8, y + 7,
                               std::max<int16_t>(1, width - 63), 1);
  const bool stagedPlayerProgress = playerSide && pokemon &&
      battleFlow.phase != BattleFlowPhase::Idle && battleFlow.displayPlayerProgressValid &&
      pokemon->uid == battleFlow.displayPlayerUid;
  const uint8_t shownLevel = stagedPlayerProgress ? battleFlow.displayPlayerLevel
                                                   : pokemon ? pokemon->level : 1U;
  char level[10]; std::snprintf(level, sizeof(level), "Lv%u", shownLevel);
  fireRedText.setTextDatum(TR_DATUM);
  fireRedText.drawStringFitted(level, x + width - 8, y + 7, 42, 1);
  fireRedText.setTextDatum(TL_DATUM);
  if (!pokemon) return;
  drawPokemonGenderSymbol(*pokemon, x + width - 52, y + 14);
  const uint16_t shownMaximum=presentedBattleMaximumHp(pokemon,playerSide);
  const uint16_t shownHp = static_cast<uint16_t>(std::min<int32_t>(shownMaximum,
      playerSide && presentedPlayerHp >= 0 ? presentedPlayerHp :
      !playerSide && presentedOpponentHp >= 0 ? presentedOpponentHp : pokemon->currentHp));
  if(!playerSide&&gameSave.battle.kind==BattleKind::Boss){
    const uint32_t shownBossHp=presentedOpponentHp>=0?
        static_cast<uint32_t>(presentedOpponentHp):
        BossSystem::battleCurrentHp(gameSave.battle);
    char hp[24];
    std::snprintf(hp,sizeof(hp),"%lu/%lu",
                  static_cast<unsigned long>(shownBossHp),
                  static_cast<unsigned long>(BossSystem::kMaximumHp));
    fireRedText.setTextColor(TFT_ORANGE,card);
    fireRedText.drawString("HP",x+19,y+20,1);
    fireRedText.setTextColor(kBattleInk,card);
    fireRedText.setTextDatum(TR_DATUM);
    fireRedText.drawStringFitted(hp,x+width-8,y+20,width-48,1);
    fireRedText.setTextDatum(TL_DATUM);
  }else{
    const int16_t animatedFill = playerSide ? presentedPlayerHpBarPixels
                                            : presentedOpponentHpBarPixels;
    drawBattleHpMeter(x + (playerSide ? 25 : 19), y + 20, shownHp,
                      shownMaximum, playerSide ? 88 : 84, animatedFill);
  }
  StatusCondition shownStatus = pokemon->status;
  if (battleFlow.phase != BattleFlowPhase::Idle) {
    if (playerSide && pokemon->uid == battleFlow.displayPlayerUid)
      shownStatus = battleFlow.displayPlayerStatus;
    else if (!playerSide && pokemon->uid == battleFlow.displayOpponentUid)
      shownStatus = battleFlow.displayOpponentStatus;
  }
  if (shownStatus != StatusCondition::None) {
    const uint16_t color = battleStatusColor(shownStatus);
    const int16_t badgeX = x + 5;
    // Status belongs on its own compact row below the HP label/bar. Normal
    // 16px text was taller than this native FireRed badge and leaked upward
    // into "HP"; the original 8px small glyph set keeps all three letters.
    constexpr int16_t kStatusBadgeWidth = 25;
    constexpr int16_t kStatusBadgeHeight = 10;
    display.fillRoundRect(badgeX, y + 33, kStatusBadgeWidth, kStatusBadgeHeight, 2, color);
    fireRedText.setTextColor(TFT_BLACK, color);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawStringFitted(battleStatusAbbreviation(shownStatus),
                                 badgeX + kStatusBadgeWidth / 2,
                                 y + 33 + kStatusBadgeHeight / 2,
                                 kStatusBadgeWidth - 4, 3);
    fireRedText.setTextDatum(TL_DATUM);
  }
  if (!playerSide && gameSave.battle.kind == BattleKind::Wild && species &&
      PokedexLogic::hasCaught(gameSave.pokedex, species->id))
    // FireRed's caught marker belongs in the unused gutter immediately left
    // of "HP", never over the meter itself. Its bottom stays above the
    // separate status row when the wild Pokemon is also afflicted.
    drawTinyPokeBall(x + 10, y + 25, true);
  if (playerSide) {
    char hp[18]; std::snprintf(hp, sizeof(hp), "%u/%u", shownHp, shownMaximum);
    fireRedText.setTextDatum(TR_DATUM); fireRedText.setTextColor(kBattleInk, card);
    fireRedText.drawStringFitted(hp, x + width - 8, y + 31, width - 43, 1);
    fireRedText.setTextDatum(TL_DATUM);
    // EXP owns a separate final row. Previously its label and bar were
    // painted directly through the numeric HP text.
    display.fillRect(x + 29, y + 43, 99, 4, TFT_DARKGREY);
    // EXP growth belongs to the Pokemon's original identity even when the
    // visible battle form is Transform. Evolution families retain one growth
    // curve, so this also remains stable while an evolution cinematic waits.
    const SpeciesData* ownSpecies = findSpecies(pokemon->speciesId);
    const uint32_t shownExperience = stagedPlayerProgress
        ? battleFlow.displayPlayerExperience : pokemon->experience;
    const uint32_t currentXp = ownSpecies ? experienceForLevel(ownSpecies->growthRate, shownLevel) : 0U;
    const uint32_t nextXp = !ownSpecies || shownLevel >= 100 ? currentXp + 1U :
                            experienceForLevel(ownSpecies->growthRate, static_cast<uint8_t>(shownLevel + 1U));
    const uint32_t span = std::max<uint32_t>(1U, nextXp - currentXp);
    const uint32_t gained = shownExperience > currentXp ? shownExperience - currentXp : 0U;
    const uint16_t xpWidth = static_cast<uint16_t>(std::min<uint32_t>(95U, 95U * gained / span));
    display.fillRect(x + 31, y + 44, xpWidth, 2, TFT_CYAN);
    fireRedText.setTextColor(TFT_ORANGE, card); fireRedText.drawString("EXP", x + 4, y + 40, 1);
  }
}

void prepareBattleGraphics(const OwnedPokemon* player, const OwnedPokemon* opponent,
                           const char* terrainPath) {
  // Every animation frame has already passed through the complete manifest
  // preload. Return before allocating two Pokemon copies and three path/key
  // workspaces on loopTask for each 8-row stripe. Besides wasted CPU, that
  // repeated stack frame left only ~180 bytes during the heaviest moves.
  if (battleVisualOverlay.active) return;
  // A BLE live capture intentionally leaves the scene arena released while
  // the player is in Home/Settings. Reacquire it only now, before any battle
  // asset is decoded, so a partial radio-time allocation can never be reused
  // as a full terrain cache.
  if (liveDiagnosticWorkspaceRestorePending) {
    const bool restored = AssetRenderer::restoreSceneWorkspace(false);
    if (restored) liveDiagnosticWorkspaceRestorePending = false;
    if (wirelessUpdate.liveLogActive())
      wirelessUpdate.emitLiveLog("UI_BATTLE_WORKSPACE restored=%u",
                                 restored ? 1U : 0U);
  }
  recordBattleRenderCheckpoint(kBattleCheckpointPrepareScene,
                               battleAnimationCurrentMove,
                               battleAnimationCurrentEnemyAttacking);
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  uint32_t terrainHash = 2166136261U;
  for (const char* cursor = terrainPath; cursor && *cursor; ++cursor)
    terrainHash = (terrainHash ^ static_cast<uint8_t>(*cursor)) * 16777619U;
  uint32_t key=terrainHash;
  const auto mixKey=[&](uint32_t value){key=(key^value)*16777619U;};
  mixKey(playerSpeciesId);mixKey(opponentSpeciesId);
  mixKey(player&&player->shiny?1U:0U);mixKey(opponent&&opponent->shiny?1U:0U);
  mixKey(playerForm);mixKey(opponentForm);
  mixKey(player?static_cast<uint8_t>(MegaEvolution::variantFor(*player)):0U);
  mixKey(opponent?static_cast<uint8_t>(MegaEvolution::variantFor(*opponent)):0U);
  char opponentPath[112]{};
  char playerPath[112]{};
  OwnedPokemon playerVisual{}, opponentVisual{};
  if(player){playerVisual=*player;playerVisual.form=playerForm;}
  if(opponent){opponentVisual=*opponent;opponentVisual.form=opponentForm;}
  if (opponent && opponentSpeciesId)
    pokemonAssetPath(opponentPath, sizeof(opponentPath), opponentVisual,
                     PokemonAssetView::Front, 0, opponentSpeciesId);
  if (player && playerSpeciesId)
    pokemonAssetPath(playerPath, sizeof(playerPath), playerVisual,
                     PokemonAssetView::Back, 0, playerSpeciesId);
  // A UI submenu is allowed to reuse the renderer's RAM. Do not trust the
  // old key alone when returning to Battle: verify its complete scene pack
  // still exists before the first frame or animation is drawn.
  // An opaque FireRed ChangeBackground replaces the terrain in the shared
  // scene slot. During its animation the replacement is the valid base, so
  // do not rebuild the old terrain and evict the authored tiled background
  // from underneath the retained compositor.
  // The animation background is assigned before the overlay is marked active.
  // Treat it as resident here so preparing the arena does not reload the
  // terrain and evict the move-specific replacement plane.
  const bool activeMoveBackgroundResident =
      battleVisualOverlay.backgroundPath[0] &&
      AssetRenderer::isPreloaded(battleVisualOverlay.backgroundPath);
  const bool battlersResident =
      (!opponentPath[0] || AssetRenderer::isPreloaded(opponentPath)) &&
      (!playerPath[0] || AssetRenderer::isPreloaded(playerPath));
  // Animation frames are presented from inside drawBattleArena(). A retained
  // frame must never try to prepare the ordinary scene again at that point:
  // doing so opens the SD recursively below the same loopTask stack frame and
  // can trip the ESP32 stack canary (most visible when a foe follows Aura
  // Sphere with Attack Order). preloadMoveAnimation() has already resolved
  // the complete move manifest before the first frame, and the final restore
  // below playBattleAnimationProgram() runs with this overlay cleared.
  // preloadMoveAnimation() has already replaced the shared scene slot with
  // this opaque ChangeBackground plane and restored both battlers. The normal
  // terrain key is allowed to be stale in that state; rebuilding it would
  // evict the authored move plane before the first retained stripe.
  if ((activeMoveBackgroundResident && battlersResident) ||
      (preparedBattleGraphicsKey == key &&
       (AssetRenderer::isPreloaded(terrainPath) || activeMoveBackgroundResident) &&
       battlersResident)) return;

  // A retained stripe is already inside the physical compositor. If the
  // scene key is stale here, never clear the valid cache and then attempt a
  // cold preload from inside that stripe; that is the exact path that turned
  // Rock Wrecker/field-heavy moves into a cancelled black frame. Keep the
  // cache intact, expose the mismatch once, and let the caller's normal
  // outside-composition retry repair it.
  if (renderingRetainedFrame) {
    Serial.printf("[GFX] retained scene mismatch prepared=%08lx key=%08lx "
                  "terrain=%u player=%u foe=%u\n",
                  static_cast<unsigned long>(preparedBattleGraphicsKey),
                  static_cast<unsigned long>(key),
                  AssetRenderer::isPreloaded(terrainPath) ? 1U : 0U,
                  playerPath[0] && AssetRenderer::isPreloaded(playerPath) ? 1U : 0U,
                  opponentPath[0] && AssetRenderer::isPreloaded(opponentPath) ? 1U : 0U);
    return;
  }

  // Cache exactly the terrain and the two battlers before a battle screen is
  // drawn.  All subsequent touches in the battle read RAM rather than the SD
  // card, including FireRed's move-selection screen.
  const uint32_t preparedAtMs = millis();
  const uint32_t cacheClearedAtMs = millis();
  bool ready = AssetRenderer::preload(terrainPath);
  const uint32_t terrainLoadedAtMs = millis();
  if (opponentPath[0]) ready = AssetRenderer::preload(opponentPath) && ready;
  if (playerPath[0]) ready = AssetRenderer::preload(playerPath) && ready;
  // A menu can leave the compact arena full of unrelated icons. The fast
  // path above intentionally preserves resident battlers across move-plane
  // replacement; if that existing cache cannot fit the complete battle base,
  // recycle it once and rebuild the canonical three-asset manifest.
  if (!ready && AssetRenderer::takeCacheCapacityFailure()) {
    AssetRenderer::clearCache();
    ready = AssetRenderer::preload(terrainPath);
    if (opponentPath[0]) ready = AssetRenderer::preload(opponentPath) && ready;
    if (playerPath[0]) ready = AssetRenderer::preload(playerPath) && ready;
  }
  if (AssetRenderer::takeIoFailure()) {
    ready = false;
    storageRecoveryPending = true;
  }
  Serial.printf("[GFX] battle preload player=%u opponent=%u %s clear=%lums terrainLoad=%lums total=%lums heap=%u block=%u\n",
                playerSpeciesId, opponentSpeciesId,
                ready ? "OK" : "FAIL", static_cast<unsigned long>(cacheClearedAtMs - preparedAtMs),
                static_cast<unsigned long>(terrainLoadedAtMs - cacheClearedAtMs),
                static_cast<unsigned long>(millis() - preparedAtMs),
                static_cast<unsigned>(ESP.getFreeHeap()), static_cast<unsigned>(ESP.getMaxAllocHeap()));
  preparedBattleGraphicsKey = ready ? key : 0;
}

void drawBattleCurseMask(const OwnedPokemon& pokemon,
                         uint16_t speciesId, uint8_t form,
                         bool opponentSide, int16_t centerX,
                         int16_t centerY) {
  if (!battleVisualOverlay.active) return;
  const bool enabled = opponentSide ? battleVisualOverlay.curseOpponent
                                    : battleVisualOverlay.cursePlayer;
  if (!enabled) return;
  OwnedPokemon visual = pokemon;
  visual.form = form;
  char maskPath[112]{};
  pokemonAssetPath(maskPath, sizeof(maskPath), visual,
                   opponentSide ? PokemonAssetView::Front
                                : PokemonAssetView::Back,
                   0, speciesId);
  int16_t originX = 0;
  int16_t originY = 0;
  centeredPokemonAssetOrigin(maskPath, centerX, centerY, 64U, 64U,
                             originX, originY);
  AssetRenderer::drawPatternMasked(
      display, maskPath,
      originX, originY,
      battleAnimationFieldPath(BattleFieldAsset::Curse),
      static_cast<int16_t>(-kBattleNativeViewportOriginX),
      static_cast<int16_t>(-kBattleNativeViewportOriginY +
                           battleVisualOverlay.curseOffsetY), 8U);
}

void drawBattleStatusClearMask(const OwnedPokemon& pokemon,
                               uint16_t speciesId, uint8_t form,
                               bool opponentSide, int16_t centerX,
                               int16_t centerY) {
  if (!battleVisualOverlay.active) return;
  const bool enabled = opponentSide ? battleVisualOverlay.cureOpponent
                                    : battleVisualOverlay.curePlayer;
  if (!enabled) return;
  OwnedPokemon visual = pokemon;
  visual.form = form;
  char maskPath[112]{};
  pokemonAssetPath(maskPath, sizeof(maskPath), visual,
                   opponentSide ? PokemonAssetView::Front
                                : PokemonAssetView::Back,
                   0, speciesId);
  int16_t originX = 0;
  int16_t originY = 0;
  centeredPokemonAssetOrigin(maskPath, centerX, centerY, 64U, 64U,
                             originX, originY);
  AssetRenderer::drawPatternMasked(
      display, maskPath,
      originX, originY,
      battleAnimationFieldPath(BattleFieldAsset::CureBubbles),
      static_cast<int16_t>(battleVisualOverlay.cureOffsetX -
                           kBattleNativeViewportOriginX),
      static_cast<int16_t>(battleVisualOverlay.cureOffsetY -
                           kBattleNativeViewportOriginY),
      battleVisualOverlay.cureOpacity);
}

void drawBattleArena(OwnedPokemon* player, OwnedPokemon* opponent, bool hideOpponent) {
  const auto clipIntersectsY = [](int16_t top, int16_t bottom) {
    return display.logicalClipTop() < bottom &&
        display.logicalClipBottom() > top;
  };
  const bool transformOpponent = battleVisualOverlay.active &&
      (battleVisualOverlay.opponentScaleX != 100U ||
       battleVisualOverlay.opponentScaleY != 100U ||
       battleVisualOverlay.opponentRotation != 0U ||
       battleVisualOverlay.opponentColorEffect != AssetColorEffect::None ||
       battleVisualOverlay.opponentClipTop != 0U ||
       battleVisualOverlay.opponentClipBottom != 64U);
  const bool transformPlayer = battleVisualOverlay.active &&
      (battleVisualOverlay.playerScaleX != 100U ||
       battleVisualOverlay.playerScaleY != 100U ||
       battleVisualOverlay.playerRotation != 0U ||
       battleVisualOverlay.playerColorEffect != AssetColorEffect::None ||
       battleVisualOverlay.playerClipTop != 0U ||
       battleVisualOverlay.playerClipBottom != 64U);
  hideOpponent = hideOpponent || battleCaptureOpponentHidden || battlePresentationOpponentHidden ||
      (battleVisualOverlay.active && battleVisualOverlay.hideOpponent) || transformOpponent;
  const bool hidePlayer = battlePresentationPlayerHidden ||
      (battleVisualOverlay.active && battleVisualOverlay.hidePlayer) || transformPlayer;
  const int16_t playerX = static_cast<int16_t>(kBattlePlayerX +
      (battleVisualOverlay.active ? battleVisualOverlay.playerOffsetX : 0));
  const int16_t playerY = static_cast<int16_t>(kBattlePlayerY +
      (battleVisualOverlay.active ? battleVisualOverlay.playerOffsetY +
          std::abs(battleAnimationSin(battleVisualOverlay.playerRotation, 32)) : 0));
  const int16_t opponentX = static_cast<int16_t>(kBattleOpponentX +
      (battleVisualOverlay.active ? battleVisualOverlay.opponentOffsetX : 0));
  const int16_t opponentY = static_cast<int16_t>(kBattleOpponentY +
      (battleVisualOverlay.active ? battleVisualOverlay.opponentOffsetY +
          std::abs(battleAnimationSin(battleVisualOverlay.opponentRotation, 32)) : 0));
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  const SpeciesData* foeSpecies = findSpecies(opponentSpeciesId);
  const SpeciesData* playerSpecies = findSpecies(playerSpeciesId);
  const char* terrain = chooseBattleTerrain(opponent);
  char terrainPath[80];
  std::snprintf(terrainPath, sizeof(terrainPath), "/pokegochi/assets/firered/battle_terrain/%s.pkg", terrain);
  prepareBattleGraphics(player, opponent, terrainPath);
  // A FireRed changebg plane is opaque and REPLACES terrain.  Drawing a
  // terrain frame first exposed it for one retained stripe and doubled the
  // palette work of every scrolling frame; on hardware that looked like a
  // flash or a band of the old arena.  Select exactly one base plane, then
  // compose task fields, battlers, particles and HUD above it.
  AssetOverlay basePlane{};
  basePlane.path = terrainPath;
  basePlane.x = 0;
  basePlane.y = 0;
  basePlane.width = 320U;
  basePlane.height = 184U;
  if (battleVisualOverlay.active) {
    basePlane.sourceOffsetX = battleVisualOverlay.backgroundOffsetX;
    basePlane.sourceOffsetY = battleVisualOverlay.backgroundOffsetY;
    basePlane.paletteFirst = battleVisualOverlay.backgroundPaletteFirst;
    basePlane.paletteCount = battleVisualOverlay.backgroundPaletteCount;
    basePlane.paletteShift = battleVisualOverlay.backgroundPaletteShift;
    basePlane.wrap = battleVisualOverlay.backgroundWrap;
    basePlane.wrapX = battleVisualOverlay.backgroundWrap;
    basePlane.wrapY = battleVisualOverlay.backgroundWrap;
  }
  if (battleVisualOverlay.active && battleVisualOverlay.backgroundPath[0]) {
    basePlane.path = battleVisualOverlay.backgroundPath;
    basePlane.wrapX = true;
    basePlane.wrapY = true;
    basePlane.scaleNumerator = battleVisualOverlay.backgroundNativeCamera ? 4U : 1U;
    basePlane.scaleDenominator = battleVisualOverlay.backgroundNativeCamera ? 3U : 1U;
    basePlane.virtualSourceWidth =
        battleVisualOverlay.backgroundVirtualWidth;
    basePlane.virtualSourceHeight =
        battleVisualOverlay.backgroundVirtualHeight;
    basePlane.virtualFillIndex =
        battleVisualOverlay.backgroundVirtualFillIndex;
  }

  AssetOverlay fieldPlane{};
  const bool hasField = battleVisualOverlay.active &&
      battleVisualOverlay.fieldAsset != BattleFieldAsset::None &&
      battleVisualOverlay.fieldOpacity &&
      battleAnimationFieldPath(battleVisualOverlay.fieldAsset);
  if (hasField) {
    fieldPlane.path = battleAnimationFieldPath(battleVisualOverlay.fieldAsset);
    fieldPlane.x = battleVisualOverlay.fieldDestinationX;
    fieldPlane.y = battleVisualOverlay.fieldDestinationY;
    fieldPlane.width = battleVisualOverlay.fieldWidth;
    fieldPlane.height = battleVisualOverlay.fieldHeight;
    fieldPlane.sourceOffsetX = battleVisualOverlay.fieldOffsetX;
    fieldPlane.sourceOffsetY = battleVisualOverlay.fieldOffsetY;
    fieldPlane.opacity16 = battleVisualOverlay.fieldOpacity;
    fieldPlane.paletteFirst = battleVisualOverlay.fieldPaletteFirst;
    fieldPlane.paletteCount = battleVisualOverlay.fieldPaletteCount;
    fieldPlane.paletteShift = battleVisualOverlay.fieldPaletteShift;
    fieldPlane.wrap = battleVisualOverlay.fieldWrap;
    fieldPlane.wrapX = battleVisualOverlay.fieldWrapX;
    fieldPlane.wrapY = battleVisualOverlay.fieldWrapY;
    fieldPlane.scaleNumerator = battleVisualOverlay.fieldNativeCamera ? 4U : 1U;
    fieldPlane.scaleDenominator = battleVisualOverlay.fieldNativeCamera ? 3U : 1U;
  }

  // Terrain/changebg and a translucent field are one visual plane as far as
  // the TFT is concerned. Compose both resident indexed images into the row
  // buffer and issue one continuous transaction. This mirrors GBA BLDALPHA
  // and makes it impossible for the LCD to expose a half-painted terrain
  // between the two layers.
  const bool baseResident = basePlane.path &&
      AssetRenderer::isPreloaded(basePlane.path);
  const bool fieldResident = !hasField ||
      (fieldPlane.path && AssetRenderer::isPreloaded(fieldPlane.path));
  bool baseDrawn = hasField && AssetRenderer::drawPlaneComposite(
      display, basePlane, fieldPlane, 0, 0, 320U, 184U);
  if (hasField && !baseDrawn) {
    // Keep this as a diagnostic event even when the validated terrain-only
    // recovery below succeeds; it identifies a missing task plane without
    // turning that recoverable field miss into a black frame.
    recordBattleRenderFailure(1U, basePlane.path, fieldPlane.path,
                              baseResident, fieldResident);
  }
  if (!baseDrawn) {
    if (hasField) {
      // Never stream the field after a failed atomic composition.  That path
      // used to paint the terrain and field in separate TFT transactions,
      // which could leave a corrupt full-screen plane when the next move
      // changed scenes.  Recover with the validated base only; the next
      // animation preload will retry the complete field manifest.
      Serial.printf("[GFX] atomic field composition skipped base=%s field=%s\n",
                    basePlane.path ? basePlane.path : "?",
                    fieldPlane.path ? fieldPlane.path : "?");
    }
    if (basePlane.wrap || basePlane.paletteCount ||
        basePlane.sourceOffsetX || basePlane.sourceOffsetY ||
        basePlane.scaleNumerator != 1U || basePlane.scaleDenominator != 1U) {
      baseDrawn = AssetRenderer::drawScrolled(
          display, basePlane.path, 0, 0, 320U, 184U,
          basePlane.sourceOffsetX, basePlane.sourceOffsetY, 16U,
          basePlane.paletteFirst, basePlane.paletteCount,
          basePlane.paletteShift, basePlane.scaleNumerator,
          basePlane.scaleDenominator, basePlane.wrapX, basePlane.wrapY,
          basePlane.virtualSourceWidth, basePlane.virtualSourceHeight,
          basePlane.virtualFillIndex);
    } else {
      baseDrawn = AssetRenderer::draw(display, basePlane.path, 0, 0);
    }
  }
  if (!baseDrawn) {
#if defined(POKEGOCHI_ANDROID)
    // A move background is an optional visual plane on Android.  An older
    // archive, a just-evicted plane, or a transient cache miss must not turn
    // the whole battle transaction into a permanent PRESENT_CANCEL loop.  The
    // canonical terrain is already resident for every battle; use it as the
    // opaque base and keep the authored OBJ/task layers above it.  This keeps
    // the journal advancing while the move still has a valid battle scene.
    const bool movePlaneMissing = basePlane.path &&
        std::strcmp(basePlane.path, terrainPath) != 0;
    if (movePlaneMissing && AssetRenderer::isPreloaded(terrainPath)) {
      baseDrawn = AssetRenderer::draw(display, terrainPath, 0, 0);
      if (baseDrawn) {
        static uint32_t lastAndroidBattlePlaneFallback = 0U;
        uint32_t pathHash = 2166136261UL;
        for (const char* cursor = basePlane.path; cursor && *cursor; ++cursor)
          pathHash = (pathHash ^ static_cast<uint8_t>(*cursor)) * 16777619UL;
        if (lastAndroidBattlePlaneFallback != pathHash) {
          lastAndroidBattlePlaneFallback = pathHash;
          Serial.printf("[GFX] Android move plane miss; terrain fallback path=%s\n",
                        basePlane.path);
        }
      }
    }
#endif
  }
  if (!baseDrawn) {
#if defined(POKEGOCHI_ANDROID)
    // Android must never turn a transient scene-bank miss into a permanent
    // battle journal lock.  The r148 capture showed the canonical terrain
    // preloading successfully and then disappearing before the next retained
    // stripe; every HP sample consequently retried frame 1 forever.  Keep the
    // animation and battle state alive with an opaque procedural arena until
    // the next normal scene preparation restores the indexed terrain.  This
    // path is strictly a recovery plane: authored backgrounds and battler/task
    // sprites still win whenever their resident assets are available.
    const char* terrainName = terrain ? terrain : "";
    uint16_t sky = 0xBDF7;
    uint16_t ground = 0x9D13;
    uint16_t line = 0x7BEF;
    if (std::strcmp(terrainName, "sand") == 0) {
      sky = 0xFFDF; ground = 0xE6B2; line = 0xC5A8;
    } else if (std::strcmp(terrainName, "water") == 0 ||
               std::strcmp(terrainName, "pond") == 0 ||
               std::strcmp(terrainName, "underwater") == 0) {
      sky = 0x7DFF; ground = 0x3D19; line = 0x2C92;
    } else if (std::strcmp(terrainName, "cave") == 0 ||
               std::strcmp(terrainName, "mountain") == 0) {
      sky = 0x6B4D; ground = 0x4228; line = 0x2945;
    } else if (std::strcmp(terrainName, "building") == 0 ||
               std::strcmp(terrainName, "indoor") == 0 ||
               std::strcmp(terrainName, "indoor_2") == 0) {
      sky = 0xD69A; ground = 0xB596; line = 0x8C71;
    }
    display.fillRect(0, 0, 320, 184, sky);
    display.fillRect(0, 96, 320, 88, ground);
    for (int16_t y = 104; y < 184; y += 16)
      display.drawFastHLine(0, y, 320, line);
    for (int16_t x = -32; x < 320; x += 32)
      display.drawFastVLine(x, 96, 88, line);
    static uint32_t lastAndroidTerrainFallbackHash = 0U;
    uint32_t pathHash = 2166136261UL;
    for (const char* cursor = basePlane.path; cursor && *cursor; ++cursor)
      pathHash = (pathHash ^ static_cast<uint8_t>(*cursor)) * 16777619UL;
    if (lastAndroidTerrainFallbackHash != pathHash) {
      lastAndroidTerrainFallbackHash = pathHash;
      Serial.printf("[GFX] Android battle terrain recovery fallback path=%s\n",
                    basePlane.path ? basePlane.path : "?");
    }
    baseDrawn = true;
#endif
  }
  if (!baseDrawn) {
    // Preserve the last valid arena instead of replacing it with a white
    // rectangle.  The caller's manifest validation will abort this move before
    // normal playback when the base scene is genuinely missing.
    Serial.printf("[GFX] battle base unavailable path=%s\n",
                  basePlane.path ? basePlane.path : "?");
    recordBattleRenderFailure(2U, basePlane.path, fieldPlane.path,
                              baseResident, fieldResident);
    battleFrameCompositionFailed = true;
    return;
  }
  if (battleVisualOverlay.active && battleVisualOverlay.blackWindow) {
    const int16_t left = std::clamp<int16_t>(
        battleVisualOverlay.blackWindowLeft, 0, 320);
    const int16_t top = std::clamp<int16_t>(
        battleVisualOverlay.blackWindowTop, 0, 184);
    const int16_t right = std::clamp<int16_t>(
        battleVisualOverlay.blackWindowRight, left, 320);
    const int16_t bottom = std::clamp<int16_t>(
        battleVisualOverlay.blackWindowBottom, top, 184);
    if (right > left && bottom > top)
      display.fillRect(left, top, right - left, bottom - top, TFT_BLACK);
  }
  drawBattleArenaPaletteEffect();
  // A fade-to-background is a transition plane, not an OBJ effect.  Most
  // fade frames contain no particles and still cover the complete scene as
  // they do on the GBA.  If a script overlaps a fade with an OBJ, however,
  // the transition must stay below that OBJ; drawing it after the foreground
  // was the source of black/coloured bands covering Moonlight, Confuse Ray
  // and several other effects.
  const bool fadeAboveObjects = battleVisualOverlay.active &&
      battleVisualLayerCount() == 0U &&
      battleVisualOverlay.primitive == BattleVisualPrimitive::None;
  if (!fadeAboveObjects) drawBattleArenaFade();
  // One compositor owns every battle frame, including dirty animation
  // updates. FireRed's order is BG terrain -> move BG/field -> battler OBJ ->
  // foreground OBJ -> HUD. Keeping this order here prevents effects from
  // changing depth or covering HP panels depending on which code path caused
  // a repaint.
  OwnedPokemon playerVisual{},opponentVisual{};
  if(player){playerVisual=*player;playerVisual.form=playerForm;}
  if(opponent){opponentVisual=*opponent;opponentVisual.form=opponentForm;}
  const bool playerBackgroundLayer = battleVisualOverlay.active &&
      battleVisualOverlay.playerInBackgroundLayer;
  const bool opponentBackgroundLayer = battleVisualOverlay.active &&
      battleVisualOverlay.opponentInBackgroundLayer;
  // monbg copies a battler into BG1/BG2 before OBJ effects are emitted.  Draw
  // that battler first, then the script's behind-OBJ group.  Ordinary
  // battlers stay between the behind/front particle groups.
  if(!hideOpponent&&opponent&&opponentBackgroundLayer)
    creature(opponentX,opponentY,opponentVisual,true,opponentSpeciesId);
  if(!hidePlayer&&player&&playerBackgroundLayer)
    battleBackSprite(playerX,playerY,playerVisual,playerSpeciesId);
  drawBattleTransformedBattlers(true);
#if defined(POKEGOCHI_ANDROID)
  static uint16_t lastLoggedPsychicArenaFrame = 0xFFFFU;
  if (tracePsychicMove(battleAnimationCurrentMove) &&
      lastLoggedPsychicArenaFrame != battleAnimationRuntimeFrame) {
    lastLoggedPsychicArenaFrame = battleAnimationRuntimeFrame;
    Serial.printf("[CONF_TRACE] arena frame=%u active=%u primitive=%u psychic=%u requested=%u rendering=%u\n",
                  static_cast<unsigned>(battleAnimationRuntimeFrame),
                  battleVisualOverlay.active ? 1U : 0U,
                  static_cast<unsigned>(battleVisualOverlay.primitive),
                  battleVisualOverlay.psychicFieldActive ? 1U : 0U,
                  retainedFrameRequested ? 1U : 0U,
                  renderingRetainedFrame ? 1U : 0U);
  }
#endif
  drawBattleVisualPhase(true);
  if(!hideOpponent&&opponent&&!opponentBackgroundLayer)
    creature(opponentX,opponentY,opponentVisual,true,opponentSpeciesId);
  if(!hidePlayer&&player&&!playerBackgroundLayer)
    battleBackSprite(playerX,playerY,playerVisual,playerSpeciesId);
  drawBattleTransformedBattlers(false);
  // FireRed clips Curse's falling BG1 lines through the attacker's OBJ
  // silhouette. Keep the line plane resident and apply that same mask here,
  // instead of exposing the 64x64 rectangle around the Pokemon.
  if (!hideOpponent && opponent && opponentSpeciesId)
    drawBattleCurseMask(opponentVisual, opponentSpeciesId, opponentForm, true,
                        opponentX, opponentY);
  if (!hidePlayer && player && playerSpeciesId)
    drawBattleCurseMask(playerVisual, playerSpeciesId, playerForm, false,
                        playerX, playerY);
  if (!hideOpponent && opponent && opponentSpeciesId)
    drawBattleStatusClearMask(opponentVisual, opponentSpeciesId, opponentForm,
                              true, opponentX, opponentY);
  if (!hidePlayer && player && playerSpeciesId)
    drawBattleStatusClearMask(playerVisual, playerSpeciesId, playerForm,
                              false, playerX, playerY);
  if (battleVisualOverlay.active && battleVisualOverlay.metallic)
    AssetRenderer::drawMetallic(display, battleVisualOverlay.metallicPath,
                                battleVisualOverlay.metallicX,
                                battleVisualOverlay.metallicY,
                                battleVisualOverlay.metallicPhase);
  drawBattleVisualPhase(false);
  if (fadeAboveObjects) drawBattleArenaFade();
  if (!hideOpponent && opponent && opponent->shiny && clipIntersectsY(
          battleShinyMarkerY(true),
          static_cast<int16_t>(battleShinyMarkerY(true) + kBattleShinyMarkerSize)))
    drawBattleShinyMarker(true);
  if (!hidePlayer && player && player->shiny && clipIntersectsY(
          battleShinyMarkerY(false),
          static_cast<int16_t>(battleShinyMarkerY(false) + kBattleShinyMarkerSize)))
    drawBattleShinyMarker(false);
  // HUD is always the top plane. A projectile may cross behind a status box
  // in FireRed, but must never erase its text, HP bar or party indicators.
  if (clipIntersectsY(9, 61))
    drawBattleStatusBox(8, 9, 146, foeSpecies, opponent, false);
  if (clipIntersectsY(105, 162))
    drawBattleStatusBox(164, 105, 148, playerSpecies, player, true);
  if (clipIntersectsY(51, 103)) drawBattleTeamIndicators();
  battleArenaVisible = true;
  battleArenaPlayerUid = player ? player->uid : 0U;
  battleArenaOpponentUid = opponent ? opponent->uid : 0U;
  battleArenaPlayerSpeciesId = playerSpeciesId;
  battleArenaOpponentSpeciesId = opponentSpeciesId;
  battleArenaPlayerForm = playerForm;
  battleArenaOpponentForm = opponentForm;
}

void drawBattleTransformedBattlers(bool backgroundLayer) {
  if (!battleVisualOverlay.active) return;
  const auto clipCoordinate = [](uint8_t clip, uint16_t extent) -> uint16_t {
    // Animation tasks use the original FireRed 64px battler space.  Scale
    // those clip coordinates to native Platinum's 80px assets instead of
    // cropping the right/bottom 16px or moving the visible centre.
    return static_cast<uint16_t>(std::min<uint32_t>(
        extent, (static_cast<uint32_t>(clip) * extent + 32U) / 64U));
  };
  OwnedPokemon* player = presentedBattlePlayer();
  OwnedPokemon* opponent = presentedBattleOpponent();
  const bool hidePlayer = battlePresentationPlayerHidden ||
      battleVisualOverlay.hidePlayer;
  const bool hideOpponent = battleCaptureOpponentHidden ||
      battlePresentationOpponentHidden || battleVisualOverlay.hideOpponent;
  const bool drawPlayer = player && !hidePlayer &&
      (battleVisualOverlay.playerScaleX != 100U ||
       battleVisualOverlay.playerScaleY != 100U ||
       battleVisualOverlay.playerRotation != 0U ||
       battleVisualOverlay.playerColorEffect != AssetColorEffect::None ||
       battleVisualOverlay.playerClipTop != 0U ||
       battleVisualOverlay.playerClipBottom != 64U);
  const bool drawOpponent = opponent && !hideOpponent &&
      (battleVisualOverlay.opponentScaleX != 100U ||
       battleVisualOverlay.opponentScaleY != 100U ||
       battleVisualOverlay.opponentRotation != 0U ||
       battleVisualOverlay.opponentColorEffect != AssetColorEffect::None ||
       battleVisualOverlay.opponentClipTop != 0U ||
       battleVisualOverlay.opponentClipBottom != 64U);
  if (drawPlayer && battleVisualOverlay.playerInBackgroundLayer == backgroundLayer) {
    const uint16_t speciesId = presentedBattleSpeciesId(player, true);
    OwnedPokemon visual = *player;
    visual.form = presentedBattleForm(player, true);
    char path[112]{};
    pokemonAssetPath(path, sizeof(path), visual, PokemonAssetView::Back, 0, speciesId);
    const uint8_t clipTop = battleVisualOverlay.playerClipTop;
    const uint8_t clipBottom = battleVisualOverlay.playerClipBottom;
    if (clipTop != 0U || clipBottom != 64U) {
      uint16_t width = 64U;
      uint16_t height = 64U;
      uint16_t residentWidth = 0U;
      uint16_t residentHeight = 0U;
      if (AssetRenderer::dimensions(path, residentWidth, residentHeight) &&
          residentWidth != 0U && residentHeight != 0U) {
        width = residentWidth;
        height = residentHeight;
      }
      const uint16_t sourceTop = clipCoordinate(clipTop, height);
      const uint16_t sourceBottom = clipCoordinate(clipBottom, height);
      const int16_t centerX = static_cast<int16_t>(
          kBattlePlayerX + battleVisualOverlay.playerOffsetX);
      const int16_t centerY = static_cast<int16_t>(
          kBattlePlayerY + battleVisualOverlay.playerOffsetY +
          std::abs(battleAnimationSin(battleVisualOverlay.playerRotation, 32)));
      if (sourceBottom > sourceTop)
        AssetRenderer::drawRegion(display, path,
            static_cast<int16_t>(centerX - width / 2U),
            static_cast<int16_t>(centerY - height / 2U + sourceTop),
            0U, sourceTop, width,
            static_cast<uint16_t>(sourceBottom - sourceTop));
    } else {
      AssetRenderer::drawAffine(
          display, path,
          static_cast<int16_t>(kBattlePlayerX + battleVisualOverlay.playerOffsetX),
          static_cast<int16_t>(kBattlePlayerY + battleVisualOverlay.playerOffsetY +
              std::abs(battleAnimationSin(battleVisualOverlay.playerRotation, 32))),
          battleVisualOverlay.playerScaleX, battleVisualOverlay.playerScaleY,
          battleVisualOverlay.playerRotation, 16U,
          battleVisualOverlay.playerColorEffect, battleVisualOverlay.playerBlendColor,
          battleVisualOverlay.playerBlendAmount);
    }
  }
  if (drawOpponent && battleVisualOverlay.opponentInBackgroundLayer == backgroundLayer) {
    const uint16_t speciesId = presentedBattleSpeciesId(opponent, false);
    OwnedPokemon visual = *opponent;
    visual.form = presentedBattleForm(opponent, false);
    char path[112]{};
    pokemonAssetPath(path, sizeof(path), visual, PokemonAssetView::Front, 0, speciesId);
    const uint8_t clipTop = battleVisualOverlay.opponentClipTop;
    const uint8_t clipBottom = battleVisualOverlay.opponentClipBottom;
    if (clipTop != 0U || clipBottom != 64U) {
      uint16_t width = 64U;
      uint16_t height = 64U;
      uint16_t residentWidth = 0U;
      uint16_t residentHeight = 0U;
      if (AssetRenderer::dimensions(path, residentWidth, residentHeight) &&
          residentWidth != 0U && residentHeight != 0U) {
        width = residentWidth;
        height = residentHeight;
      }
      const uint16_t sourceTop = clipCoordinate(clipTop, height);
      const uint16_t sourceBottom = clipCoordinate(clipBottom, height);
      const int16_t centerX = static_cast<int16_t>(
          kBattleOpponentX + battleVisualOverlay.opponentOffsetX);
      const int16_t centerY = static_cast<int16_t>(
          kBattleOpponentY + battleVisualOverlay.opponentOffsetY +
          std::abs(battleAnimationSin(battleVisualOverlay.opponentRotation, 32)));
      if (sourceBottom > sourceTop)
        AssetRenderer::drawRegion(display, path,
            static_cast<int16_t>(centerX - width / 2U),
            static_cast<int16_t>(centerY - height / 2U + sourceTop),
            0U, sourceTop, width,
            static_cast<uint16_t>(sourceBottom - sourceTop));
    } else {
      AssetRenderer::drawAffine(
          display, path,
          static_cast<int16_t>(kBattleOpponentX + battleVisualOverlay.opponentOffsetX),
          static_cast<int16_t>(kBattleOpponentY + battleVisualOverlay.opponentOffsetY +
              std::abs(battleAnimationSin(battleVisualOverlay.opponentRotation, 32))),
          battleVisualOverlay.opponentScaleX, battleVisualOverlay.opponentScaleY,
          battleVisualOverlay.opponentRotation, 16U,
          battleVisualOverlay.opponentColorEffect, battleVisualOverlay.opponentBlendColor,
          battleVisualOverlay.opponentBlendAmount);
    }
  }
}

bool battleRectIntersects(int16_t leftA, int16_t topA, int16_t widthA, int16_t heightA,
                          int16_t leftB, int16_t topB, int16_t widthB, int16_t heightB) {
  return leftA < leftB + widthB && leftA + widthA > leftB &&
         topA < topB + heightB && topA + heightA > topB;
}

// Paint just the static layers concealed by a transient animation. The
// terrain is cached as an indexed large asset, and the two battler sprites
// are in the compact cache, so this path never opens the microSD card.
bool restoreBattleRegion(int16_t x, int16_t y, uint16_t width, uint16_t height, bool hideOpponent) {
  hideOpponent = hideOpponent || battleCaptureOpponentHidden || battlePresentationOpponentHidden ||
      (battleVisualOverlay.active && battleVisualOverlay.hideOpponent);
  const bool hidePlayer = battlePresentationPlayerHidden ||
      (battleVisualOverlay.active && battleVisualOverlay.hidePlayer);
  const int16_t playerX = static_cast<int16_t>(kBattlePlayerX +
      (battleVisualOverlay.active ? battleVisualOverlay.playerOffsetX : 0));
  const int16_t playerY = static_cast<int16_t>(kBattlePlayerY +
      (battleVisualOverlay.active ? battleVisualOverlay.playerOffsetY : 0));
  const int16_t opponentX = static_cast<int16_t>(kBattleOpponentX +
      (battleVisualOverlay.active ? battleVisualOverlay.opponentOffsetX : 0));
  const int16_t opponentY = static_cast<int16_t>(kBattleOpponentY +
      (battleVisualOverlay.active ? battleVisualOverlay.opponentOffsetY : 0));
  const int16_t right = std::min<int16_t>(320, static_cast<int16_t>(x + width));
  const int16_t bottom = std::min<int16_t>(184, static_cast<int16_t>(y + height));
  const int16_t left = std::max<int16_t>(0, x);
  const int16_t top = std::max<int16_t>(0, y);
  if (right <= left || bottom <= top) return true;
  // Dirty restoration must use the same authoritative compositor as every
  // other battle frame. The legacy code below is intentionally bypassed: it
  // separately rebuilt terrain, move BG, battlers and HUD and therefore could
  // disagree with drawBattleArena() about monbg/affine/visibility state.
  // The retained presenter clips the repaint to this exact rectangle and
  // never exposes an intermediate terrain-only frame on the physical TFT.
  (void)hideOpponent;
  invalidatePixels(left, top, right - left, bottom - top);
  requestRetainedFrame();
  presentRetainedFrame();
  return true;
#if 0  // Historical compositor retained temporarily for source-level comparison.
  const uint16_t clippedWidth = static_cast<uint16_t>(right - left);
  const uint16_t clippedHeight = static_cast<uint16_t>(bottom - top);
  if (clippedWidth > 96U || clippedHeight > 96U) return false;

  OwnedPokemon* player = presentedBattlePlayer();
  OwnedPokemon* opponent = presentedBattleOpponent();
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  const char* terrain = chooseBattleTerrain(opponent);
  char terrainPath[80];
  std::snprintf(terrainPath, sizeof(terrainPath), "/pokegochi/assets/firered/battle_terrain/%s.pkg", terrain);
  // Recompose the terrain and both battlers into the *same* RAM dirty tile.
  // The old implementation first pushed terrain, then pushed a battler and
  // finally a particle in separate transactions.  That exposed the empty
  // terrain for a frame and read as a flash, especially over the grass.
  char playerPath[112]{}, opponentPath[112]{};
  AssetOverlay overlays[4]{};
  uint8_t overlayCount = 0;
  OwnedPokemon playerVisual{},opponentVisual{};
  if(player){playerVisual=*player;playerVisual.form=playerForm;}
  if(opponent){opponentVisual=*opponent;opponentVisual.form=opponentForm;}
  // An active changebg is an opaque 240x160 FireRed BG layer between terrain
  // and battlers. Include it in local restoration too; restoring from terrain
  // alone produced rectangular holes behind moving particles.
  const char* basePath = terrainPath;
  // Static 320x184 move backgrounds are already the complete opaque base and
  // can be sampled directly for a dirty rectangle. Scrolling/palette-cycled
  // 256x256 tilemaps remain an overlay because their source coordinates wrap.
  const bool backgroundAsBase = battleVisualOverlay.active &&
      battleVisualOverlay.backgroundPath[0] &&
      !battleVisualOverlay.backgroundWrap &&
      !battleVisualOverlay.backgroundPaletteCount;
  if (backgroundAsBase)
    basePath = battleVisualOverlay.backgroundPath;
  else if (battleVisualOverlay.active && battleVisualOverlay.backgroundPath[0]) {
    AssetOverlay& background = overlays[overlayCount++];
    background.path = battleVisualOverlay.backgroundPath;
    background.x = 0;
    background.y = 0;
    background.width = 320U;
    background.height = 184U;
    background.sourceOffsetX = battleVisualOverlay.backgroundOffsetX;
    background.sourceOffsetY = battleVisualOverlay.backgroundOffsetY;
    background.paletteFirst = battleVisualOverlay.backgroundPaletteFirst;
    background.paletteCount = battleVisualOverlay.backgroundPaletteCount;
    background.paletteShift = battleVisualOverlay.backgroundPaletteShift;
    background.wrap = battleVisualOverlay.backgroundWrap;
    background.scaleNumerator = battleVisualOverlay.backgroundNativeCamera ? 4U : 1U;
    background.scaleDenominator = battleVisualOverlay.backgroundNativeCamera ? 3U : 1U;
    background.virtualSourceWidth = battleVisualOverlay.backgroundVirtualWidth;
    background.virtualSourceHeight = battleVisualOverlay.backgroundVirtualHeight;
    background.virtualFillIndex = battleVisualOverlay.backgroundVirtualFillIndex;
  }
  if (battleVisualOverlay.active && battleVisualOverlay.fieldAsset !=
          BattleFieldAsset::None && battleVisualOverlay.fieldOpacity) {
    AssetOverlay& field = overlays[overlayCount++];
    field.path = battleAnimationFieldPath(battleVisualOverlay.fieldAsset);
    field.x = battleVisualOverlay.fieldDestinationX;
    field.y = battleVisualOverlay.fieldDestinationY;
    field.width = battleVisualOverlay.fieldWidth;
    field.height = battleVisualOverlay.fieldHeight;
    field.sourceOffsetX = battleVisualOverlay.fieldOffsetX;
    field.sourceOffsetY = battleVisualOverlay.fieldOffsetY;
    field.opacity16 = battleVisualOverlay.fieldOpacity;
    field.paletteFirst = battleVisualOverlay.fieldPaletteFirst;
    field.paletteCount = battleVisualOverlay.fieldPaletteCount;
    field.paletteShift = battleVisualOverlay.fieldPaletteShift;
    field.wrap = battleVisualOverlay.fieldWrap;
    field.wrapX = battleVisualOverlay.fieldWrapX;
    field.wrapY = battleVisualOverlay.fieldWrapY;
    field.scaleNumerator = battleVisualOverlay.fieldNativeCamera ? 4U : 1U;
    field.scaleDenominator = battleVisualOverlay.fieldNativeCamera ? 3U : 1U;
  }
  if (!hidePlayer && player && playerSpeciesId) {
    pokemonAssetPath(playerPath, sizeof(playerPath), playerVisual,
                     PokemonAssetView::Back, 0, playerSpeciesId);
    int16_t originX = 0;
    int16_t originY = 0;
    centeredPokemonAssetOrigin(playerPath, playerX, playerY, 64U, 64U,
                               originX, originY);
    overlays[overlayCount++] = {playerPath, originX, originY};
  }
  if (!hideOpponent && opponent && opponentSpeciesId) {
    pokemonAssetPath(opponentPath, sizeof(opponentPath), opponentVisual,
                     PokemonAssetView::Front, 0, opponentSpeciesId);
    int16_t originX = 0;
    int16_t originY = 0;
    centeredPokemonAssetOrigin(opponentPath, opponentX, opponentY, 64U, 64U,
                               originX, originY);
    overlays[overlayCount++] = {opponentPath, originX, originY};
  }
  if (!AssetRenderer::drawCompositeRegion(display, basePath, nullptr, left, top,
                                           static_cast<uint16_t>(left), static_cast<uint16_t>(top),
                                           clippedWidth, clippedHeight, overlays, overlayCount)) {
    // A scene cache can only be lost when another screen was drawn. Recover
    // once with a complete frame; normal animation frames never use this.
    drawBattleArena(player, opponent, hideOpponent);
    return false;
  }

  const SpeciesData* foeSpecies = findSpecies(opponentSpeciesId);
  const SpeciesData* playerSpecies = findSpecies(playerSpeciesId);
  if (battleRectIntersects(left, top, clippedWidth, clippedHeight, 8, 9, 151, 51))
    drawBattleStatusBox(8, 9, 146, foeSpecies, opponent, false);
  if (battleRectIntersects(left, top, clippedWidth, clippedHeight, 164, 105, 153, 56))
    drawBattleStatusBox(164, 105, 148, playerSpecies, player, true);
  if (!hideOpponent && opponent && opponent->shiny &&
      battleRectIntersects(left, top, clippedWidth, clippedHeight,
                           battleShinyMarkerX(true), battleShinyMarkerY(true),
                           kBattleShinyMarkerSize, kBattleShinyMarkerSize))
    drawBattleShinyMarker(true);
  if (!hidePlayer && player && player->shiny &&
      battleRectIntersects(left, top, clippedWidth, clippedHeight,
                           battleShinyMarkerX(false), battleShinyMarkerY(false),
                           kBattleShinyMarkerSize, kBattleShinyMarkerSize))
    drawBattleShinyMarker(false);
  if (battleRectIntersects(left, top, clippedWidth, clippedHeight, 0, 51, 320, 52))
    drawBattleTeamIndicators();
  return true;
#endif
}

void drawBattlePromptAndCommands(OwnedPokemon* player) {
  const bool replacingMovePicker = moveSelectVisible;
  moveSelectVisible = false;
  renderedMoveConfirmSlot = -2;
  // MOVE SELECT owns most of the bottom eighty pixels. Returning to the
  // regular command grid is a local surface transition, so clear exactly
  // that old panel once; without this, its left white cells survive below
  // the prompt and look like the black/white battle bar reported on-device.
  if (replacingMovePicker) display.fillRect(0, 160, 320, 80, TFT_BLACK);
  if (battleFlow.phase != BattleFlowPhase::Idle) {
    drawFireRedBattleWindow(0, 160, 320, 80, kBattleFrameGold, themePrimary());
    fireRedText.setTextColor(TFT_WHITE, themePrimary());
    battlePromptLineCount = fireRedText.drawTextBox(message, 12, 171, 296, 58,
                                                    battlePromptScroll);
    if (battlePromptLineCount > static_cast<uint8_t>(battlePromptScroll + 3U))
      display.fillTriangle(292, 220, 306, 220, 299, 228, TFT_RED);
    else
      // FireRed's dialogue cursor: the event journal is paused until the
      // player taps. It is deliberately absent while animations run.
      display.fillTriangle(296, 220, 306, 220, 301, 228, TFT_WHITE);
    return;
  }
  const SpeciesData* species = findSpecies(presentedBattleSpeciesId(player, true));
  char defaultPrompt[54];
  std::snprintf(defaultPrompt, sizeof(defaultPrompt), "WHAT WILL %s DO?",
                species ? species->name : "POKEMON");
  const char* prompt = message[0] ? message : defaultPrompt;
  // Once the battle has ended there is no command grid on the right.  Treat
  // the victory/EXP result as one FireRed-style message surface spanning the
  // complete lower HUD instead of leaving the old half-width prompt panel.
  if (!gameSave.battle.active) {
    drawFireRedBattleWindow(0, 160, 320, 80, kBattleFrameGold, themePrimary());
    fireRedText.setTextColor(TFT_WHITE, themePrimary());
    battlePromptLineCount = fireRedText.drawTextBox(prompt, 12, 171, 296, 22,
                                                    battlePromptScroll);
    button(92, 200, 136, 32, "CONTINUE", TFT_DARKGREEN);
    return;
  }
  drawFireRedBattleWindow(0, 160, 154, 80, kBattleFrameGold, themePrimary());
  fireRedText.setTextColor(TFT_WHITE, themePrimary());
  battlePromptLineCount = fireRedText.drawTextBox(prompt, 10, 169, 134, 62, battlePromptScroll);
  if (battlePromptLineCount > static_cast<uint8_t>(battlePromptScroll + 3U))
    display.fillTriangle(132, 222, 144, 222, 138, 229, TFT_RED);
  else if (message[0] && !std::strstr(message, "WAITING") &&
           !std::strstr(message, "LOCKED") && !std::strstr(message, "SYNCING"))
    display.fillTriangle(134, 221, 144, 221, 139, 229, TFT_WHITE);

  // The command pane follows FireRed's two-by-two menu instead of four
  // modern rounded buttons.  The small triangle is deliberately fixed on
  // FIGHT because touch selects directly rather than moving a D-pad cursor.
  drawFireRedBattleWindow(151, 160, 169, 80, kBattleCommandFrame, kBattlePaper);
  display.drawFastVLine(234, 166, 68, kBattleFrameGold);
  display.drawFastHLine(157, 200, 157, kBattleFrameGold);
  display.fillTriangle(157, 181, 165, 176, 165, 186, TFT_DARKGREY);
  fireRedText.setTextColor(kBattleInk, kBattlePaper);
  fireRedText.drawString("FIGHT", 170, 176, 1);
  fireRedText.drawString("BAG", 253, 176, 1);
  fireRedText.drawString("POKEMON", 164, 212, 1);
  fireRedText.drawString("RUN", 253, 212, 1);

}

void drawBattleRunConfirmation() {
  if (!runConfirmVisible) return;
  // RUN is destructive because the foe receives its turn before escape is
  // resolved. Keep confirmation away from every battle command so a held
  // touch can never both open and accept it. This is its own arena overlay:
  // nesting it under the y>=160 command-pane painter made it disappear when
  // the ESP32 retained presenter recomposed only the modal's y=46..144 bands.
  drawFireRedBattleWindow(BattleTouch::kRunConfirmationX,
                          BattleTouch::kRunConfirmationY,
                          BattleTouch::kRunConfirmationWidth,
                          BattleTouch::kRunConfirmationHeight,
                          kBattleCommandFrame, kBattlePaper);
  display.drawFastHLine(115, 78, 90, kBattleFrameGold);
  display.drawFastHLine(115, 106, 90, kBattleFrameGold);
  fireRedText.setTextColor(kBattleInk, kBattlePaper);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString("RUN?", 160, 66, 1);
  fireRedText.drawString("OK", 160, 92, 1);
  fireRedText.drawString("CANCEL", 160, 120, 1);
  fireRedText.setTextDatum(TL_DATUM);
}

void invalidateRunConfirmation() {
  invalidatePixels(BattleTouch::kRunConfirmationDamageX,
                   BattleTouch::kRunConfirmationDamageY,
                   BattleTouch::kRunConfirmationDamageWidth,
                   BattleTouch::kRunConfirmationDamageHeight);
  requestRetainedFrame();
}

void openRunConfirmation() {
  if (runConfirmVisible) return;
  runConfirmVisible = true;
  invalidateRunConfirmation();
  Serial.println("[RUN_MODAL] open requested");
}

void closeRunConfirmation() {
  if (!runConfirmVisible) return;
  runConfirmVisible = false;
  // Recompose the complete footprint, including the frame shadow.  The modal
  // sits over terrain, both battlers and both status cards, so restoring only
  // the old inner rectangle could leave its final rows resident on the TFT.
  // The retained presenter still transfers only changed pixels.
  invalidateRunConfirmation();
  Serial.println("[RUN_MODAL] close requested");
}

constexpr int16_t kLevelUpPanelX = 158;
constexpr int16_t kLevelUpPanelY = 8;
constexpr int16_t kLevelUpPanelW = 158;
constexpr int16_t kLevelUpPanelH = 152;

// FireRed's level-up window is deliberately an opaque overlay over the right
// half of the arena.  The first page contains +gains and the second the new
// totals; no element is omitted to fit the CYD's 320x240 landscape canvas.
void drawBattleLevelUpPanel() {
  if (battleFlow.levelUpPage == 0 ||
      battleFlow.levelUpSummaryIndex >= battleFlow.result.levelUpCount) return;
  const LevelUpSummary& summary = battleFlow.result.levelUps[battleFlow.levelUpSummaryIndex];
  static constexpr const char* labels[6] = {
    "MAX. HP", "ATTACK", "DEFENSE", "SP. ATK", "SP. DEF", "SPEED"
  };
  const uint16_t paper = 0xFFF4;
  const uint16_t stripe = 0xF6A6;
  const uint16_t ink = TFT_DARKGREY;
  display.fillRect(kLevelUpPanelX, kLevelUpPanelY, kLevelUpPanelW, kLevelUpPanelH, themePrimary());
  display.fillRect(kLevelUpPanelX + 3, kLevelUpPanelY + 3,
                   kLevelUpPanelW - 6, kLevelUpPanelH - 6, paper);
  display.fillRect(kLevelUpPanelX + 7, kLevelUpPanelY + 7,
                   kLevelUpPanelW - 14, 20, stripe);
  fireRedText.setTextColor(ink, stripe);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString(battleFlow.levelUpPage == 1 ? "STAT GAINS" : "NEW STATS",
                         kLevelUpPanelX + kLevelUpPanelW / 2, kLevelUpPanelY + 17, 1);
  fireRedText.setTextDatum(TL_DATUM);

  for (uint8_t index = 0; index < 6U; ++index) {
    const int16_t rowY = static_cast<int16_t>(kLevelUpPanelY + 32 + index * 18);
    if (index) display.drawFastHLine(kLevelUpPanelX + 9, rowY - 3,
                                     kLevelUpPanelW - 18, TFT_LIGHTGREY);
    fireRedText.setTextColor(ink, paper);
    fireRedText.setTextDatum(TL_DATUM);
    fireRedText.drawString(labels[index], kLevelUpPanelX + 11, rowY, 1);
    char value[10];
    if (battleFlow.levelUpPage == 1)
      std::snprintf(value, sizeof(value), "+%u", summary.gains[index]);
    else
      std::snprintf(value, sizeof(value), "%u", summary.stats[index]);
    fireRedText.setTextDatum(TR_DATUM);
    fireRedText.drawString(value, kLevelUpPanelX + kLevelUpPanelW - 11, rowY, 1);
  }
  fireRedText.setTextDatum(TL_DATUM);
  display.fillTriangle(kLevelUpPanelX + kLevelUpPanelW - 18,
                       kLevelUpPanelY + kLevelUpPanelH - 12,
                       kLevelUpPanelX + kLevelUpPanelW - 8,
                       kLevelUpPanelY + kLevelUpPanelH - 12,
                       kLevelUpPanelX + kLevelUpPanelW - 13,
                       kLevelUpPanelY + kLevelUpPanelH - 6, TFT_RED);
}

void refreshBattleHud() {
  OwnedPokemon* player = presentedBattlePlayer();
  OwnedPokemon* opponent = presentedBattleOpponent();
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  if (!battleArenaVisible || battleArenaPlayerUid != (player ? player->uid : 0U) ||
      battleArenaOpponentUid != (opponent ? opponent->uid : 0U) ||
      battleArenaPlayerSpeciesId != playerSpeciesId ||
      battleArenaOpponentSpeciesId != opponentSpeciesId ||
      battleArenaPlayerForm != playerForm || battleArenaOpponentForm != opponentForm) {
    drawBattle();
    return;
  }
  const SpeciesData* foeSpecies = findSpecies(opponentSpeciesId);
  const SpeciesData* playerSpecies = findSpecies(playerSpeciesId);
  // Cards are opaque, so their own redraw clears every changing digit/bar
  // without touching the scenery or either Pokémon sprite.
  drawBattleStatusBox(8, 9, 146, foeSpecies, opponent, false);
  drawBattleStatusBox(164, 105, 148, playerSpecies, player, true);
  drawBattleTeamIndicators();
  drawBattlePromptAndCommands(player);
  drawBattleLevelUpPanel();
  if (BattleTouch::runConfirmationIntersectsClip(
          display.logicalClipLeft(), display.logicalClipTop(),
          display.logicalClipRight(), display.logicalClipBottom()))
    drawBattleRunConfirmation();
}

void invalidateBattleHpCard(BattleSide side) {
  // HP animation mutates only the meter and, on the player's card, its
  // numeric value. Repainting the complete status box for every source tick
  // made the retained ESP32 renderer spend most of its time redrawing names,
  // borders, status, EXP and team icons. These bounds include the complete
  // old and new meter plus the numeric row, while the retained compositor
  // still reconstructs the canonical battle scene inside that rectangle.
  if (side == BattleSide::Player) {
    invalidatePixels(188, 124, 118, 27);
  } else {
    invalidatePixels(26, 28, 110, 11);
  }
}

// Full battle composition is a screen transition, never an animation frame.
// Effects can call this safely: if the arena is already on the display only
// its opaque HUD cards are refreshed.
void ensureBattleSceneForAnimation() {
  OwnedPokemon* player = presentedBattlePlayer();
  OwnedPokemon* opponent = presentedBattleOpponent();
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  if (screen != Screen::Battle && screen != Screen::MoveSelect) {
    screen = Screen::Battle;
    drawBattle();
    return;
  }
  if (!battleArenaVisible || battleArenaPlayerUid != (player ? player->uid : 0U) ||
      battleArenaOpponentUid != (opponent ? opponent->uid : 0U) ||
      battleArenaPlayerSpeciesId != playerSpeciesId ||
      battleArenaOpponentSpeciesId != opponentSpeciesId ||
      battleArenaPlayerForm != playerForm || battleArenaOpponentForm != opponentForm) {
    screen = Screen::Battle;
    drawBattle();
    return;
  }
  screen = Screen::Battle;
  refreshBattleHud();
}

enum class BattleEntrySide : uint8_t { Player, Opponent };

void setBattleEntryHidden(BattleEntrySide side, bool hidden) {
  if (side == BattleEntrySide::Player)
    battlePresentationPlayerHidden = hidden;
  else
    battlePresentationOpponentHidden = hidden;
}

void setBattleEntryScale(BattleEntrySide side, int16_t scale) {
  if (side == BattleEntrySide::Player) {
    battleVisualOverlay.playerScaleX = scale;
    battleVisualOverlay.playerScaleY = scale;
  } else {
    battleVisualOverlay.opponentScaleX = scale;
    battleVisualOverlay.opponentScaleY = scale;
  }
}

void playBattleEntrySide(BattleEntrySide side) {
  const bool playerSide = side == BattleEntrySide::Player;
  const int16_t targetX = playerSide ? kBattlePlayerX : kBattleOpponentX;
  const int16_t targetY = playerSide ? kBattlePlayerY : kBattleOpponentY;
  const int16_t startX = playerSide ? 36 : 284;
  const int16_t startY = playerSide ? 158 : 40;
  char ballPath[96]{};
  constexpr const char* kSparklePath =
      "/pokegochi/assets/firered/battle_anims/sprites/sparkle_1_00.pkg";

  // Six travel frames are enough to read the arc on the TFT. This happens on
  // every new battle, so it must stay a compact flourish rather than a
  // second loading screen.
  constexpr uint8_t kTravelFrames = 6U;
  for (uint8_t phase = 0; phase < kTravelFrames; ++phase) {
    const int16_t x = static_cast<int16_t>(startX +
        (targetX - startX) * phase / (kTravelFrames - 1U));
    const int16_t interpolatedY = static_cast<int16_t>(startY +
        (targetY - startY) * phase / (kTravelFrames - 1U));
    const int16_t arc = static_cast<int16_t>(
        24U * phase * (kTravelFrames - 1U - phase) / 25U);
    resetBattleVisualOverlay();
    battleBallAssetPath(ballPath, sizeof(ballPath), PokeBallType::PokeBall, 0U);
    addBattleVisualLayer(ballPath, x - 12, interpolatedY - arc - 12);
    showBattleVisualFrame(x - 28, interpolatedY - arc - 28, 56, 56, 24U);
  }

  // Opening frame: the battler stays hidden in the base composition until
  // this flash has landed, so no sprite leaks through the ball.
  resetBattleVisualOverlay();
  battleBallAssetPath(ballPath, sizeof(ballPath), PokeBallType::PokeBall, 1U);
  addBattleVisualLayer(ballPath, targetX - 12, targetY - 12);
  addBattleVisualLayer(kSparklePath, targetX + 10, targetY - 22);
  battleVisualOverlay.flash = true;
  battleVisualOverlay.flashColor = TFT_WHITE;
  showBattleVisualFrame(targetX - 42, targetY - 42, 84, 84, 42U);

  // The battler's real cached sprite scales in over five samples. No SD read
  // occurs here: drawBattleArena() prepared both battler assets before this
  // sequence started.
  setBattleEntryHidden(side, false);
  static constexpr int16_t kRevealScales[] = {28, 46, 64, 82, 98};
  for (uint8_t phase = 0;
       phase < sizeof(kRevealScales) / sizeof(kRevealScales[0]); ++phase) {
    resetBattleVisualOverlay();
    setBattleEntryScale(side, kRevealScales[phase]);
    if (phase < 3U) {
      addBattleVisualLayer(kSparklePath,
          static_cast<int16_t>(targetX - 18 + phase * 7),
          static_cast<int16_t>(targetY - 20 - phase * 3));
      addBattleVisualLayer(kSparklePath,
          static_cast<int16_t>(targetX + 18 - phase * 5),
          static_cast<int16_t>(targetY + 8 - phase * 2));
    }
    showBattleVisualFrame(targetX - 52, targetY - 52, 104, 104, 24U);
  }
  clearBattleVisualFrame(12U);
}

void playWildBattleEntryAnimation() {
  // FireRed and Emerald do not throw a ball for the wild battler.  Their
  // wild sprite is created off-screen, slides into its battle coordinate and
  // only then allows the health box/idle animation to finish.  Keep that
  // exact language here: a short horizontal reveal, no ball, no scale pop.
  setBattleEntryHidden(BattleEntrySide::Opponent, false);
  static constexpr int16_t kWildSlideOffsets[] = {
      -42, -36, -30, -24, -18, -12, -6, 0
  };
  for (uint8_t frame = 0;
       frame < sizeof(kWildSlideOffsets) / sizeof(kWildSlideOffsets[0]);
       ++frame) {
    resetBattleVisualOverlay();
    battleVisualOverlay.opponentOffsetX = kWildSlideOffsets[frame];
    showBattleVisualFrame(kBattleOpponentX - 68 + kWildSlideOffsets[frame],
                          kBattleOpponentY - 48, 116, 96, 24U);
  }
  // The source waits for the front sprite's first cel before showing the
  // healthbox.  One quiet retained frame gives the same readable landing
  // without adding a long loading-looking pause.
  resetBattleVisualOverlay();
  showBattleVisualFrame(kBattleOpponentX - 56, kBattleOpponentY - 44,
                        112, 92, 36U);
  clearBattleVisualFrame(8U);
}

void playBattleEntryAnimation() {
  // A wild opponent is already in the field. Only the player's battler is
  // released from a ball; trainer, boss and PvP opponents still use the
  // opposing trainer's send-out animation.
  battleCaptureOpponentHidden = false;
  if (gameSave.battle.kind == BattleKind::Wild) {
    playWildBattleEntryAnimation();
    preloadBallAnimation(PokeBallType::PokeBall);
  } else {
    preloadBallAnimation(PokeBallType::PokeBall);
    playBattleEntrySide(BattleEntrySide::Opponent);
  }
  playBattleEntrySide(BattleEntrySide::Player);
  battlePresentationPlayerHidden = false;
  battlePresentationOpponentHidden = false;
  resetBattleVisualOverlay();
  Serial.printf("[BATTLE] entry animation complete kind=%u\n",
                static_cast<unsigned>(gameSave.battle.kind));
}

void drawBattle() {
#if defined(POKEGOCHI_ANDROID)
  // A battle checkpoint can outlive the renderer process. Validate it again
  // at the exact resume boundary: this protects START as well as every later
  // return from Bag/Party/Move Select without touching the rest of the save.
  if (!prepareAndroidBattleRender("draw")) return;
#endif
  OwnedPokemon* player = presentedBattlePlayer();
  OwnedPokemon* opponent = presentedBattleOpponent();
  const uint16_t playerSpeciesId = presentedBattleSpeciesId(player, true);
  const uint16_t opponentSpeciesId = presentedBattleSpeciesId(opponent, false);
  const uint8_t playerForm = presentedBattleForm(player, true);
  const uint8_t opponentForm = presentedBattleForm(opponent, false);
  beginScreenPresentation(Screen::Battle, TFT_BLACK);
  // Returning from FIGHT, an item animation or the command confirmation
  // keeps this exact arena resident. The only pixels that must change are
  // the two HUD cards and command pane; do not blank the display first.
  // A retained animation frame is rebuilt off-screen through redrawCurrentScreen().
  // Even when the static arena is already resident, that composition must run
  // again while a move overlay is active; otherwise Android repaints only the
  // HUD and every frame after the first one becomes pixel-identical.
  if (!battleVisualOverlay.active && battleArenaVisible &&
      battleArenaPlayerUid == (player ? player->uid : 0U) &&
      battleArenaOpponentUid == (opponent ? opponent->uid : 0U) &&
      battleArenaPlayerSpeciesId == playerSpeciesId &&
      battleArenaOpponentSpeciesId == opponentSpeciesId &&
      battleArenaPlayerForm == playerForm && battleArenaOpponentForm == opponentForm) {
    refreshBattleHud();
    return;
  }
  // Battle owns the complete screen only when it is actually being entered.
  // Returning from MOVE SELECT shares the resident arena and skips this
  // clear; returning from Bag/Party is a real transition and gets one clean
  // composition before any battle pixels are drawn.
  // Entry animation is intentionally disabled for now. Consume the launch
  // latch so wild, trainer, PvP and series battles all open directly on the
  // normal arena while keeping the old presentation code available for a
  // later, better implementation.
  battleEntryAnimationPending = false;
  drawBattleArena(player, opponent);
  if (display.logicalClipBottom() > 160)
    drawBattlePromptAndCommands(player);
  if (battleFlow.levelUpPage != 0U &&
      display.logicalClipTop() < kLevelUpPanelY + kLevelUpPanelH &&
      display.logicalClipBottom() > kLevelUpPanelY)
    drawBattleLevelUpPanel();
  if (BattleTouch::runConfirmationIntersectsClip(
          display.logicalClipLeft(), display.logicalClipTop(),
          display.logicalClipRight(), display.logicalClipBottom()))
    drawBattleRunConfirmation();
}

void playBattleFaintAnimation(const BattleEvent& event) {
  OwnedPokemon* pokemon = event.side == BattleSide::Player
      ? CollectionLogic::find(gameSave.collection, event.pokemonUid)
      : battleOpponentByUid(event.pokemonUid);
  if (!pokemon || !pokemon->speciesId) return;
  ensureBattleSceneForAnimation();

  const uint16_t displayedSpeciesId = presentedBattleSpeciesId(
      pokemon, event.side == BattleSide::Player);
  OwnedPokemon visual=*pokemon;
  visual.form=presentedBattleForm(pokemon,event.side==BattleSide::Player);

  char path[112];
  pokemonAssetPath(path, sizeof(path), visual,
                   event.side == BattleSide::Player ? PokemonAssetView::Back : PokemonAssetView::Front,
                   0, displayedSpeciesId);
  AssetRenderer::preload(path);
  const int16_t centerX = event.side == BattleSide::Player ? kBattlePlayerX : kBattleOpponentX;
  const int16_t centerY = event.side == BattleSide::Player ? kBattlePlayerY : kBattleOpponentY;

  // Remove the battler from the retained base first, then carry its cached
  // sprite down over that base. This mirrors FireRed's faint drop without a
  // full-screen redraw and guarantees that the next opponent cannot leak
  // into the final frames.
  if (event.side == BattleSide::Player) battlePresentationPlayerHidden = true;
  else battlePresentationOpponentHidden = true;
  for (uint8_t step = 0; step < 4; ++step) {
    resetBattleVisualOverlay();
    int16_t originX = 0;
    int16_t originY = 0;
    centeredPokemonAssetOrigin(path, centerX,
                               static_cast<int16_t>(centerY + step * 8),
                               64U, 64U, originX, originY);
    addBattleVisualLayer(path, originX, originY);
    showBattleVisualFrame(centerX - 36, centerY - 36, 72, 94, 45);
  }
  clearBattleVisualFrame(25);
  // The faint flag changes the authoritative battle base.  Defer that full
  // composition to the next loop turn instead of letting the event presenter
  // immediately redraw the scene from inside this animation call.
  battleArenaVisible = false;
  invalidatePixels(0, 0, 320, 184);
  requestRetainedFrame();
}

// The battle picker is only two rows high on the 320px screen.  Shrinking a
// long move to the compact font made names such as ANCIENT POWER unreadable;
// instead, keep the normal FireRed glyphs and split the label over two lines.
void drawBattleMoveName(const char* name, int16_t x, int16_t y) {
  fireRedText.setTextDatum(MC_DATUM);
  if (!name || !name[0]) { fireRedText.drawString("---", x, y + 18, 2); fireRedText.setTextDatum(TL_DATUM); return; }
  const size_t length = std::strlen(name);
  if (length <= 7U) { fireRedText.drawString(name, x, y + 18, 2); fireRedText.setTextDatum(TL_DATUM); return; }

  // Prefer the original word/hyphen boundary nearest the middle.  A long
  // one-word move (e.g. SUPERPOWER) gets a clean character split instead of
  // silently falling back to tiny type-3 lettering.
  size_t split = 0, closest = length;
  const size_t middle = length / 2U;
  for (size_t index = 1; index + 1U < length; ++index) {
    if (name[index] != ' ' && name[index] != '-') continue;
    const size_t distance = index > middle ? index - middle : middle - index;
    if (distance < closest) { closest = distance; split = index; }
  }
  if (!split || split > 7U || length - split - (name[split] == ' ' ? 1U : 0U) > 7U)
    split = std::min<size_t>(6U, length - 1U);

  char first[12]{}, second[12]{};
  size_t firstLength = split;
  if (name[split] == '-') ++firstLength;  // retain DOUBLE- / SELF-.
  std::memcpy(first, name, std::min(firstLength, sizeof(first) - 1U));
  const bool splitOnSeparator = name[split] == ' ' || name[split] == '-';
  size_t secondStart = splitOnSeparator ? split + 1U : split;
  while (name[secondStart] == ' ') ++secondStart;
  std::strncpy(second, name + secondStart, sizeof(second) - 1U);
  // At most seven visible characters per row keeps the normal 16px type
  // safely inside the 88px move cell, including its black outline.
  first[7] = 0;
  second[7] = 0;
  fireRedText.drawString(first, x, y + 9, 2);
  fireRedText.drawString(second, x, y + 25, 2);
  fireRedText.setTextDatum(TL_DATUM);
}

// The move picker remains on screen while the player browses it.  A cursor
// tap therefore changes at most a 12x12 arrow and, when entering/leaving the
// confirmation state, the small 89x72 detail panel.  The four move labels
// are static and are never streamed or redrawn for a highlight change.
void refreshMoveSelectFocus(const OwnedPokemon* pokemon) {
  (void)pokemon;
  // Cursor, PP/TYPE and confirmation are one retained subscene. Recompose
  // its bounded regions atomically instead of maintaining two competing
  // cursor states with partial erases.
  invalidatePixels(0, 160, 320, 80);
  invalidatePixels(112, 54, 96, 60);
  requestRetainedFrame();
}

void drawMoveSelect() {
  const bool topLevelDraw = !renderingRetainedFrame;
  beginScreenPresentation(Screen::MoveSelect, TFT_BLACK);
  OwnedPokemon* pokemon = CollectionLogic::find(gameSave.collection, gameSave.battle.playerUid);
  OwnedPokemon* opponent = BattleEngine::currentOpponent(gameSave.battle);
  if (!gameSave.battle.active || battleFlow.phase != BattleFlowPhase::Idle ||
      !pokemon || !pokemon->currentHp || !opponent || !opponent->currentHp) {
    moveConfirmSlot = -1;
    moveSelectVisible = false;
    screen = Screen::Battle;
    drawBattle();
    return;
  }
  if (pokemon && CollectionLogic::ensureUsableMoves(*pokemon)) { saveDirty = true; saveNow(); }
  bool hasUsableMove = false;
  if (pokemon) for (uint8_t slot = 0; slot < kMoveSlots; ++slot)
    if (isMoveAvailableInSingleBattle(pokemon->moves[slot]) &&
        pokemon->movePp[slot] != 0 &&
        BattleEngine::moveIsSelectable(gameSave.battle,gameSave.collection,
                                       pokemon->moves[slot],BattleSide::Player)) {
      hasUsableMove = true; break;
    }
  if (pokemon && topLevelDraw) Serial.printf("[BATTLE] move picker uid=%lu moves=%u/%u/%u/%u pp=%u/%u/%u/%u\n",
                             static_cast<unsigned long>(pokemon->uid), static_cast<unsigned>(pokemon->moves[0]),
                             static_cast<unsigned>(pokemon->moves[1]), static_cast<unsigned>(pokemon->moves[2]),
                             static_cast<unsigned>(pokemon->moves[3]), pokemon->movePp[0], pokemon->movePp[1],
                             pokemon->movePp[2], pokemon->movePp[3]);
  // FIGHT only replaces the bottom command panel. Repainting the already
  // visible arena here was responsible for the flash on every tap.
  if (!battleArenaVisible || battleArenaPlayerUid != (pokemon ? pokemon->uid : 0U) ||
      battleArenaOpponentUid != (opponent ? opponent->uid : 0U) ||
      battleArenaPlayerSpeciesId != presentedBattleSpeciesId(pokemon, true) ||
      battleArenaOpponentSpeciesId != presentedBattleSpeciesId(opponent, false) ||
      battleArenaPlayerForm != presentedBattleForm(pokemon, true) ||
      battleArenaOpponentForm != presentedBattleForm(opponent, false))
    drawBattleArena(pokemon, opponent);

  // A retained stripe is a fresh off-screen composition, even when the
  // physical move picker was already visible. Skipping to the cursor-only
  // path here left every later stripe of the logical panel black.
  if (moveHighlightedSlot >= kMoveSlots) moveHighlightedSlot = 0;

  // This is the original FireRed move picker layout: four moves on the left,
  // PP and TYPE on the right.  It deliberately overlays the arena rather
  // than replacing it with a separate, generic selection screen.
  drawFireRedBattleWindow(0, 160, 223, 80, kBattleCommandFrame, kBattlePaper);
  display.drawFastVLine(112, 165, 70, kBattleFrameGold);
  display.drawFastHLine(5, 199, 213, kBattleFrameGold);
  drawFireRedBattleWindow(222, 160, 98, 80, kBattleCommandFrame, kBattlePaper);
  const uint8_t highlightedSlot = moveHighlightedSlot;
  const int16_t selectedY = static_cast<int16_t>(175 + (highlightedSlot / 2U) * 36U);
  const int16_t selectedX = static_cast<int16_t>(11 + (highlightedSlot % 2U) * 98U);
  display.fillTriangle(selectedX, selectedY + 8, selectedX + 8, selectedY + 3,
                       selectedX + 8, selectedY + 13, TFT_DARKGREY);
  for (uint8_t slot = 0; slot < kMoveSlots; ++slot) {
    const int16_t x = 58 + (slot % 2) * 107;
    const int16_t y = 164 + (slot / 2) * 36;
    const FullMoveData* move = pokemon ? findFullMove(pokemon->moves[slot]) : nullptr;
    const bool usable = move && pokemon && pokemon->movePp[slot] &&
                        isMoveAvailableInSingleBattle(pokemon->moves[slot]) &&
                        BattleEngine::moveIsSelectable(gameSave.battle,gameSave.collection,
                                                       pokemon->moves[slot],BattleSide::Player);
    fireRedText.setTextColor(usable ? kBattleInk : TFT_LIGHTGREY, kBattlePaper);
    drawBattleMoveName(move ? move->name : "---", x, y);
  }
  const FullMoveData* selectedMove = pokemon ? findFullMove(pokemon->moves[highlightedSlot]) : nullptr;
  fireRedText.setTextColor(kBattleInk, kBattlePaper);
  const uint8_t selectedMaximumPp = pokemon
      ? (gameSave.battle.playerTransformed ? (selectedMove ? 5U : 0U)
                                           : CollectionLogic::maximumMovePp(*pokemon, highlightedSlot))
      : 0U;
  char pp[20]; std::snprintf(pp, sizeof(pp), "%u/%u", pokemon ? pokemon->movePp[highlightedSlot] : 0U,
                             selectedMaximumPp);
  // PP and TYPE are permanent information and must never disappear behind
  // confirmation controls.
  fireRedText.drawString("PP", 236, 170, 1); fireRedText.setTextDatum(TR_DATUM);
  fireRedText.drawStringFitted(pp, 306, 170, 67, 1); fireRedText.setTextDatum(TL_DATUM);
  fireRedText.drawString("TYPE", 236, 190, 1);
  if (selectedMove) drawPokemonTypeBadge(selectedMove->type, 234, 201, 73, 17);
  else fireRedText.drawString("---", 236, 203, 1);
  fireRedText.setTextColor(kBattleInk, kBattlePaper); fireRedText.drawString("BACK", 260, 221, 1);
  // Opening the confirmation paints opaque pixels, but closing it paints
  // nothing at this layer. Explicitly invalidate the old modal footprint so
  // the retained compositor restores the arena underneath it immediately.
  if (topLevelDraw && renderedMoveConfirmSlot != moveConfirmSlot)
    invalidatePixels(112, 54, 96, 60);
  if (moveConfirmSlot >= 0) {
    // Dedicated modal in the unused centre of the arena. It does not cover
    // HP cards, move labels or the PP/TYPE card.
    drawFireRedBattleWindow(112, 54, 96, 60, kBattleCommandFrame, kBattlePaper);
    display.drawFastHLine(117, 84, 86, kBattleFrameGold);
    fireRedText.setTextColor(kBattleInk, kBattlePaper);
    fireRedText.drawString("OK", 145, 64, 1);
    fireRedText.drawString("CANCEL", 132, 91, 1);
  }
  if (!hasUsableMove) {
    fireRedText.setTextColor(TFT_RED, kBattlePaper);
    fireRedText.drawString("STRUGGLE", 27, 170, 1);
  }
  moveSelectVisible = true;
  renderedMoveConfirmSlot = moveConfirmSlot;
}

void queueMoveLearning(const BattleActionResult& result) {
  gameSave.moveLearning.origin = 0;
  for(uint8_t i=0;i<result.movesToLearnCount&&gameSave.moveLearning.count<kPartyCapacity;++i){
    PendingMoveLearning& pending=gameSave.moveLearning.entries[gameSave.moveLearning.count++];
    pending.pokemonUid=result.moveLearnerUids[i];pending.move=result.movesToLearn[i];
  }
}

void queueEvolutionChoices(const BattleActionResult& result) {
  for(uint8_t i=0;i<result.pendingEvolutionCount&&gameSave.evolutionQueue.count<kPartyCapacity;++i){
    PendingEvolution& pending=gameSave.evolutionQueue.entries[gameSave.evolutionQueue.count++];
    pending.pokemonUid=result.pendingEvolutionUids[i];
    pending.choiceCount=result.pendingEvolutionChoiceCounts[i];
    for(uint8_t choice=0;choice<pending.choiceCount&&choice<kEvolutionChoiceCapacity;++choice)
      pending.choices[choice]=result.pendingEvolutionChoices[i][choice];
  }
}

void drawEvolutionChoose() {
  if(gameSave.evolutionQueue.index>=gameSave.evolutionQueue.count){
    const bool returnToInventory=gameSave.moveLearning.origin==kMoveLearningOriginInventory;
    gameSave.evolutionQueue=EvolutionQueue{};saveDirty=true;saveNow();
    if(gameSave.moveLearning.index<gameSave.moveLearning.count){screen=Screen::MoveLearn;drawMoveLearn();}
    else if(returnToInventory){gameSave.moveLearning=MoveLearningQueue{};screen=Screen::Inventory;drawInventory();}
    else if(seriesIntroPending()){screen=Screen::TrainerIntro;drawTrainerIntro();}
    else{screen=Screen::Battle;drawBattle();}
    return;
  }
  const PendingEvolution& pending=gameSave.evolutionQueue.entries[gameSave.evolutionQueue.index];
  // Linear evolutions do not need an artificial destination picker. They
  // enter the cinematic immediately, where the player may still cancel with
  // the top-left X exactly as B cancels an evolution in FireRed.
  if(pending.choiceCount==1U){resolvePendingEvolution(0);return;}
  const OwnedPokemon* pokemon=CollectionLogic::find(gameSave.collection,pending.pokemonUid);
  const SpeciesData* current=pokemon?findSpecies(pokemon->speciesId):nullptr;
  beginScreenPresentation(Screen::EvolutionChoose,TFT_WHITE); display.fillRoundRect(4,4,312,232,8,TFT_DARKGREY); display.fillRoundRect(8,8,304,224,6,themePrimary());
  fireRedText.setTextColor(TFT_WHITE,themePrimary()); fireRedText.drawString("EVOLUTION CHOICE",12,14,2);
  char prompt[48]; std::snprintf(prompt,sizeof(prompt),"%s CAN EVOLVE INTO...",current?current->name:"POKEMON");
  fireRedText.setTextColor(TFT_YELLOW,themePrimary()); fireRedText.drawStringAuto(prompt,12,36,296);
  for(uint8_t i=0;i<pending.choiceCount&&i<kEvolutionChoiceCapacity;++i){
    const int16_t x=i<3?12+i*102:61+(i-3)*143;
    const int16_t y=i<3?54:145;
    const int16_t width=i<3?92:133;
    const SpeciesData* target=findSpecies(pending.choices[i]);
    display.fillRoundRect(x,y,width,82,6,TFT_LIGHTGREY); display.drawRoundRect(x,y,width,82,6,TFT_WHITE);
    // Evolution branches use the same compact 32x32 sprites as the Box.  The
    // former 64x64 battle portraits left almost no room for five Eeveelutions
    // and could visually escape their cards.  Keep the eventual evolution
    // animation full-sized; only this choice grid is deliberately compact.
    char path[80];
    std::snprintf(path,sizeof(path),"/pokegochi/assets/pokemon/%sicons/%03u_0.pkg",
                  pokemon&&pokemon->shiny?"shiny/":"",pending.choices[i]);
    const int16_t iconX=x+(width-32)/2;
    const int16_t iconY=y+11;
    if(!sdReady||!AssetRenderer::draw(display,path,iconX,iconY)){
      display.fillCircle(x+width/2,y+27,13,speciesColor(pending.choices[i]));
      display.drawCircle(x+width/2,y+27,13,TFT_DARKGREY);
    }
    fireRedText.setTextColor(TFT_BLACK,TFT_LIGHTGREY); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawStringFitted(target?target->name:"?",x+width/2,y+63,width-8,1); fireRedText.setTextDatum(TL_DATUM);
  }
}

void resolvePendingEvolution(uint8_t choiceIndex) {
  if(gameSave.evolutionQueue.index>=gameSave.evolutionQueue.count){
    drawEvolutionChoose();return;
  }
  const PendingEvolution pending=
      gameSave.evolutionQueue.entries[gameSave.evolutionQueue.index];
  OwnedPokemon* pokemon=CollectionLogic::find(gameSave.collection,pending.pokemonUid);
  if(!pokemon||choiceIndex>=pending.choiceCount||choiceIndex>=kEvolutionChoiceCapacity){
    ++gameSave.evolutionQueue.index;drawEvolutionChoose();return;
  }

  const uint16_t oldSpecies=pokemon->speciesId;
  const uint16_t newSpecies=pending.choices[choiceIndex];
  const bool shiny=pokemon->shiny;
  const bool completed=playEvolutionAnimation(oldSpecies,newSpecies,shiny);
  if(completed){
    uint32_t bonusUid=0;
    if(CollectionLogic::evolve(gameSave.collection,pending.pokemonUid,newSpecies,&bonusUid,
                               unlockedContentGeneration())){
      PokedexLogic::markCaught(gameSave.pokedex,newSpecies);
      if(bonusUid)PokedexLogic::markCaught(gameSave.pokedex,292U);
    }
  }

  // Cancellation resolves only this attempt. Since the species was left
  // untouched, the normal level-up check queues it again at the next level.
  ++gameSave.evolutionQueue.index;
  saveDirty=true;saveNow();
  drawEvolutionChoose();
}

void resetMoveLearnDescriptionScroll() {
  moveLearnOldDescriptionScroll = 0;
  moveLearnNewDescriptionScroll = 0;
  moveLearnOldDescriptionLines = 0;
  moveLearnNewDescriptionLines = 0;
}

void finishMoveLearningFlow(bool learnedMove) {
  const bool returnToInventory =
      gameSave.moveLearning.origin == kMoveLearningOriginInventory;
  gameSave.moveLearning = MoveLearningQueue{};
  moveLearnConfirmSlot = -2;
  resetMoveLearnDescriptionScroll();
  saveDirty = true;
  saveNow();
  if (!returnToInventory) {
    if (seriesIntroPending()) { screen = Screen::TrainerIntro; drawTrainerIntro(); }
    else { screen = Screen::Battle; drawBattle(); }
    return;
  }
  inventoryMode = InventoryMode::Browse;
  inventoryBattleContext = false;
  std::snprintf(inventoryNotice, sizeof(inventoryNotice),
                learnedMove ? "THE MOVE WAS LEARNED." : "THE MOVE WAS NOT LEARNED.");
  inventoryDescriptionScroll = 0;
  screen = Screen::Inventory;
  drawInventory();
}

void drawMoveLearnComparisonCard(const char* heading, const FullMoveData* move,
                                 int16_t y, uint8_t& scroll, uint8_t& lineCount) {
  constexpr int16_t x = 23;
  constexpr int16_t width = 274;
  constexpr uint8_t visibleDescriptionLines = 1;
  constexpr uint16_t cardBorder = 0x6B6D;
  constexpr uint16_t cardPaper = 0xFFDF;
  display.fillRoundRect(x, y, width, 60, 4, cardBorder);
  display.fillRect(x + 3, y + 3, width - 6, 54, cardPaper);
  fireRedText.setTextColor(TFT_DARKGREY, cardPaper);
  fireRedText.drawStringFitted(heading, x + 7, y + 7, 34, 1);
  fireRedText.drawStringAuto(move ? move->name : "EMPTY SLOT", x + 45, y + 6, 104);
  if (!move) {
    lineCount = 0;
    scroll = 0;
    return;
  }

  drawPokemonTypeBadge(move->type, x + 154, y + 4, 50, 17);
  char data[48];
  std::snprintf(data, sizeof(data), "POW %u  ACC %u  PP %u",
                move->power, move->accuracy, move->pp);
  fireRedText.setTextColor(TFT_DARKGREY, cardPaper);
  fireRedText.drawStringAuto(data, x + 7, y + 25, width - 22);

  // Reserve the final 14 px for the scroll affordance. drawTextBox wraps the
  // complete purpose-written move description and renders exactly one row in
  // this compact comparison card. Tapping anywhere on the card advances it.
  const uint8_t measured = fireRedText.drawTextBox(
      moveEffectDescription(move), x + 7, y + 41, width - 29, 16, scroll);
  lineCount = measured;
  const uint8_t maximum = measured > visibleDescriptionLines
      ? static_cast<uint8_t>(measured - visibleDescriptionLines) : 0U;
  scroll = std::min<uint8_t>(scroll, maximum);
  if (scroll < maximum) {
    display.fillTriangle(x + width - 15, y + 48, x + width - 5, y + 48,
                         x + width - 10, y + 54, TFT_DARKGREY);
  } else if (maximum) {
    // At the final line the upward marker explains that another tap cycles
    // back to the beginning instead of leaving the prose apparently stuck.
    display.fillTriangle(x + width - 15, y + 54, x + width - 5, y + 54,
                         x + width - 10, y + 48, TFT_DARKGREY);
  }
}

void advanceMoveLearnDescription(uint8_t& scroll, uint8_t lineCount) {
  constexpr uint8_t visibleLines = 1;
  const uint8_t maximum = lineCount > visibleLines
      ? static_cast<uint8_t>(lineCount - visibleLines) : 0U;
  scroll = maximum && scroll < maximum ? static_cast<uint8_t>(scroll + 1U) : 0U;
}

void drawMoveLearn() {
  if(gameSave.moveLearning.index>=gameSave.moveLearning.count){finishMoveLearningFlow(false);return;}
  const PendingMoveLearning& pending=gameSave.moveLearning.entries[gameSave.moveLearning.index];
  OwnedPokemon* pokemon=CollectionLogic::find(gameSave.collection,pending.pokemonUid);
  const SpeciesData* species=pokemon?findSpecies(pokemon->speciesId):nullptr;const FullMoveData* learned=findFullMove(pending.move);
  beginScreenPresentation(Screen::MoveLearn,TFT_WHITE);display.fillRoundRect(4,4,312,232,7,TFT_DARKGREY);display.fillRoundRect(8,8,304,224,5,themePrimary());
  fireRedText.setTextColor(TFT_WHITE,themePrimary());char title[64];std::snprintf(title,sizeof(title),"%s WANTS TO LEARN",species?species->name:"POKEMON");fireRedText.drawStringFitted(title,15,16,290,2);
  fireRedText.setTextColor(TFT_YELLOW,themePrimary());fireRedText.drawStringFitted(learned?learned->name:"A NEW MOVE",15,38,290,2);
  fireRedText.setTextColor(TFT_WHITE,themePrimary());fireRedText.drawStringAuto("CHOOSE A MOVE TO FORGET",15,58,290);
  for(uint8_t slot=0;slot<kMoveSlots;++slot){const FullMoveData* move=pokemon?findFullMove(pokemon->moves[slot]):nullptr;char label[40];
    std::snprintf(label,sizeof(label),"%s  PP %u",move?move->name:"---",pokemon?pokemon->movePp[slot]:0);button(17,80+slot*29,286,24,label,themeAccent());}
  button(75,202,170,27,"DO NOT LEARN",TFT_RED);
  if (moveLearnConfirmSlot >= -1) {
    const FullMoveData* oldMove = moveLearnConfirmSlot >= 0 && pokemon
        ? findFullMove(pokemon->moves[static_cast<uint8_t>(moveLearnConfirmSlot)]) : nullptr;
    display.fillRoundRect(13, 19, 294, 202, 7, TFT_DARKGREY);
    display.fillRoundRect(17, 23, 286, 194, 5, TFT_WHITE);
    fireRedText.setTextColor(TFT_DARKGREY, TFT_WHITE);
    fireRedText.drawStringFitted(moveLearnConfirmSlot < 0 ? "STOP LEARNING THIS MOVE?" : "REPLACE THIS MOVE?", 27, 30, 266, 2);
    if (moveLearnConfirmSlot >= 0) {
      drawMoveLearnComparisonCard("OLD", oldMove, 55, moveLearnOldDescriptionScroll,
                                  moveLearnOldDescriptionLines);
      drawMoveLearnComparisonCard("NEW", learned, 119, moveLearnNewDescriptionScroll,
                                  moveLearnNewDescriptionLines);
    } else {
      drawMoveLearnComparisonCard("NEW", learned, 73, moveLearnNewDescriptionScroll,
                                  moveLearnNewDescriptionLines);
      fireRedText.setTextColor(TFT_DARKGREY,TFT_WHITE);
      fireRedText.drawStringAuto("THE MOVE WILL NOT BE LEARNED.",35,145,250);
    }
    button(35, 185, 110, 27, "CONFIRM", TFT_DARKGREEN);
    button(175, 185, 110, 27, "CANCEL", TFT_RED);
  }
}

bool prepareBattlePartySceneAssets() {
  static char iconPaths[kPartyCapacity][112]{};
  static const char* assets[kPartyCapacity]{};
  std::memset(iconPaths, 0, sizeof(iconPaths));
  std::memset(assets, 0, sizeof(assets));
  uint8_t count = 0;
  uint32_t sceneKey = 0x50415254UL;
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    if (!pokemon || count >= kPartyCapacity) continue;
    // Battle-party screens are static surfaces. Always use frame zero so the
    // manifest and every retained repaint point at the same resident asset.
    // Keep the slot index separate from the counter increment. The former
    // one-liner read and modified `count` without sequencing those operations;
    // on ARM64 that could publish a corrupted manifest pointer and crash in
    // prepareUiScene() while resuming a fainted battle.
    const uint8_t assetIndex = count;
    pokemonAssetPath(iconPaths[assetIndex], sizeof(iconPaths[assetIndex]),
                     *pokemon, PokemonAssetView::Icon, 0U);
    assets[assetIndex] = iconPaths[assetIndex];
    ++count;
    sceneKey = (sceneKey * 16777619UL) ^ pokemon->uid;
    sceneKey = (sceneKey * 16777619UL) ^ pokemon->speciesId;
    sceneKey = (sceneKey * 16777619UL) ^ CollectionLogic::resolvedForm(*pokemon);
  }
  return prepareUiScene(sceneKey, assets, count);
}

bool prepareSummarySceneAssets(const OwnedPokemon& pokemon, uint8_t page) {
  static char background[96]{};
  static char frontPath[112]{};
  static const char* assets[2]{};
  // EDIT MOVESET and EV TRAINING paint an opaque procedural body plus their
  // own header. Loading the Moves tilemap for those pages only to cover every
  // pixel immediately caused an avoidable SD transaction on each visit.
  if (page >= 3U) return true;
  const char* name = page == 0U ? "info" : page == 1U ? "skills" : "moves";
  std::snprintf(background, sizeof(background),
                "/pokegochi/assets/firered/summary_screen/%s_page.pkg", name);
  const uint8_t resolvedForm = CollectionLogic::resolvedForm(pokemon);
  const bool sameResidentPokemon =
      summaryResidentFrontPath[0] &&
      summaryResidentFrontUid == pokemon.uid &&
      summaryResidentFrontSpecies == pokemon.speciesId &&
      summaryResidentFrontForm == resolvedForm &&
      summaryResidentFrontShiny == pokemon.shiny;
  if (sameResidentPokemon)
    std::strncpy(frontPath, summaryResidentFrontPath, sizeof(frontPath) - 1U);
  else
    pokemonAssetPath(frontPath, sizeof(frontPath), pokemon, PokemonAssetView::Front);
  char requestedFrontPath[112]{};
  std::strncpy(requestedFrontPath, frontPath,
               sizeof(requestedFrontPath) - 1U);
  assets[0] = background;
  // Only Info draws the front card. Skills and Moves used to evict/reload it
  // despite never painting it, increasing both SD latency and cache pressure.
  const bool needsFront = page == 0U;
  assets[1] = needsFront ? frontPath : nullptr;
  uint32_t sceneKey = 0x53554D00UL ^ page;
  if (needsFront) {
    sceneKey ^= pokemon.uid;
    sceneKey = (sceneKey * 16777619UL) ^ pokemon.speciesId;
    sceneKey = (sceneKey * 16777619UL) ^ resolvedForm;
    sceneKey = (sceneKey * 16777619UL) ^ (pokemon.shiny ? 0x5348494EUL : 0U);
  }
  const uint8_t assetCount = needsFront ? 2U : 1U;
  bool ready = prepareUiScene(sceneKey, assets, assetCount);
  if (needsFront && !ready && !AssetRenderer::isPreloaded(frontPath)) {
    // Dedicated form cards were added after the original pack. Retry with
    // the canonical species front card before exposing the old silhouette;
    // the background remains the same FireRed Summary scene. Reusing the
    // logical key keeps retained repaint stripes from rebuilding this pack.
    const char* fallbackPrefix = pokemon.shiny ? "shiny/" : "";
    std::snprintf(frontPath, sizeof(frontPath),
                  "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  fallbackPrefix, static_cast<unsigned>(pokemon.speciesId));
    if (std::strcmp(frontPath, requestedFrontPath) != 0) {
      preparedUiSceneKey = 0;
      preparedUiSceneComplete = false;
      ready = prepareUiScene(sceneKey, assets, assetCount);
    }
    if (!ready && pokemon.shiny) {
      std::snprintf(frontPath, sizeof(frontPath),
                    "/pokegochi/assets/pokemon/front/%03u.pkg",
                    static_cast<unsigned>(pokemon.speciesId));
      preparedUiSceneKey = 0;
      preparedUiSceneComplete = false;
      ready = prepareUiScene(sceneKey, assets, assetCount);
    }
  }
  if (needsFront && (ready || AssetRenderer::isPreloaded(frontPath))) {
    std::strncpy(summaryResidentFrontPath, frontPath,
                 sizeof(summaryResidentFrontPath) - 1U);
    summaryResidentFrontPath[sizeof(summaryResidentFrontPath) - 1U] = 0;
    summaryResidentFrontUid = pokemon.uid;
    summaryResidentFrontSpecies = pokemon.speciesId;
    summaryResidentFrontForm = resolvedForm;
    summaryResidentFrontShiny = pokemon.shiny;
  }
  return ready;
}

void drawBattleParty() {
  beginScreenPresentation(Screen::BattleParty,TFT_LIGHTGREY);
  prepareBattlePartySceneAssets();
  display.fillRect(0, 0, 320, 27, TFT_DARKCYAN);
  fireRedText.setTextColor(TFT_WHITE, TFT_DARKCYAN); fireRedText.drawString("CHOOSE A POKEMON", 9, 7, 2);
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    const int16_t y = 34 + slot * 54;
    const bool inBattle = pokemon && pokemon->uid == gameSave.battle.playerUid;
    const bool selected = battlePartySelection == static_cast<int8_t>(slot);
    const uint16_t background = selected ? TFT_YELLOW : inBattle ? themePale() : TFT_WHITE;
    display.fillRoundRect(7, y, 306, 48, 7, TFT_DARKGREY);
    display.fillRoundRect(10, y + 3, 300, 42, 5, background);
    if (!pokemon) { fireRedText.setTextColor(TFT_DARKGREY, background); fireRedText.drawString("EMPTY", 65, y + 17, 2); continue; }
    char path[112]; pokemonAssetPath(path, sizeof(path), *pokemon, PokemonAssetView::Icon, 0U);
    if (!AssetRenderer::draw(display, path, 17, y + 7))
      creature(33, y + 23, *pokemon, false);
    const SpeciesData* species = findSpecies(pokemon->speciesId);
    fireRedText.setTextColor(TFT_DARKGREY, background); fireRedText.drawStringFitted(species ? species->name : "UNKNOWN", 57, y + 8, 139, 2);
    drawPokemonGenderSymbol(*pokemon, 207, y + 16);
    char level[12]; std::snprintf(level, sizeof(level), "Lv%u", pokemon->level);
    fireRedText.setTextDatum(TR_DATUM);
    fireRedText.drawStringFitted(level, 297, y + 8, 72, 1);
    fireRedText.setTextDatum(TL_DATUM);
    display.drawRect(57, y + 28, 150, 8, TFT_DARKGREY);
    const uint16_t hpWidth = meterFillPixels(146U, pokemon->currentHp, pokemon->maximumHp);
    display.fillRect(59, y + 30, hpWidth, 4, pokemon->currentHp * 4U > pokemon->maximumHp ? TFT_GREEN : pokemon->currentHp * 8U > pokemon->maximumHp ? TFT_ORANGE : TFT_RED);
    char hp[22]; std::snprintf(hp, sizeof(hp), "%u/%u", pokemon->currentHp, pokemon->maximumHp);
    fireRedText.setTextDatum(TR_DATUM);
    fireRedText.drawStringFitted(hp, 297, y + 27, 80, 1);
    fireRedText.setTextDatum(TL_DATUM);
    if (inBattle) fireRedText.drawString("IN BATTLE", 243, y + 37, 1);
    else if (pokemon->currentHp == 0 || pokemon->recoverySecondsRemaining) fireRedText.drawStringAuto("UNABLE", 228, y + 37, 69);
    else if (pokemon->status != StatusCondition::None) fireRedText.drawStringAuto(PetLogic::statusName(pokemon->status), 228, y + 37, 69);
  }
  if (battlePartySelection >= 0) {
    button(12, 202, 88, 31, "SHIFT", TFT_DARKGREEN);
    button(116, 202, 88, 31, "SUMMARY", themePrimary());
    if (!forcedBattleSwitch) button(220, 202, 88, 31, "CANCEL", TFT_RED);
  } else if (!forcedBattleSwitch) button(110, 202, 100, 31, "CANCEL", TFT_RED);
}

