void drawFireRedSummaryHeader(uint8_t page, uint8_t pageCount) {
  static constexpr const char* titles[] = {
      "POKEMON INFO", "POKEMON SKILLS", "POKEMON MOVES", "EDIT MOVESET", "EV TRAINING"};
  pageCount = std::max<uint8_t>(1U, std::min<uint8_t>(pageCount, 5U));
  // Use one opaque pearl title tab on all five pages. The authentic FireRed
  // tilemap remains visible beneath it, while Pokegochi's extra pages no
  // longer look pasted over the original three-page header.
  display.fillRoundRect(3, 2, 134, 22, 5, 0x6B6D);
  display.fillRoundRect(5, 3, 130, 19, 4, 0xFFDF);
  fireRedText.setTextColor(TFT_DARKGREY, 0xFFDF);
  fireRedText.drawStringAuto(titles[page % pageCount], 10, 5, 122);
  // The source tilemap contains static page dots.  Replace that region with
  // a real indicator so the selected dot visibly follows the active page.
  const uint16_t headerBlue = themePrimary();
  display.fillRect(139, 0, 96, 24, headerBlue);
  display.drawFastHLine(139, 23, 181, themeAccent());
  const int16_t firstDot = pageCount > 4U ? 144 : 151;
  for (uint8_t index = 0; index < pageCount; ++index) {
    const int16_t x = static_cast<int16_t>(firstDot + index * 18);
    const uint16_t fill = index == page ? TFT_WHITE : themeDark();
    display.fillCircle(x, 11, 6, 0x4228);
    display.fillCircle(x, 11, 4, fill);
    if (index == page) display.drawFastHLine(x - 2, 8, 5, themePale());
  }
  // The arrows make the three original pages discoverable on a touch-only
  // device. Tapping a dot also selects its matching page directly.
  display.fillTriangle(265, 14, 277, 6, 277, 22, 0x4228);
  display.fillTriangle(268, 14, 276, 9, 276, 19, TFT_WHITE);
  display.fillTriangle(314, 14, 302, 6, 302, 22, 0x4228);
  display.fillTriangle(311, 14, 303, 9, 303, 19, TFT_WHITE);
}

bool drawFireRedSummaryBackground(uint8_t page, uint8_t pageCount) {
  if (page >= 3U) {
    // Both Pokegochi-only pages are fully opaque below the shared header.
    // Keep this branch RAM-only; their painters replace the body immediately.
    display.fillRect(0, 0, 320, 213, 0xFFDF);
    drawFireRedSummaryHeader(page, pageCount);
    renderedSummaryPage = page;
    return true;
  }
  const char* name = page == 0 ? "info" : page == 1 ? "skills" : "moves";
  char path[88];
  std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/summary_screen/%s_page.pkg", name);
  // Entering the Summary page was already cleared by
  // beginScreenPresentation(). Changing one of the three Summary pages is
  // not a new screen: the opaque tilemap overwrites only the 320x213 body,
  // preventing the black flash that used to occur under every dot/arrow tap.
  // The Summary is a complete opaque scene. Clear its body before attempting
  // the cached page so a failed/partial card read can never expose the old
  // battle or Box colours underneath the FireRed layers.
  display.fillRect(0, 0, 320, 213, page == 1 ? 0xFDF0 : 0xD69A);
  const bool drawn = sdReady && AssetRenderer::draw(display, path, 0, 0);
  if (!drawn) {
    // The layout remains usable while a card is being remounted; normal
    // operation always renders the genuine FireRed tilemap above.
    display.fillRect(0, 0, 320, 213, page == 1 ? 0xFDF0 : 0xD69A);
    display.drawRect(1, 24, 158, 109, TFT_DARKGREY);
    display.drawRect(161, 24, 158, 185, TFT_DARKGREY);
  }
  drawFireRedSummaryHeader(page, pageCount);
  renderedSummaryPage = page;
  return drawn;
}

void rebuildSummaryMovePool(const OwnedPokemon& pokemon) {
  const uint8_t unlockedGeneration = unlockedContentGeneration();
  const uint8_t resolvedForm = CollectionLogic::resolvedForm(pokemon);
  uint32_t cacheKey = 2166136261UL;
  cacheKey = (cacheKey ^ pokemon.uid) * 16777619UL;
  cacheKey = (cacheKey ^ pokemon.speciesId) * 16777619UL;
  cacheKey = (cacheKey ^ resolvedForm) * 16777619UL;
  cacheKey = (cacheKey ^ static_cast<uint8_t>(
      MegaEvolution::variantFor(pokemon))) * 16777619UL;
  cacheKey = (cacheKey ^ pokemon.level) * 16777619UL;
  cacheKey = (cacheKey ^ unlockedGeneration) * 16777619UL;
  if (summaryMovePoolCacheValid && summaryMovePoolCacheKey == cacheKey) return;
  const uint32_t started = millis();
  summaryMovePoolCount = relearnableMovesForPokemon(
      pokemon,summaryMovePool,kSummaryMovePoolCapacity,unlockedGeneration);
  summaryMovePoolCacheKey = cacheKey;
  summaryMovePoolCacheValid = true;
  if (!summaryMovePoolCount) {
    summaryMovePoolOffset = 0;
    summaryMovePoolSelection = -1;
    return;
  }
  if (summaryMovePoolOffset >= summaryMovePoolCount)
    summaryMovePoolOffset = static_cast<uint8_t>(
        ((summaryMovePoolCount - 1U) / kSummaryMovePoolRows) * kSummaryMovePoolRows);
  if (summaryMovePoolSelection >= static_cast<int8_t>(summaryMovePoolCount))
    summaryMovePoolSelection = -1;
  const uint32_t elapsed = millis() - started;
  if (elapsed >= 4U)
    Serial.printf("[PERF] Summary move pool uid=%lu moves=%u %lums\n",
                  static_cast<unsigned long>(pokemon.uid),
                  static_cast<unsigned>(summaryMovePoolCount),
                  static_cast<unsigned long>(elapsed));
}

uint8_t drawSummaryScrollableText(const char* text, int16_t x, int16_t y,
                                  int16_t width, int16_t height, uint16_t color) {
  fireRedText.setTextColor(color);
  const int16_t textWidth = std::max<int16_t>(8, width - 7);
  const uint8_t count = fireRedText.drawTextBox(
      text ? text : "", x, y, textWidth, height, summaryTextScroll);
  summaryTextLineCount = count;
  summaryTextVisibleLines = static_cast<uint8_t>(std::max<int16_t>(1, height / 16));
  const uint8_t maximum = count > summaryTextVisibleLines
      ? static_cast<uint8_t>(count - summaryTextVisibleLines) : 0U;
  summaryTextScroll = std::min<uint8_t>(summaryTextScroll, maximum);
  if (count > summaryTextVisibleLines) {
    const int16_t railX = x + width - 4;
    const int16_t railTop = y + 3;
    const int16_t railHeight = std::max<int16_t>(8, height - 8);
    display.fillRoundRect(railX, railTop, 3, railHeight, 1, 0xC618);
    const int16_t thumbHeight = std::max<int16_t>(5,
        railHeight * summaryTextVisibleLines / count);
    const int16_t travel = std::max<int16_t>(0, railHeight - thumbHeight);
    const int16_t thumbY = railTop +
        (maximum ? travel * summaryTextScroll / maximum : 0);
    display.fillRoundRect(railX, thumbY, 3, thumbHeight, 1, themePrimary());
  }
  if (count > static_cast<uint8_t>(summaryTextScroll + summaryTextVisibleLines)) {
    display.fillTriangle(x + width - 12, y + height - 3, x + width - 3, y + height - 3,
                         x + width - 7, y + height - 9, TFT_DARKGREY);
  }
  return count;
}

