const char* moveCategoryName(MoveCategory category) {
  switch (category) {
    case MoveCategory::Physical: return "PHYSICAL";
    case MoveCategory::Special: return "SPECIAL";
    case MoveCategory::Status: return "STATUS";
  }
  return "STATUS";
}

const char* moveEffectDescription(const FullMoveData* move) {
  static char text[320];
  if (!move) return "NO MOVE SELECTED.";
  // Every one of FireRed's 354 moves has its original purpose-written text.
  // This preserves the exact affected stat and special rule (for example,
  // AGILITY sharply raises SPEED) instead of inferring a vague sentence from
  // a shared battle-effect family.
  const char* base = moveDescription(static_cast<MoveId>(move->id));
  // Category is authored per move from Platinum/White. Type inference would
  // mislabel punches, fangs, Ancient Power and every other post-split
  // exception even though the battle engine correctly follows this field.
  const char* category = moveCategoryName(move->category);
  char chance[28]=""; if(move->effectChance)std::snprintf(chance,sizeof(chance)," EFFECT CHANCE: %u%%.",move->effectChance);
  char priority[28]=""; if(move->priority)std::snprintf(priority,sizeof(priority)," PRIORITY: %+d.",move->priority);
  std::snprintf(text,sizeof(text),"%s CATEGORY: %s.%s%s%s",base,category,
                move->makesContact?" MAKES CONTACT.":"",chance,priority);
  return text;
}

const char* summaryNatureText(const OwnedPokemon& pokemon) {
  static char text[176];
  static constexpr PokemonStat stats[]={PokemonStat::Attack,PokemonStat::Defense,
      PokemonStat::Speed,PokemonStat::SpAttack,PokemonStat::SpDefense};
  static constexpr const char* names[]={"ATTACK","DEFENSE","SPEED","SP. ATK","SP. DEF"};
  const char* raised=nullptr;const char* lowered=nullptr;
  for(uint8_t i=0;i<5;++i){
    const int8_t effect=CollectionLogic::natureEffect(pokemon.nature,stats[i]);
    if(effect>0)raised=names[i];else if(effect<0)lowered=names[i];
  }
  if(raised&&lowered)
    std::snprintf(text,sizeof(text),"%s NATURE.  %s +10%%.  %s -10%%.",
        CollectionLogic::natureName(pokemon.nature),raised,lowered);
  else
    std::snprintf(text,sizeof(text),"%s NATURE.  NO STAT BONUS OR PENALTY.",
        CollectionLogic::natureName(pokemon.nature));
  return text;
}

uint8_t& summaryEvAt(EffortValues& values, uint8_t index) {
  switch (index) {
    case 0: return values.hp;
    case 1: return values.attack;
    case 2: return values.defense;
    case 3: return values.spAttack;
    case 4: return values.spDefense;
    default: return values.speed;
  }
}

uint8_t summaryEvAt(const EffortValues& values, uint8_t index) {
  switch (index) {
    case 0: return values.hp;
    case 1: return values.attack;
    case 2: return values.defense;
    case 3: return values.spAttack;
    case 4: return values.spDefense;
    default: return values.speed;
  }
}

uint8_t summaryIvAt(const IndividualValues& values, uint8_t index) {
  switch (index) {
    case 0: return values.hp;
    case 1: return values.attack;
    case 2: return values.defense;
    case 3: return values.spAttack;
    case 4: return values.spDefense;
    default: return values.speed;
  }
}

uint8_t summaryBaseAt(const OwnedPokemon& pokemon, uint8_t index) {
  static constexpr PokemonStat stats[] = {PokemonStat::Attack, PokemonStat::Defense,
      PokemonStat::SpAttack, PokemonStat::SpDefense, PokemonStat::Speed};
  return index == 0U ? CollectionLogic::resolvedBaseHp(pokemon)
                     : CollectionLogic::resolvedBaseStat(pokemon, stats[index - 1U]);
}

void initializeSummaryEvDraft(const OwnedPokemon& pokemon, bool force = false) {
  if (!force && summaryEvDraftUid == pokemon.uid) return;
  summaryEvDraft = pokemon.evs;
  summaryEvDraftUid = pokemon.uid;
  summaryEvEarned = CollectionLogic::totalEffortValues(pokemon);
  summaryEvMaximum = CollectionLogic::maximumTotalEffortValues(pokemon);
  summaryEvFree = 0;
  summaryEvSelected = 0;
  summaryEvStep = 10;
  summaryEvApplyConfirm = false;
}

bool summaryEvDraftChanged(const OwnedPokemon& pokemon){
  for(uint8_t row=0;row<6U;++row)
    if(summaryEvAt(pokemon.evs,row)!=summaryEvAt(summaryEvDraft,row))return true;
  return false;
}

uint8_t summaryEvChangedStatCount(const OwnedPokemon& pokemon){
  uint8_t changed=0;
  for(uint8_t row=0;row<6U;++row)
    if(summaryEvAt(pokemon.evs,row)!=summaryEvAt(summaryEvDraft,row))++changed;
  return changed;
}

