void drawBoxContextMenu(const OwnedPokemon* selected) {
  const uint16_t chrome = 0x6B4D;
  const uint16_t paper = 0xFFDF;
  BoxContextEntry contextEntries[7]{};
  const uint8_t contextEntryCount = buildBoxContextEntries(selected, contextEntries);
  const bool actionGrid = boxOverlay == BoxOverlay::Actions &&
      !multiplayerTradeSelectionActive();
  const uint8_t actionRows = static_cast<uint8_t>(
      (contextEntryCount + kBoxActionColumns - 1U) / kBoxActionColumns);
  const int16_t menuX = actionGrid ? kBoxActionMenuX : kBoxMenuX;
  const int16_t menuY = actionGrid ? kBoxActionMenuY : kBoxMenuY;
  const int16_t menuW = actionGrid ? kBoxActionMenuW : kBoxMenuW;
  const uint16_t menuHeight = boxOverlay == BoxOverlay::ReleaseConfirm ? 64 :
      boxOverlay == BoxOverlay::FormSelect ?
          static_cast<uint16_t>((selected ? CollectionLogic::formCount(selected->speciesId) : 4U) *
                                kBoxMenuRowH + 8U) :
      actionGrid ? static_cast<uint16_t>(actionRows*kBoxActionCellH+8U) :
          static_cast<uint16_t>(2U*kBoxMenuRowH+8U);
  display.fillRoundRect(menuX + 2, menuY + 3, menuW, menuHeight, 6, 0x4228);
  drawGbaInsetPanel(menuX, menuY, menuW, menuHeight, 6, chrome, paper);

  fireRedText.setTextColor(TFT_DARKGREY, paper);
  if (multiplayerTradeSelectionActive()) {
    fireRedText.drawString("TRADE", kBoxMenuX + 24, kBoxMenuY + 8, 2);
    fireRedText.drawString("CANCEL", kBoxMenuX + 24, kBoxMenuY + 28, 2);
    display.fillTriangle(kBoxMenuX + 10, kBoxMenuY + 17, kBoxMenuX + 18,
                         kBoxMenuY + 11, kBoxMenuX + 18, kBoxMenuY + 23, TFT_DARKGREY);
    return;
  }
  if (boxOverlay == BoxOverlay::ReleaseConfirm) {
    char prompt[26];
    std::snprintf(prompt, sizeof(prompt), "RELEASE %s?", selected && findSpecies(selected->speciesId) ?
                  findSpecies(selected->speciesId)->name : "PKMN");
    fireRedText.drawStringAuto(prompt, kBoxMenuX + 10, kBoxMenuY + 7, kBoxMenuW - 18);
    fireRedText.drawString("YES", kBoxMenuX + 31, kBoxMenuY + 28, 2);
    fireRedText.drawString("NO", kBoxMenuX + 31, kBoxMenuY + 45, 2);
    display.fillTriangle(kBoxMenuX + 12, kBoxMenuY + 38, kBoxMenuX + 20,
                         kBoxMenuY + 32, kBoxMenuX + 20, kBoxMenuY + 44, TFT_DARKGREY);
    return;
  }
  if (boxOverlay == BoxOverlay::FormSelect) {
    const uint8_t count = selected ? CollectionLogic::formCount(selected->speciesId) : 4U;
    for (uint8_t row = 0; row < count; ++row)
      fireRedText.drawStringFitted(CollectionLogic::formName(
                             selected ? selected->speciesId : 386U, row),
                             kBoxMenuX + 24, kBoxMenuY + 8 + row * kBoxMenuRowH,
                             kBoxMenuW - 34, 2);
    const uint8_t current = selected ? CollectionLogic::resolvedForm(*selected) : 0U;
    display.fillTriangle(kBoxMenuX + 10, kBoxMenuY + 15 + current * kBoxMenuRowH,
                         kBoxMenuX + 18, kBoxMenuY + 9 + current * kBoxMenuRowH,
                         kBoxMenuX + 18, kBoxMenuY + 21 + current * kBoxMenuRowH,
                         TFT_DARKGREY);
    return;
  }

  // MARK is intentionally omitted: it has no purpose in a three-member
  // Pokegochi party, while the other original FireRed actions remain.  Every
  // painted cell below is also the exact cell consumed by boxContextActionAt.
  const int16_t innerX = kBoxActionMenuX + kBoxActionInset;
  const int16_t innerY = kBoxActionMenuY + kBoxActionInset;
  const uint16_t divider = 0xA514;
  // A soft selected cell makes the pointer meaningful on a touch-only UI and
  // retains the first-action focus of FireRed's command menu.
  display.fillRect(innerX + 1, innerY + 1,
                   kBoxActionCellW - 2, kBoxActionCellH - 2, themePale());
  display.drawFastVLine(innerX + kBoxActionCellW, innerY,
                        actionRows * kBoxActionCellH, divider);
  for (uint8_t row = 1; row < actionRows; ++row)
    display.drawFastHLine(innerX, innerY + row * kBoxActionCellH,
                          kBoxActionInnerW, divider);
  fireRedText.setTextDatum(MC_DATUM);
  for (uint8_t index = 0; index < contextEntryCount; ++index) {
    const uint8_t row = index / kBoxActionColumns;
    const uint8_t column = index % kBoxActionColumns;
    const int16_t centerX = innerX + column * kBoxActionCellW + kBoxActionCellW / 2;
    const int16_t centerY = innerY + row * kBoxActionCellH + kBoxActionCellH / 2;
    const int16_t labelWidth = kBoxActionCellW - (index == 0U ? 22 : 10);
    fireRedText.setTextColor(TFT_DARKGREY,
        index == 0U ? themePale() : paper);
    fireRedText.drawStringFitted(contextEntries[index].label,
                                 centerX + (index == 0U ? 6 : 0), centerY,
                                 labelWidth, 2);
  }
  fireRedText.setTextDatum(TL_DATUM);
  display.fillTriangle(innerX + 5, innerY + kBoxActionCellH / 2,
                       innerX + 13, innerY + kBoxActionCellH / 2 - 6,
                       innerX + 13, innerY + kBoxActionCellH / 2 + 6,
                       TFT_DARKGREY);
}

// Build one atomic cache pack for everything that can be visible in the PC
// scene.  Summary pages use the same renderer workspace, so this helper must
// be called by both the full screen painter and the local Box/Party painters.
// prepareUiScene() verifies every resident entry even when the logical key is
// unchanged; returning from Summary can therefore never reuse stale handles.
bool prepareBoxSceneAssets() {
  const OwnedPokemon* selected = CollectionLogic::find(gameSave.collection, selectedUid);
  const bool showingParty = boxPartyView || boxOverlay == BoxOverlay::PartyTarget ||
      boxOverlay == BoxOverlay::SoftBoiledTarget;
  // 30 paths x 72 bytes used to consume more than 2 KiB of loopTask's stack.
  // Entering FatFs below then crossed the stack canary and rebooted precisely
  // when Box was opened. This manifest is transient but non-reentrant, so keep
  // its workspace in static storage and explicitly initialise every use.
  static const char* assets[40];
  // The longest form-aware path is still below 72 bytes. Keeping this large
  // manifest compact is essential: it lives in DRAM for the whole firmware,
  // alongside the retained canvas and battle caches.
  static char iconPaths[30][72];
  static char previewPath[72];
  std::memset(assets, 0, sizeof(assets));
  std::memset(iconPaths, 0, sizeof(iconPaths));
  std::memset(previewPath, 0, sizeof(previewPath));
  assets[0] = "/pokegochi/assets/firered/pokemon_storage/scrolling_bg.pkg";
  assets[1] = "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_00.pkg";
  assets[2] = "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_01.pkg";
  assets[3] = "/pokegochi/assets/firered/pokemon_storage/cursor_00.pkg";
  uint8_t assetCount = 4;
  uint8_t iconCount = 0;
  uint8_t previewAssetIndex = 0xFF;
  uint32_t baseKey = 0x424F5800UL ^ boxPage ^ (showingParty ? 0x80000000UL : 0U);

  if (selected) {
    pokemonAssetPath(previewPath, sizeof(previewPath), *selected, PokemonAssetView::Front);
    // The selected preview is required UI and is deliberately placed before
    // the optional grid icons in the pack.
    previewAssetIndex = assetCount;
    assets[assetCount++] = previewPath;
  }
  if (showingParty) {
    assets[assetCount++] = "/pokegochi/assets/firered/pokemon_storage/party_menu.pkg";
  }

  const auto addIcon = [&](const OwnedPokemon& pokemon) {
    if (iconCount >= 30) return;
    pokemonAssetPath(iconPaths[iconCount], sizeof(iconPaths[iconCount]), pokemon,
                     PokemonAssetView::Icon, 0);
    assets[assetCount++] = iconPaths[iconCount++];
    // UID alone is not a sprite cache key: evolution keeps it stable, while
    // the icon path changes with species, form and shiny palette.
    baseKey = (baseKey * 16777619UL) ^ pokemon.uid;
    baseKey = (baseKey * 16777619UL) ^ pokemon.speciesId;
    baseKey = (baseKey * 16777619UL) ^ (pokemon.shiny ? 0x5348494EUL : 0UL);
    baseKey = (baseKey * 16777619UL) ^ CollectionLogic::resolvedForm(pokemon);
  };
  if (showingParty) {
    for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
      const OwnedPokemon* member = CollectionLogic::active(gameSave.collection, slot);
      if (member) addIcon(*member);
    }
  } else {
    const uint16_t first = static_cast<uint16_t>(boxPage) * kBoxPageSize;
    const uint16_t last = std::min<uint16_t>(kBoxCapacity, first + kBoxPageSize);
    for (uint16_t index = first; index < last; ++index)
      if (gameSave.collection.box[index].uid) addIcon(gameSave.collection.box[index]);
  }
  // Selecting a different Pokemon changes only the 64x64 preview at the
  // left.  Clearing and rebuilding the whole scene here used to reopen all
  // 30 grid icons on every selection (175 SD opens for five ordinary taps),
  // which both stalled the UI for about two seconds and needlessly stressed
  // the removable card.  Keep the verified grid resident and append just the
  // new preview.  The arena is append-only, so after enough distinct previews
  // it naturally falls back to one atomic full rebuild.
  static uint32_t residentBaseKey = 0;
  bool baseResident = residentBaseKey == baseKey;
  if (baseResident) {
    for (uint8_t item = 0; item < assetCount; ++item) {
      if (item == previewAssetIndex) continue;
      if (!AssetRenderer::isPreloaded(assets[item])) {
        baseResident = false;
        break;
      }
    }
  }
  if (baseResident && (!selected || AssetRenderer::isPreloaded(previewPath) ||
                       AssetRenderer::preload(previewPath))) {
    preparedUiSceneKey = baseKey ^ (selected ? selected->uid * 2654435761UL : 0U);
    preparedUiSceneComplete = true;
    return true;
  }

  const uint32_t fullKey = baseKey ^ (selected ? selected->uid * 2654435761UL : 0U);
  const bool ready = prepareUiScene(fullKey, assets, assetCount);
  residentBaseKey = ready ? baseKey : 0U;
  return ready;
}

void drawBoxPreviewArtwork(const OwnedPokemon* selected) {
  constexpr uint16_t kChromeDark = 0x4228;
  const uint16_t kPreviewBlue = themePale();
  constexpr int16_t kPanelX = 10;
  constexpr int16_t kPanelY = 37;
  constexpr int16_t kPanelWidth = 86;
  constexpr int16_t kPanelHeight = 100;
  constexpr int16_t kInnerX = kPanelX + 4;
  constexpr int16_t kInnerY = kPanelY + 4;
  constexpr int16_t kInnerWidth = kPanelWidth - 8;
  constexpr int16_t kInnerHeight = kPanelHeight - 8;
  constexpr int16_t kTileWidth = 32;
  constexpr int16_t kTileHeight = 16;
  constexpr const char* kBackdrop =
      "/pokegochi/assets/firered/pokemon_storage/scrolling_bg.pkg";

  drawGbaInsetPanel(kPanelX, kPanelY, kPanelWidth, kPanelHeight, 6,
                    kChromeDark, kPreviewBlue, TFT_WHITE);
  if (sdReady) {
    // FireRed's scrolling background is exactly 32x16. The previous loop
    // drew only two columns inside an 84px field, leaving the right side a
    // different colour and visually pulling every Pokemon left. Tile the
    // complete interior and clip the final row/column to the panel border.
    for (int16_t offsetY = 0; offsetY < kInnerHeight; offsetY += kTileHeight) {
      const uint16_t height = static_cast<uint16_t>(
          std::min<int16_t>(kTileHeight, kInnerHeight - offsetY));
      for (int16_t offsetX = 0; offsetX < kInnerWidth; offsetX += kTileWidth) {
        const uint16_t width = static_cast<uint16_t>(
            std::min<int16_t>(kTileWidth, kInnerWidth - offsetX));
        AssetRenderer::drawRegion(display, kBackdrop,
            kInnerX + offsetX, kInnerY + offsetY, 0, 0, width, height);
      }
    }
  }
  // Redraw a thin inner rim after tiling so a damaged transparent asset can
  // never visually eat into the card edge.
  display.drawRoundRect(kInnerX - 1, kInnerY - 1,
                        kInnerWidth + 2, kInnerHeight + 2, 3, themePale());
  // The preview interior is centred at (53,87). Front sprites are 64x64,
  // so this gives equal breathing room on every side of the visible card.
  if(selected)creature(53,87,*selected,true);
  else {
    fireRedText.setTextColor(TFT_DARKGREY, kPreviewBlue);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("NO PKMN", 53, 87, 1);
    fireRedText.setTextDatum(TL_DATUM);
  }
}

void drawBoxPreviewPanelContents(const OwnedPokemon* selected,
                                 const SpeciesData* selectedData) {
  constexpr uint16_t kChrome = 0x6B4D;
  constexpr uint16_t kChromeDark = 0x4228;
  constexpr uint16_t kPaper = 0xFFDF;
  // One continuous rounded card replaces the former pair of unrelated
  // rectangles. The sprite window and data sheet remain separate inside it,
  // matching the visual hierarchy of FireRed's PC.
  display.fillRoundRect(7, 35, 94, 171, 7, kChromeDark);
  display.fillRoundRect(6, 33, 94, 171, 7, kChrome);
  display.fillRoundRect(8, 35, 90, 167, 5, 0xD69A);
  drawBoxPreviewArtwork(selected);
  drawGbaInsetPanel(9, 138, 88, 64, 5, kChromeDark, kPaper, 0xD69A);
  display.fillRoundRect(13, 142, 80, 14, 3, themePale());
  fireRedText.setTextColor(TFT_DARKGREY, themePale());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString("SELECTED", 53, 149, 1);
  fireRedText.setTextDatum(TL_DATUM);
  if (selected) {
    char info[32];
    fireRedText.setTextColor(TFT_DARKGREY, kPaper);
    fireRedText.drawStringAuto(selectedData ? selectedData->name : "UNKNOWN",
                               13, 158, 63);
    drawPokemonGenderSymbol(*selected, 87, 166);
    std::snprintf(info, sizeof(info), "LV%u", selected->level);
    fireRedText.drawStringFitted(info, 13, 174, 77, 2);
    std::snprintf(info, sizeof(info), "HP %u/%u",
                  selected->currentHp, selected->maximumHp);
    fireRedText.drawStringAuto(info, 13, 187, 77);
  } else {
    fireRedText.setTextColor(TFT_DARKGREY, kPaper);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("EMPTY", 53, 177, 2);
    fireRedText.setTextDatum(TL_DATUM);
  }
}

// Party cards keep HP readable at a glance without spending the narrow row on
// a current/maximum number.  The same thresholds as the battle HUD make the
// meter green above half HP, orange at half or below, and red at a quarter or
// below.  Keeping this in one painter prevents the full Box draw and its
// retained partial refresh from drifting apart again.
void drawBoxPartyHpMeter(const OwnedPokemon& pokemon, int16_t rowY,
                         uint16_t panel) {
  constexpr int16_t kLabelX = kBoxGridX + 105;
  constexpr int16_t kTrackX = kBoxGridX + 125;
  constexpr uint16_t kTrackWidth = 68;
  constexpr uint16_t kFillWidth = kTrackWidth - 4U;
  constexpr uint16_t kTrackColor = 0x4208;
  fireRedText.setTextColor(TFT_ORANGE, panel);
  fireRedText.drawString("HP", kLabelX, rowY + 23, 3);
  display.fillRect(kTrackX, rowY + 23, kTrackWidth, 7, kTrackColor);
  display.fillRect(kTrackX + 2, rowY + 25, kFillWidth, 3, TFT_WHITE);
  const uint16_t filled = meterFillPixels(
      kFillWidth, pokemon.currentHp, pokemon.maximumHp);
  if (filled)
    display.fillRect(kTrackX + 2, rowY + 25, filled, 3,
                     battleHpColor(pokemon.currentHp, pokemon.maximumHp));
}

void drawBox() {
  // This is the FireRed storage layout adapted proportionally from 240x160
  // to the CYD's 320x240 landscape screen: data panel left, tabs above and
  // the storage field right.  It deliberately uses square GBA-like frames.
  constexpr uint16_t kChrome = 0x6B4D;
  constexpr uint16_t kChromeDark = 0x4228;
  constexpr uint16_t kPaper = 0xFFDF;
  const uint16_t kPreviewBlue = themePale();
  boxPage = normalizeBoxPage(boxPage);
  const BoxPalette& boxPalette = currentBoxPalette();

  if (!selectedUid) {
    const OwnedPokemon* active = currentPet();
    if (active) selectedUid = active->uid;
  }
  const OwnedPokemon* selected = CollectionLogic::find(gameSave.collection, selectedUid);
  const SpeciesData* selectedData = selected ? findSpecies(selected->speciesId) : nullptr;
  beginScreenPresentation(Screen::Box, kChromeDark);
  prepareBoxSceneAssets();

  display.fillRoundRect(1, 1, 318, 238, 9, kChromeDark);
  display.fillRoundRect(3, 3, 314, 234, 7, kPaper);
  display.drawRoundRect(4, 4, 312, 232, 6, 0xD69A);

  // The old PKMN DATA tab was merely decorative on Pokégochi.  Its useful
  // position now holds the Party toggle instead.
  drawBoxPreviewPanelContents(selected, selectedData);

  // The exact FireRed tab wording and visual hierarchy, without the former
  // generic "OUT" list that made party management hard to understand.
  const bool showingParty = boxPartyView || boxOverlay == BoxOverlay::PartyTarget ||
      boxOverlay == BoxOverlay::SoftBoiledTarget;
  char partyToggle[16];
  std::snprintf(partyToggle, sizeof(partyToggle), showingParty ? "BOX %02u" : "PARTY",
                boxPage + 1U);
  drawBoxTopButton(kBoxPartyButtonX, kBoxPartyButtonW, partyToggle, 0xB7F5);
  drawBoxTopButton(kBoxSortButtonX, kBoxSortButtonW, "SORT", 0xFFEE);
  drawBoxTopButton(kBoxCloseButtonX, kBoxCloseButtonW, "CLOSE BOX", kPreviewBlue);

  display.fillRoundRect(102, 36, 214, 30, 6, kChromeDark);
  drawGbaInsetPanel(101, 34, 214, 30, 6, kChrome,
                    boxPalette.field, boxPalette.ribbon);
  char boxLabel[24];
  std::snprintf(boxLabel, sizeof(boxLabel), showingParty ? "PARTY POKEMON" : "BOX %u", boxPage + 1U);
  fireRedText.setTextColor(TFT_DARKGREY, boxPalette.field);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted(boxLabel, 208, 49, 196, 1);
  fireRedText.setTextDatum(TL_DATUM);
  if (!showingParty) {
    if (sdReady) {
      AssetRenderer::draw(display, "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_00.pkg", 106, 41);
      AssetRenderer::draw(display, "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_01.pkg", 302, 41);
    } else {
      display.fillTriangle(108, 49, 116, 43, 116, 55, TFT_WHITE);
      display.fillTriangle(306, 49, 298, 43, 298, 55, TFT_WHITE);
    }
  }

  display.fillRoundRect(kBoxGridX - 2, kBoxGridY - 1,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChromeDark);
  display.fillRoundRect(kBoxGridX - 3, kBoxGridY - 3,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChrome);
  display.fillRoundRect(kBoxGridX, kBoxGridY,
                        kBoxGridW, kBoxGridH, 5, boxPalette.field);
  // The bright coloured wallpaper keeps FireRed's subtle irregular tile
  // pattern. The dots stay below icons and give the same dense PC texture without a
  // visible modern grid between every slot.
  for (int16_t y = kBoxGridY + 8; y < kBoxGridY + kBoxGridH; y += 16)
    for (int16_t x = kBoxGridX + 9 + ((y / 16) & 1) * 7; x < kBoxGridX + kBoxGridW; x += 19)
      display.fillRect(x, y, 2, 2, boxPalette.dot);
  display.drawRoundRect(kBoxGridX - 1, kBoxGridY - 1,
                        kBoxGridW + 2, kBoxGridH + 2, 5, boxPalette.border);

  if (showingParty) {
    // The original Party menu uses saturated cyan strips. On the smaller TFT
    // those strips merged with the mini sprites, so keep its blue family as a
    // backdrop but put every member on a separate bright FireRed-style card.
    // This makes a party readable at a glance, particularly for dark Pokémon
    // sprites such as Gastly, Zubat and the shiny palette variants.
    const uint16_t partyBackdrop = themePale();
    const uint16_t partyStripe = themeAccent();
    const uint16_t partyFrame = 0x4C5C;
    const uint16_t partyCard = 0xEFFF;
    const uint16_t partySelectedCard = 0xFFF2;
    const uint16_t partySelectedFrame = 0xFD60;
    const uint16_t partyIconPad = 0xFFFF;
    display.fillRoundRect(kBoxGridX, kBoxGridY, kBoxGridW, kBoxGridH,
                          5, partyBackdrop);
    for (int16_t y = kBoxGridY + 3; y < kBoxGridY + kBoxGridH; y += 6)
      display.drawFastHLine(kBoxGridX + 2, y, kBoxGridW - 4, partyStripe);
    for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
      const int16_t y = boxPartyRowY(slot);
      const bool activeSlot = slot == gameSave.activePetSlot;
      const uint16_t panel = activeSlot ? partySelectedCard : partyCard;
      const uint16_t frame = activeSlot ? partySelectedFrame : partyFrame;
      display.fillRoundRect(kBoxGridX + 8, y + 2, kBoxGridW - 14, 37, 6, 0x4228);
      display.fillRoundRect(kBoxGridX + 7, y, kBoxGridW - 14, 37, 6, frame);
      display.fillRoundRect(kBoxGridX + 10, y + 3, kBoxGridW - 20, 33, 4, panel);
      // A plain white pad gives the 32x32 FireRed party sprite a reliable
      // silhouette regardless of the card or of the Pokémon's own colours.
      display.fillRoundRect(kBoxGridX + 13, y + 4, 36, 29, 4, partyIconPad);
      display.drawRoundRect(kBoxGridX + 13, y + 4, 36, 29, 4, frame);
      if (activeSlot) display.fillCircle(kBoxGridX + 15, y + 6, 3, 0xFD60);
      OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
      if (pokemon) {
        const SpeciesData* data = findSpecies(pokemon->speciesId);
        char iconPath[112];
        pokemonAssetPath(iconPath, sizeof(iconPath), *pokemon,
                         PokemonAssetView::Icon, 0U);
        if (!AssetRenderer::draw(display, iconPath, kBoxGridX + 12, y + 2))
          creature(kBoxGridX + 28, y + 18, *pokemon, false);
        drawPokemonGenderSymbol(*pokemon, kBoxGridX + 44, y + 11);
        char label[42];
        std::snprintf(label, sizeof(label), "%s", data ? data->name : "PKMN");
        fireRedText.setTextColor(TFT_DARKGREY, panel);
        fireRedText.drawStringAuto(label, kBoxGridX + 53, y + 3, 92);
        std::snprintf(label, sizeof(label), "Lv%u", pokemon->level);
        fireRedText.setTextColor(TFT_DARKGREY, panel);
        fireRedText.drawStringFitted(label, kBoxGridX + 53, y + 19, 50, 2);
        drawBoxPartyHpMeter(*pokemon, y, panel);
      } else {
        fireRedText.setTextColor(TFT_DARKGREY, panel);
        fireRedText.drawString("EMPTY", kBoxGridX + 55, y + 12, 2);
      }
      if (boxOverlay == BoxOverlay::PartyTarget) {
        drawBoxMoveHereBadge(y, panel, frame);
      } else if (boxOverlay == BoxOverlay::SoftBoiledTarget) {
        drawBoxHealBadge(y, panel, frame);
      }
    }
  } else {
    // Storage positions are physical: blank cells stay blank, and MOVE can
    // therefore put a Pokémon in any visible cell (or in another Box) just
    // like FireRed rather than silently repacking the collection.
    const uint16_t first = static_cast<uint16_t>(boxPage) * kBoxPageSize;
    const uint16_t last = std::min<uint16_t>(kBoxCapacity, first + kBoxPageSize);
    for (uint16_t index = first; index < last; ++index) {
      const OwnedPokemon& pokemon = gameSave.collection.box[index];
      const uint8_t cell = static_cast<uint8_t>(index - first);
      const int16_t x = kBoxGridX + 2 + (cell % 6) * kBoxCellW;
      const int16_t y = kBoxGridY - 1 + (cell / 6) * kBoxCellH;
      if (!pokemon.uid) continue;
      char path[112];
      pokemonAssetPath(path, sizeof(path), pokemon, PokemonAssetView::Icon, 0);
      if (!sdReady || !AssetRenderer::draw(display, path, x, y, false))
        creature(x+16,y+16,pokemon,false);
      if (pokemon.uid == selectedUid) {
        if (!sdReady || !AssetRenderer::draw(display,
              "/pokegochi/assets/firered/pokemon_storage/cursor_00.pkg", x - 7, y - 8))
          display.fillTriangle(x + 3, y + 3, x + 11, y + 8, x + 3, y + 13, TFT_WHITE);
      }
    }
  }

  char defaultFooter[44];
  if (boxNotice[0]) {
    std::snprintf(defaultFooter, sizeof(defaultFooter), "%s", boxNotice);
  } else if (boxOverlay == BoxOverlay::PartyTarget) {
    std::snprintf(defaultFooter, sizeof(defaultFooter), "MOVE %s TO A PARTY SLOT.",
                  selectedData ? selectedData->name : "POKEMON");
  } else if (boxOverlay == BoxOverlay::SoftBoiledTarget) {
    std::snprintf(defaultFooter, sizeof(defaultFooter), "CHOOSE A PARTY POKEMON TO HEAL.");
  } else if (boxOverlay == BoxOverlay::BoxMoveTarget) {
    std::snprintf(defaultFooter, sizeof(defaultFooter), "CHOOSE A DESTINATION IN BOX %u.", boxPage + 1U);
  } else if(boxOverlay==BoxOverlay::InventoryTarget){
    std::snprintf(defaultFooter,sizeof(defaultFooter),"USE %s ON WHICH POKEMON?",
                  inventoryEntryName(selectedInventoryEntry()));
  } else if (selectedData) {
    std::snprintf(defaultFooter, sizeof(defaultFooter), "%s is selected.", selectedData->name);
  } else std::snprintf(defaultFooter, sizeof(defaultFooter), "NO POKEMON is selected.");
  drawBoxFooter(defaultFooter);
  if (boxOverlay == BoxOverlay::Actions || boxOverlay == BoxOverlay::ReleaseConfirm ||
      boxOverlay == BoxOverlay::FormSelect)
    drawBoxContextMenu(selected);
  else if (boxOverlay == BoxOverlay::SortSelect)
    drawBoxSortMenu();
}

// The PC's left data card and storage field are independent dynamic regions.
// Keeping them separate is important on the CYD: opening/cancelling MOVE used
// to call drawBox(), blank the complete display, then stream every icon again.
void drawBoxPreviewPanel() {
  const OwnedPokemon* selected = CollectionLogic::find(gameSave.collection, selectedUid);
  const SpeciesData* selectedData = selected ? findSpecies(selected->speciesId) : nullptr;
  drawBoxPreviewPanelContents(selected, selectedData);
}

void drawBoxStorageHeader() {
  constexpr uint16_t kChrome = 0x6B4D;
  constexpr uint16_t kChromeDark = 0x4228;
  const BoxPalette& palette = currentBoxPalette();
  drawBoxTopButton(kBoxPartyButtonX, kBoxPartyButtonW, "PARTY", 0xB7F5);
  drawBoxTopButton(kBoxSortButtonX, kBoxSortButtonW, "SORT", 0xFFEE);
  drawBoxTopButton(kBoxCloseButtonX, kBoxCloseButtonW, "CLOSE BOX", themePale());
  display.fillRoundRect(102, 36, 214, 30, 6, kChromeDark);
  drawGbaInsetPanel(101, 34, 214, 30, 6, kChrome,
                    palette.field, palette.ribbon);
  char label[24]; std::snprintf(label, sizeof(label), "BOX %u", boxPage + 1U);
  fireRedText.setTextColor(TFT_DARKGREY, palette.field);
  fireRedText.setTextDatum(MC_DATUM); fireRedText.drawStringFitted(label, 208, 49, 196, 1); fireRedText.setTextDatum(TL_DATUM);
  if (sdReady) {
    AssetRenderer::draw(display, "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_00.pkg", 106, 41);
    AssetRenderer::draw(display, "/pokegochi/assets/firered/pokemon_storage/box_scroll_arrow_01.pkg", 302, 41);
  } else {
    display.fillTriangle(108, 49, 116, 43, 116, 55, TFT_WHITE);
    display.fillTriangle(306, 49, 298, 43, 298, 55, TFT_WHITE);
  }
}

void redrawBoxStorageField() {
  // Party has a different full-height card layout. Its toggle is treated as
  // as a local surface transition; callers route it through
  // refreshBoxPartySurface() rather than rebuilding the display.
  if (boxPartyView || boxOverlay == BoxOverlay::PartyTarget ||
      boxOverlay == BoxOverlay::SoftBoiledTarget) return;
  constexpr uint16_t kChrome = 0x6B4D;
  constexpr uint16_t kChromeDark = 0x4228;
  const BoxPalette& palette = currentBoxPalette();
  display.fillRoundRect(kBoxGridX - 2, kBoxGridY - 1,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChromeDark);
  display.fillRoundRect(kBoxGridX - 3, kBoxGridY - 3,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChrome);
  display.fillRoundRect(kBoxGridX, kBoxGridY,
                        kBoxGridW, kBoxGridH, 5, palette.field);
  for (int16_t y = kBoxGridY + 8; y < kBoxGridY + kBoxGridH; y += 16)
    for (int16_t x = kBoxGridX + 9 + ((y / 16) & 1) * 7; x < kBoxGridX + kBoxGridW; x += 19)
      display.fillRect(x, y, 2, 2, palette.dot);
  display.drawRoundRect(kBoxGridX - 1, kBoxGridY - 1,
                        kBoxGridW + 2, kBoxGridH + 2, 5, palette.border);
  const uint16_t first = static_cast<uint16_t>(boxPage) * kBoxPageSize;
  const uint16_t last = std::min<uint16_t>(kBoxCapacity, first + kBoxPageSize);
  for (uint16_t index = first; index < last; ++index) {
    const OwnedPokemon& pokemon = gameSave.collection.box[index];
    if (!pokemon.uid) continue;
    const uint8_t cell = static_cast<uint8_t>(index - first);
    const int16_t x = kBoxGridX + 2 + (cell % 6) * kBoxCellW;
    const int16_t y = kBoxGridY - 1 + (cell / 6) * kBoxCellH;
    char path[112]; pokemonAssetPath(path, sizeof(path), pokemon, PokemonAssetView::Icon, 0);
    // Let a cold/missing entry refill the canonical PGA3 cache.  Passing
    // false here skipped that path and fell straight into the old purple
    // silhouette during retained Box repaints.
    if (!sdReady || !AssetRenderer::draw(display, path, x, y))
      creature(x+16,y+16,pokemon,false);
    if (pokemon.uid == selectedUid) {
      if (!sdReady || !AssetRenderer::draw(display, "/pokegochi/assets/firered/pokemon_storage/cursor_00.pkg", x - 7, y - 8))
        display.fillTriangle(x + 3, y + 3, x + 11, y + 8, x + 3, y + 13, TFT_WHITE);
    }
  }
}

void refreshBoxStorageSurface(bool refreshPreview) {
  if (boxPartyView || boxOverlay == BoxOverlay::PartyTarget ||
      boxOverlay == BoxOverlay::SoftBoiledTarget) return;
  // Selection, page changes and a return from Summary can all change or
  // displace the visible sprite set. Rebuild that set before touching any
  // display pixels so the local repaint is complete in its first frame.
  prepareBoxSceneAssets();
  if (refreshPreview) {
    drawBoxPreviewPanel();
  }
  drawBoxStorageHeader();
  redrawBoxStorageField();
  const OwnedPokemon* selected = CollectionLogic::find(gameSave.collection, selectedUid);
  const SpeciesData* selectedData = selected ? findSpecies(selected->speciesId) : nullptr;
  char footer[44];
  if (boxOverlay == BoxOverlay::BoxMoveTarget)
    std::snprintf(footer, sizeof(footer), "CHOOSE A DESTINATION IN BOX %u.", boxPage + 1U);
  else if(boxOverlay==BoxOverlay::InventoryTarget)
    std::snprintf(footer,sizeof(footer),"USE %s ON WHICH POKEMON?",
                  inventoryEntryName(selectedInventoryEntry()));
  else if (boxNotice[0]) std::snprintf(footer, sizeof(footer), "%s", boxNotice);
  else if (selectedData) std::snprintf(footer, sizeof(footer), "%s is selected.", selectedData->name);
  else std::snprintf(footer, sizeof(footer), "NO POKEMON is selected.");
  drawBoxFooter(footer);
  if (boxOverlay == BoxOverlay::Actions || boxOverlay == BoxOverlay::ReleaseConfirm ||
      boxOverlay == BoxOverlay::FormSelect) drawBoxContextMenu(selected);
  else if (boxOverlay == BoxOverlay::SortSelect) drawBoxSortMenu();
}

// The Party tab is not a new screen.  It replaces the Box field, header and
// footer only.  In particular it must not rebuild the left preview card or
// stream the whole storage view again whenever the player selects a member.
void refreshBoxPartySurface(bool refreshPreview) {
  constexpr uint16_t kChrome = 0x6B4D;
  constexpr uint16_t kChromeDark = 0x4228;
  constexpr uint16_t kPaper = 0xFFDF;
  const uint16_t kPartyBackdrop = themePale();
  const uint16_t kPartyStripe = themeAccent();
  constexpr uint16_t kPartyFrame = 0x4C5C;
  constexpr uint16_t kPartyCard = 0xEFFF;
  constexpr uint16_t kPartySelectedCard = 0xFFF2;
  constexpr uint16_t kPartySelectedFrame = 0xFD60;
  constexpr uint16_t kPartyIconPad = 0xFFFF;

  // Prepare the Party cards, all members and the selected preview as one
  // scene.  This replaces the former piecemeal preloads that accumulated old
  // icons until the renderer ran out of cache space.
  prepareBoxSceneAssets();

  if (refreshPreview) {
    drawBoxPreviewPanel();
  }
  char partyToggle[16];
  std::snprintf(partyToggle, sizeof(partyToggle), "BOX %02u", boxPage + 1U);
  drawBoxTopButton(kBoxPartyButtonX, kBoxPartyButtonW, partyToggle, 0xB7F5);
  drawBoxTopButton(kBoxSortButtonX, kBoxSortButtonW, "SORT", 0xFFEE);
  drawBoxTopButton(kBoxCloseButtonX, kBoxCloseButtonW, "CLOSE BOX", themePale());
  display.fillRoundRect(102, 36, 214, 30, 6, kChromeDark);
  drawGbaInsetPanel(101, 34, 214, 30, 6, kChrome, 0xB7F5, 0x8F70);
  fireRedText.setTextColor(TFT_DARKGREY, 0xB7F5);
  fireRedText.setTextDatum(MC_DATUM); fireRedText.drawString("PARTY POKEMON", 208, 49, 1); fireRedText.setTextDatum(TL_DATUM);

  display.fillRoundRect(kBoxGridX - 2, kBoxGridY - 1,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChromeDark);
  display.fillRoundRect(kBoxGridX - 3, kBoxGridY - 3,
                        kBoxGridW + 6, kBoxGridH + 6, 7, kChrome);
  display.fillRoundRect(kBoxGridX, kBoxGridY, kBoxGridW, kBoxGridH,
                        5, kPartyBackdrop);
  for (int16_t y = kBoxGridY + 3; y < kBoxGridY + kBoxGridH; y += 6)
    display.drawFastHLine(kBoxGridX + 2, y, kBoxGridW - 4, kPartyStripe);

  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) {
    const int16_t y = boxPartyRowY(slot);
    const bool activeSlot = slot == gameSave.activePetSlot;
    const uint16_t panel = activeSlot ? kPartySelectedCard : kPartyCard;
    const uint16_t frame = activeSlot ? kPartySelectedFrame : kPartyFrame;
    display.fillRoundRect(kBoxGridX + 8, y + 2, kBoxGridW - 14, 37, 6, 0x4228);
    display.fillRoundRect(kBoxGridX + 7, y, kBoxGridW - 14, 37, 6, frame);
    display.fillRoundRect(kBoxGridX + 10, y + 3, kBoxGridW - 20, 33, 4, panel);
    display.fillRoundRect(kBoxGridX + 13, y + 4, 36, 29, 4, kPartyIconPad);
    display.drawRoundRect(kBoxGridX + 13, y + 4, 36, 29, 4, frame);
    if (activeSlot) display.fillCircle(kBoxGridX + 15, y + 6, 3, 0xFD60);
    OwnedPokemon* pokemon = CollectionLogic::active(gameSave.collection, slot);
    if (pokemon) {
      const SpeciesData* data = findSpecies(pokemon->speciesId);
       char iconPath[112];
       pokemonAssetPath(iconPath, sizeof(iconPath), *pokemon,
                        PokemonAssetView::Icon, 0U);
       if (!AssetRenderer::draw(display, iconPath, kBoxGridX + 12, y + 2))
         creature(kBoxGridX + 28, y + 18, *pokemon, false);
      drawPokemonGenderSymbol(*pokemon, kBoxGridX + 44, y + 11);
      char label[42];
      fireRedText.setTextColor(TFT_DARKGREY, panel);
      std::snprintf(label, sizeof(label), "%s", data ? data->name : "PKMN");
      fireRedText.drawStringAuto(label, kBoxGridX + 53, y + 3, 92);
      std::snprintf(label, sizeof(label), "Lv%u", pokemon->level);
      fireRedText.drawStringFitted(label, kBoxGridX + 53, y + 19, 50, 2);
      drawBoxPartyHpMeter(*pokemon, y, panel);
    } else {
      fireRedText.setTextColor(TFT_DARKGREY, panel);
      fireRedText.drawString("EMPTY", kBoxGridX + 55, y + 12, 2);
    }
    if (boxOverlay == BoxOverlay::PartyTarget) {
      drawBoxMoveHereBadge(y, panel, frame);
    } else if (boxOverlay == BoxOverlay::SoftBoiledTarget) {
      drawBoxHealBadge(y, panel, frame);
    }
  }
  const OwnedPokemon* selected = CollectionLogic::find(gameSave.collection, selectedUid);
  const SpeciesData* selectedData = selected ? findSpecies(selected->speciesId) : nullptr;
  char footer[44];
  if (boxNotice[0]) std::snprintf(footer, sizeof(footer), "%s", boxNotice);
  else if (boxOverlay == BoxOverlay::PartyTarget)
    std::snprintf(footer, sizeof(footer), "MOVE %s TO A PARTY SLOT.", selectedData ? selectedData->name : "POKEMON");
  else if (boxOverlay == BoxOverlay::SoftBoiledTarget)
    std::snprintf(footer, sizeof(footer), "CHOOSE A PARTY POKEMON TO HEAL.");
  else if (selectedData) std::snprintf(footer, sizeof(footer), "%s is selected.", selectedData->name);
  else std::snprintf(footer, sizeof(footer), "NO POKEMON is selected.");
  drawBoxFooter(footer);

  // Party browsing uses the same action/confirmation overlays as storage.
  // Paint them here as part of the Party surface so opening, replacing and
  // dismissing a menu are all exact inverses of one another.
  if (boxOverlay == BoxOverlay::Actions ||
      boxOverlay == BoxOverlay::ReleaseConfirm ||
      boxOverlay == BoxOverlay::FormSelect)
    drawBoxContextMenu(selected);
}

void refreshBoxSurface(bool refreshPreview) {
  if (boxPartyView || boxOverlay == BoxOverlay::PartyTarget ||
      boxOverlay == BoxOverlay::SoftBoiledTarget) refreshBoxPartySurface(refreshPreview);
  else refreshBoxStorageSurface(refreshPreview);
}

bool prepareSinnohExpeditionAssets(SinnohSite site) {
  constexpr uint8_t kMaxIconCount = 32U;
  static uint16_t species[kMaxIconCount]{};
  // pokemonAssetPath's longest form-aware icon path fits in the same
  // 72-byte storage already used by the Box manifest.  The previous generic
  // 112-byte battle-path allowance wasted 1,280 bytes of permanent DRAM here
  // even though this screen requests icons only.
  static char iconPaths[kMaxIconCount][72]{};
  static const char* assets[kMaxIconCount + 1U]{};
  const uint8_t iconCount = SinnohExpedition::availableSpecies(
      site, species, kMaxIconCount);
  assets[0] = "/pokegochi/assets/sinnoh/underground/dirt.pkg";
  uint32_t sceneKey = 0x53494E4FUL ^ static_cast<uint32_t>(site);
  for (uint8_t index = 0; index < iconCount; ++index) {
    OwnedPokemon visual{};
    visual.speciesId = species[index];
    pokemonAssetPath(iconPaths[index], sizeof(iconPaths[index]), visual,
                     PokemonAssetView::Icon, 0U);
    assets[index + 1U] = iconPaths[index];
    sceneKey = (sceneKey * 16777619UL) ^ species[index];
  }
  // The final Rift uses a single message instead of a 107-icon wall.
  return prepareUiScene(sceneKey, assets, static_cast<uint8_t>(iconCount + 1U));
}

void drawSinnohExpedition() {
  SinnohExpedition::reconcile(gameSave.sinnoh, gameSave.gymProgress);
  reconcileRegionCompletionRewards();
  const uint8_t sinnohRewardNotice = static_cast<uint8_t>(sinnohNotice[55]);
  if (sinnohRewardNotice) {
    if (sinnohRewardNotice == 0x03U)
      std::snprintf(sinnohNotice, sizeof(sinnohNotice),
                    "SINNOH 100%%! PLATINUM + MASTER BALL!");
    else if (sinnohRewardNotice & 0x01U)
      std::snprintf(
          sinnohNotice, sizeof(sinnohNotice),
          (gameSave.sinnoh.rewardFlags &
           SinnohExpedition::kMasterBallRewardBit) != 0U
              ? "PLATINUM THEME UNLOCKED!"
              : "PLATINUM UNLOCKED! CLEAR EVERY EXPLORE.");
    else
      std::snprintf(sinnohNotice, sizeof(sinnohNotice),
                    "MASTER BALL RECEIVED!");
    sinnohNotice[55] = 0;
  }
  if (!SinnohExpedition::available(gameSave.gymProgress, gameSave.sinnoh)) {
    screen = Screen::Home;
    drawHome();
    return;
  }
  if (sinnohSiteCursor >= SinnohExpedition::kSiteCount)
    sinnohSiteCursor = static_cast<uint8_t>(SinnohExpedition::kSiteCount - 1U);
  const SinnohSite site = static_cast<SinnohSite>(sinnohSiteCursor);
  beginScreenPresentation(Screen::SinnohExpedition, 0x5A84);
  const bool assetsReady = prepareSinnohExpeditionAssets(site);
  if (!AssetRenderer::draw(display, "/pokegochi/assets/sinnoh/underground/dirt.pkg", 0, 40))
    display.fillRect(0, 40, 320, 160, 0x8C51);
  display.fillRect(0, 0, 320, 40, 0x2945);
  display.drawFastHLine(0, 39, 320, TFT_WHITE);
  button(7, 8, 52, 24, "BACK", TFT_DARKGREY);
  fireRedText.setTextColor(TFT_WHITE, 0x2945);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted("SINNOH EXPEDITIONS", 160, 15, 184, 2);
  char research[56];
  std::snprintf(research, sizeof(research),
                "RESEARCH %u  GYM %u/8  EXP %u/8",
                gameSave.sinnoh.research,
                SinnohExpedition::gymVictoryCount(gameSave.sinnoh),
                SinnohExpedition::exploredSiteCount(gameSave.sinnoh));
  fireRedText.drawStringFitted(research, 160, 30, 244, 1);
  fireRedText.setTextDatum(TL_DATUM);

  const bool unlocked = SinnohExpedition::isUnlocked(gameSave.sinnoh, site);
  const uint16_t frame = unlocked ? 0xD69A : 0x5AEB;
  const uint16_t paper = unlocked ? 0xF7DE : 0x39E7;

  // A single focused site gives every name and tagline a predictable area.
  // The side arrows make the eight-site expedition a small carousel instead
  // of squeezing four unrelated cards into 130px-wide boxes.
  drawGbaInsetPanel(36, 49, 248, 103, 8, frame, paper, TFT_WHITE);
  button(6, 82, 28, 48, "<", themePrimary());
  button(286, 82, 28, 48, ">", themePrimary());
  char locationLine[64];
  std::snprintf(locationLine, sizeof(locationLine), "%s - %s",
                SinnohExpedition::siteName(site),
                SinnohExpedition::siteTagline(site));
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(unlocked ? TFT_DARKGREY : TFT_LIGHTGREY, paper);
  fireRedText.drawStringFitted(locationLine, 160, 61, 226, 1);
  if (!unlocked) {
    fireRedText.setTextColor(TFT_RED, paper);
    char unlock[48];
    const uint8_t siteIndex = static_cast<uint8_t>(site);
    if (siteIndex && !SinnohExpedition::hasGymVictory(
                         gameSave.sinnoh,
                         static_cast<SinnohSite>(siteIndex - 1U))) {
      const SinnohGymDefinition* previous = SinnohExpedition::gymDefinition(
          static_cast<SinnohSite>(siteIndex - 1U));
      std::snprintf(unlock, sizeof(unlock), "LOCKED - BEAT %s FIRST",
                    previous ? previous->leader : "PREVIOUS GYM");
    } else {
      std::snprintf(unlock, sizeof(unlock), "LOCKED - NEED %u RESEARCH",
                    SinnohExpedition::unlockCost(site));
    }
    fireRedText.drawStringFitted(unlock, 160, 111, 226, 1);
  } else if (site == SinnohSite::DistortionRift) {
    fireRedText.setTextColor(TFT_DARKGREEN, paper);
    fireRedText.drawStringFitted("ALL SINNOH POKEMON", 160, 111, 226, 2);
  } else {
    constexpr uint8_t kIconsPerRow = 9U;
    uint16_t species[32]{};
    const uint8_t iconCount = SinnohExpedition::availableSpecies(
        site, species, static_cast<uint8_t>(sizeof(species) / sizeof(species[0])));
    for (uint8_t index = 0; index < iconCount; ++index) {
      OwnedPokemon visual{};
      visual.speciesId = species[index];
      char path[112];
      pokemonAssetPath(path, sizeof(path), visual, PokemonAssetView::Icon, 0U);
      const uint8_t row = static_cast<uint8_t>(index / kIconsPerRow);
      const uint8_t rowStart = static_cast<uint8_t>(row * kIconsPerRow);
      const uint8_t rowCount = std::min<uint8_t>(
          kIconsPerRow, static_cast<uint8_t>(iconCount - rowStart));
      const int16_t left = static_cast<int16_t>(160 - rowCount * 12);
      const int16_t centerX = static_cast<int16_t>(left +
          static_cast<int16_t>(index - rowStart) * 24 + 12);
      const int16_t centerY = static_cast<int16_t>(84 + row * 23);
      bool drawn = assetsReady && AssetRenderer::drawTransformed(
          display, path, centerX, centerY, 66U, 66U);
      if (!drawn) creature(centerX, centerY, visual, false);
    }
  }
  fireRedText.setTextDatum(TL_DATUM);

  display.fillRoundRect(36, 157, 248, 38, 7, 0x4228);
  display.fillRoundRect(38, 159, 244, 34, 5, 0xE73C);
  fireRedText.setTextColor(TFT_DARKGREY, 0xE73C);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted(sinnohNotice, 160, 169, 228, 1);
  const SinnohGymDefinition* gym = SinnohExpedition::gymDefinition(site);
  char actionHint[56];
  if (!unlocked)
    std::snprintf(actionHint, sizeof(actionHint), "UNLOCK THIS SITE TO REACH ITS GYM");
  else if (SinnohExpedition::hasGymVictory(gameSave.sinnoh, site))
    std::snprintf(actionHint, sizeof(actionHint), "%s - %s BADGE WON",
                  gym ? gym->leader : "LEADER", gym ? gym->badge : "GYM");
  else if (SinnohExpedition::gymChallengeAvailable(gameSave.sinnoh, site))
    std::snprintf(actionHint, sizeof(actionHint), "LEADER %s - %s BADGE",
                  gym ? gym->leader : "UNKNOWN", gym ? gym->badge : "GYM");
  else
    std::snprintf(actionHint, sizeof(actionHint), "DEFEAT THE PREVIOUS SINNOH LEADER");
  fireRedText.drawStringFitted(actionHint, 160, 183, 228, 1);
  fireRedText.setTextDatum(TL_DATUM);

  button(18, 204, 136, 31, "EXPLORE", unlocked ? TFT_DARKGREEN : TFT_DARKGREY);
  const bool gymReady = SinnohExpedition::gymChallengeAvailable(
      gameSave.sinnoh, site);
  const bool badgeWon = SinnohExpedition::hasGymVictory(gameSave.sinnoh, site);
  button(166, 204, 136, 31, badgeWon ? "BADGE WON" : "GYM",
         gymReady ? 0xA145 : TFT_DARKGREY);
}

