    for(uint8_t row=0;row<kMartVisibleRows;++row) if(inside(p,kMartListX,kMartRowY+row*kMartRowH,216,kMartRowH)){
      const uint8_t i=static_cast<uint8_t>(martListOffset+row);if(i>=kMartOfferCount)return;
      martSelection=i;martPurchaseQuantity=1;martSelectionArmed=false;martNotice[0]=0;martDescriptionScroll=0;refreshMartPanels();return;
    }
    return;
